import {
  Controller,
  Get,
  Post,
  Param,
  Query,
  HttpCode,
  HttpStatus,
} from '@nestjs/common';
import { AnalyticsService, AnalyticsFilterDto } from './analytics.service';

@Controller('analytics')
export class AnalyticsController {
  constructor(private readonly analyticsService: AnalyticsService) {}

  @Get('overview')
  async getOverview(
    @Query('platform') platform?: string,
    @Query('videoId') videoId?: string,
    @Query('dateRange')
    dateRange?: 'today' | 'last7days' | 'last30days' | 'last90days' | 'custom',
    @Query('startDate') startDate?: string,
    @Query('endDate') endDate?: string,
  ) {
    return this.analyticsService.getOverview({
      platform,
      videoId,
      dateRange,
      startDate,
      endDate,
    });
  }

  @Get('insights')
  async getContentInsights() {
    return this.analyticsService.getContentInsights();
  }

  @Get('top-performing')
  async getTopPerforming(
    @Query('platform') platform?: string,
    @Query('videoId') videoId?: string,
    @Query('dateRange')
    dateRange?: 'today' | 'last7days' | 'last30days' | 'last90days' | 'custom',
    @Query('startDate') startDate?: string,
    @Query('endDate') endDate?: string,
    @Query('sortBy')
    sortBy?: 'views' | 'likes' | 'comments' | 'shares' | 'engagementRate',
    @Query('limit') limit?: string,
  ) {
    return this.analyticsService.getTopPerforming({
      platform,
      videoId,
      dateRange,
      startDate,
      endDate,
      sortBy,
      limit: limit ? Number(limit) : 10,
    });
  }

  @Get('platforms/:platform')
  async getPlatformAnalytics(
    @Param('platform') platform: string,
    @Query('dateRange')
    dateRange?: 'today' | 'last7days' | 'last30days' | 'last90days' | 'custom',
    @Query('startDate') startDate?: string,
    @Query('endDate') endDate?: string,
  ) {
    return this.analyticsService.getOverview({
      platform: platform.toUpperCase(),
      dateRange,
      startDate,
      endDate,
    });
  }

  @Get('videos/:videoId')
  async getVideoAnalytics(@Param('videoId') videoId: string) {
    return this.analyticsService.getVideoAnalytics(videoId);
  }

  @Get('posts/:postId')
  async getPostAnalytics(@Param('postId') postId: string) {
    return this.analyticsService.getPostAnalytics(postId);
  }

  @Post('collect/:jobId')
  @HttpCode(HttpStatus.OK)
  async triggerCollection(@Param('jobId') jobId: string) {
    await this.analyticsService.collectSnapshotForJob(jobId);
    return {
      success: true,
      message: `Collected analytics snapshot for publish job ${jobId}`,
    };
  }
}

import { Test, TestingModule } from '@nestjs/testing';
import { AnalyticsService } from './analytics.service';
import { PrismaService } from '../database/prisma.service';
import { PublishingService } from '../publishing/publishing.service';
import { getQueueToken } from '@nestjs/bullmq';

describe('AnalyticsService', () => {
  let service: AnalyticsService;

  const mockPrismaService = {
    publishJob: {
      findUnique: jest.fn(),
      findMany: jest.fn(),
    },
    postAnalytics: {
      create: jest.fn(),
    },
  };

  const mockPublishingService = {
    getAdapter: jest.fn().mockReturnValue({
      fetchAnalytics: jest.fn().mockResolvedValue({
        views: 5000,
        likes: 250,
        comments: 15,
        shares: 8,
        saves: 4,
        clicks: 0,
        engagementRate: 0.055,
      }),
    }),
  };

  const mockQueue = {
    add: jest.fn().mockResolvedValue({ id: 'analytics-job-1' }),
  };

  beforeEach(async () => {
    const module: TestingModule = await Test.createTestingModule({
      providers: [
        AnalyticsService,
        { provide: PrismaService, useValue: mockPrismaService },
        { provide: PublishingService, useValue: mockPublishingService },
        { provide: getQueueToken('analytics-queue'), useValue: mockQueue },
      ],
    }).compile();

    service = module.get<AnalyticsService>(AnalyticsService);
    jest.clearAllMocks();
  });

  describe('collectSnapshotForJob', () => {
    it('should create new PostAnalytics snapshot record without overwriting previous snapshots', async () => {
      mockPrismaService.publishJob.findUnique.mockResolvedValue({
        id: 'job-1',
        status: 'PUBLISHED',
        platformPostId: 'tiktok_post_1',
        platform: 'TIKTOK',
        platformAccount: { id: 'acc-1' },
      });

      await service.collectSnapshotForJob('job-1');

      expect(mockPrismaService.postAnalytics.create).toHaveBeenCalledWith({
        data: expect.objectContaining({
          publishJobId: 'job-1',
          platformPostId: 'tiktok_post_1',
          views: BigInt(5000),
          likes: 250,
          comments: 15,
          shares: 8,
        }),
      });
    });
  });

  describe('getOverview & Platform Comparison', () => {
    it('should calculate aggregated views, likes, avg views, and platform breakdown', async () => {
      mockPrismaService.publishJob.findMany.mockResolvedValue([
        {
          id: 'job-1',
          videoId: 'v-1',
          title: 'Video A',
          platform: 'TIKTOK',
          video: { id: 'v-1', title: 'Video A' },
          analyticsSnapshots: [
            { views: BigInt(120000), likes: 8000, comments: 300, shares: 100 },
          ],
        },
        {
          id: 'job-2',
          videoId: 'v-1',
          title: 'Video A',
          platform: 'YOUTUBE',
          video: { id: 'v-1', title: 'Video A' },
          analyticsSnapshots: [
            { views: BigInt(80000), likes: 5000, comments: 200, shares: 50 },
          ],
        },
      ]);

      const overview = await service.getOverview();

      expect(overview.totalVideosPublished).toEqual(2);
      expect(overview.totalViews).toEqual(200000);
      expect(overview.totalLikes).toEqual(13000);
      expect(overview.avgViewsPerVideo).toEqual(100000);
      expect(overview.bestPerformingPlatform?.platform).toEqual('TIKTOK');
      expect(overview.platformComparison).toHaveLength(4);
    });
  });
});

import { Injectable, Logger, NotFoundException } from '@nestjs/common';
import { InjectQueue } from '@nestjs/bullmq';
import { Queue } from 'bullmq';
import { PrismaService } from '../database/prisma.service';
import { PublishingService } from '../publishing/publishing.service';
import { PlatformType } from '../publishing/adapters/platform-adapter.interface';

export interface AnalyticsFilterDto {
  platform?: string;
  videoId?: string;
  dateRange?: 'today' | 'last7days' | 'last30days' | 'last90days' | 'custom';
  startDate?: string;
  endDate?: string;
  sortBy?: 'views' | 'likes' | 'comments' | 'shares' | 'engagementRate';
  limit?: number;
}

@Injectable()
export class AnalyticsService {
  private readonly logger = new Logger(AnalyticsService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly publishingService: PublishingService,
    @InjectQueue('analytics-queue') private readonly analyticsQueue: Queue,
  ) {}

  private getDateFilter(dto?: AnalyticsFilterDto) {
    if (!dto?.dateRange) return undefined;

    const now = new Date();
    let start: Date;

    switch (dto.dateRange) {
      case 'today':
        start = new Date(now.setHours(0, 0, 0, 0));
        break;
      case 'last7days':
        start = new Date(Date.now() - 7 * 24 * 3600 * 1000);
        break;
      case 'last30days':
        start = new Date(Date.now() - 30 * 24 * 3600 * 1000);
        break;
      case 'last90days':
        start = new Date(Date.now() - 90 * 24 * 3600 * 1000);
        break;
      case 'custom':
        start = dto.startDate ? new Date(dto.startDate) : new Date(0);
        break;
      default:
        return undefined;
    }

    const end =
      dto.dateRange === 'custom' && dto.endDate
        ? new Date(dto.endDate)
        : new Date();
    return { gte: start, lte: end };
  }

  // --- SNAPSHOT COLLECTION ---

  async collectSnapshotForJob(publishJobId: string): Promise<void> {
    const job = await this.prisma.publishJob.findUnique({
      where: { id: publishJobId },
      include: { platformAccount: true },
    });

    if (!job || job.status !== 'PUBLISHED' || !job.platformPostId) {
      this.logger.warn(
        `Skipping analytics collection for job ${publishJobId}: Job not published or missing post ID.`,
      );
      return;
    }

    try {
      const adapter = this.publishingService.getAdapter(
        job.platform as PlatformType,
      );
      const metrics = await adapter.fetchAnalytics(
        job.platformAccount,
        job.platformPostId,
      );

      await this.prisma.postAnalytics.create({
        data: {
          publishJobId: job.id,
          platformPostId: job.platformPostId,
          collectedAt: new Date(),
          views: BigInt(metrics.views || 0),
          likes: metrics.likes || 0,
          comments: metrics.comments || 0,
          shares: metrics.shares || 0,
          saves: metrics.saves || 0,
          clicks: metrics.clicks || 0,
          watchTime: metrics.watchTime,
          averageWatchTime: metrics.averageWatchTime,
          completionRate: metrics.completionRate,
          engagementRate: metrics.engagementRate,
          rawMetadata: metrics.rawMetadata || {},
        },
      });

      this.logger.log(
        `Created analytics snapshot for job ${publishJobId} (Views: ${metrics.views}, Likes: ${metrics.likes})`,
      );
    } catch (error: any) {
      this.logger.error(
        `Error collecting analytics snapshot for job ${publishJobId}: ${error.message}`,
        error.stack,
      );
    }
  }

  async scheduleNextSnapshot(publishJobId: string, currentInterval: string) {
    const intervals: Record<string, { nextLabel: string; delayMs: number }> = {
      '1h': { nextLabel: '6h', delayMs: 5 * 3600 * 1000 },
      '6h': { nextLabel: '24h', delayMs: 18 * 3600 * 1000 },
      '24h': { nextLabel: '48h', delayMs: 24 * 3600 * 1000 },
      '48h': { nextLabel: '7d', delayMs: 5 * 24 * 3600 * 1000 },
    };

    const next = intervals[currentInterval];
    if (next) {
      await this.analyticsQueue.add(
        'collect-analytics',
        { publishJobId, intervalLabel: next.nextLabel },
        { delay: next.delayMs },
      );
    }
  }

  // --- ANALYTICS APIS ---

  async getOverview(dto?: AnalyticsFilterDto) {
    const dateFilter = this.getDateFilter(dto);

    const whereJob: any = { status: 'PUBLISHED' };
    if (dto?.platform) whereJob.platform = dto.platform;
    if (dto?.videoId) whereJob.videoId = dto.videoId;

    const publishedJobs = await this.prisma.publishJob.findMany({
      where: whereJob,
      include: {
        video: true,
        analyticsSnapshots: {
          where: dateFilter ? { collectedAt: dateFilter } : undefined,
          orderBy: { collectedAt: 'desc' },
          take: 1, // latest snapshot per post
        },
      },
    });

    let totalViews = 0;
    let totalLikes = 0;
    let totalComments = 0;
    let totalShares = 0;

    const platformStats: Record<
      string,
      {
        videos: number;
        views: number;
        likes: number;
        comments: number;
        shares: number;
      }
    > = {
      TIKTOK: { videos: 0, views: 0, likes: 0, comments: 0, shares: 0 },
      YOUTUBE: { videos: 0, views: 0, likes: 0, comments: 0, shares: 0 },
      INSTAGRAM: { videos: 0, views: 0, likes: 0, comments: 0, shares: 0 },
      FACEBOOK: { videos: 0, views: 0, likes: 0, comments: 0, shares: 0 },
    };

    let bestVideo: { videoId: string; title: string; views: number } | null =
      null;
    let maxVideoViews = -1;

    const videoViewsMap: Record<string, { title: string; views: number }> = {};

    for (const job of publishedJobs) {
      const latestSnapshot = job.analyticsSnapshots[0];
      const views = latestSnapshot ? Number(latestSnapshot.views) : 0;
      const likes = latestSnapshot ? latestSnapshot.likes : 0;
      const comments = latestSnapshot ? latestSnapshot.comments : 0;
      const shares = latestSnapshot ? latestSnapshot.shares : 0;

      totalViews += views;
      totalLikes += likes;
      totalComments += comments;
      totalShares += shares;

      if (!platformStats[job.platform]) {
        platformStats[job.platform] = {
          videos: 0,
          views: 0,
          likes: 0,
          comments: 0,
          shares: 0,
        };
      }
      platformStats[job.platform].videos += 1;
      platformStats[job.platform].views += views;
      platformStats[job.platform].likes += likes;
      platformStats[job.platform].comments += comments;
      platformStats[job.platform].shares += shares;

      if (!videoViewsMap[job.videoId]) {
        videoViewsMap[job.videoId] = {
          title: job.title || job.video.title,
          views: 0,
        };
      }
      videoViewsMap[job.videoId].views += views;

      if (videoViewsMap[job.videoId].views > maxVideoViews) {
        maxVideoViews = videoViewsMap[job.videoId].views;
        bestVideo = {
          videoId: job.videoId,
          title: videoViewsMap[job.videoId].title,
          views: maxVideoViews,
        };
      }
    }

    let bestPlatform: string | null = null;
    let maxPlatformViews = -1;
    for (const [p, stats] of Object.entries(platformStats)) {
      if (stats.views > maxPlatformViews && stats.videos > 0) {
        maxPlatformViews = stats.views;
        bestPlatform = p;
      }
    }

    const totalVideosPublished = publishedJobs.length;
    const avgViewsPerVideo =
      totalVideosPublished > 0
        ? Math.round(totalViews / totalVideosPublished)
        : 0;
    const engagementRate =
      totalViews > 0
        ? (totalLikes + totalComments + totalShares) / totalViews
        : 0;

    return {
      totalVideosPublished,
      totalViews,
      totalLikes,
      totalComments,
      totalShares,
      totalEngagement: totalLikes + totalComments + totalShares,
      avgViewsPerVideo,
      engagementRate,
      bestPerformingVideo: bestVideo,
      bestPerformingPlatform: bestPlatform
        ? { platform: bestPlatform, views: maxPlatformViews }
        : null,
      platformComparison: Object.entries(platformStats).map(
        ([platform, stats]) => ({
          platform,
          videos: stats.videos,
          views: stats.views,
          likes: stats.likes,
          comments: stats.comments,
          shares: stats.shares,
          avgViews:
            stats.videos > 0 ? Math.round(stats.views / stats.videos) : 0,
          engagementRate:
            stats.views > 0
              ? (stats.likes + stats.comments + stats.shares) / stats.views
              : 0,
        }),
      ),
    };
  }

  async getTopPerforming(dto?: AnalyticsFilterDto) {
    const limit = dto?.limit || 10;
    const dateFilter = this.getDateFilter(dto);

    const whereJob: any = { status: 'PUBLISHED' };
    if (dto?.platform) whereJob.platform = dto.platform;
    if (dto?.videoId) whereJob.videoId = dto.videoId;

    const publishedJobs = await this.prisma.publishJob.findMany({
      where: whereJob,
      include: {
        video: true,
        platformAccount: { select: { platform: true, accountName: true } },
        analyticsSnapshots: {
          where: dateFilter ? { collectedAt: dateFilter } : undefined,
          orderBy: { collectedAt: 'desc' },
          take: 1,
        },
      },
    });

    const items = publishedJobs.map((job) => {
      const snap = job.analyticsSnapshots[0];
      const views = snap ? Number(snap.views) : 0;
      const likes = snap ? snap.likes : 0;
      const comments = snap ? snap.comments : 0;
      const shares = snap ? snap.shares : 0;
      const engagementRate =
        views > 0 ? (likes + comments + shares) / views : 0;

      return {
        jobId: job.id,
        videoId: job.videoId,
        title: job.title || job.video.title,
        platform: job.platform,
        accountName: job.platformAccount.accountName,
        platformPostId: job.platformPostId,
        platformUrl: job.platformUrl,
        publishedAt: job.publishedAt,
        views,
        likes,
        comments,
        shares,
        engagementRate,
      };
    });

    const sortBy = dto?.sortBy || 'views';
    items.sort((a, b) => b[sortBy] - a[sortBy]);

    return items.slice(0, limit);
  }

  async getVideoAnalytics(videoId: string) {
    const jobs = await this.prisma.publishJob.findMany({
      where: { videoId },
      include: {
        platformAccount: { select: { platform: true, accountName: true } },
        analyticsSnapshots: {
          orderBy: { collectedAt: 'asc' },
        },
      },
    });

    if (jobs.length === 0) {
      throw new NotFoundException(
        `No publishing records found for video ID ${videoId}`,
      );
    }

    return jobs.map((job) => ({
      jobId: job.id,
      platform: job.platform,
      accountName: job.platformAccount.accountName,
      platformPostId: job.platformPostId,
      platformUrl: job.platformUrl,
      publishedAt: job.publishedAt,
      status: job.status,
      snapshots: job.analyticsSnapshots.map((s) => ({
        id: s.id,
        collectedAt: s.collectedAt,
        views: Number(s.views),
        likes: s.likes,
        comments: s.comments,
        shares: s.shares,
        saves: s.saves,
        engagementRate: s.engagementRate,
      })),
    }));
  }

  async getPostAnalytics(publishJobId: string) {
    const job = await this.prisma.publishJob.findUnique({
      where: { id: publishJobId },
      include: {
        video: true,
        platformAccount: { select: { platform: true, accountName: true } },
        analyticsSnapshots: {
          orderBy: { collectedAt: 'asc' },
        },
      },
    });

    if (!job) {
      throw new NotFoundException(
        `Publish job with ID ${publishJobId} not found.`,
      );
    }

    return {
      jobId: job.id,
      videoId: job.videoId,
      videoTitle: job.video.title,
      platform: job.platform,
      accountName: job.platformAccount.accountName,
      platformPostId: job.platformPostId,
      platformUrl: job.platformUrl,
      publishedAt: job.publishedAt,
      snapshots: job.analyticsSnapshots.map((s) => ({
        id: s.id,
        collectedAt: s.collectedAt,
        views: Number(s.views),
        likes: s.likes,
        comments: s.comments,
        shares: s.shares,
        saves: s.saves,
        engagementRate: s.engagementRate,
      })),
    };
  }

  async getContentInsights() {
    const publishedJobs = await this.prisma.publishJob.findMany({
      where: { status: 'PUBLISHED' },
      include: {
        video: {
          include: {
            idea: {
              include: {
                product: {
                  include: {
                    contentIdeas: true,
                  },
                },
              },
            },
          },
        },
        analyticsSnapshots: {
          orderBy: { collectedAt: 'desc' },
          take: 1,
        },
      },
    });

    const angleStats: Record<
      string,
      { views: number; count: number; likes: number }
    > = {};
    let totalViews = 0;
    let totalPosts = 0;

    for (const job of publishedJobs) {
      const snap = job.analyticsSnapshots[0];
      const views = snap ? Number(snap.views) : 0;
      const likes = snap ? snap.likes : 0;
      totalViews += views;
      totalPosts++;

      // Match angle/contentType from associated idea or product
      const idea = job.video?.idea;
      const matchedIdea = idea?.product?.contentIdeas.find(
        (ci) =>
          ci.title === idea.title ||
          idea.description?.includes(ci.marketingAngle),
      );

      const angleKey =
        matchedIdea?.contentType ||
        matchedIdea?.marketingAngle ||
        'product_review';

      if (!angleStats[angleKey]) {
        angleStats[angleKey] = { views: 0, count: 0, likes: 0 };
      }
      angleStats[angleKey].views += views;
      angleStats[angleKey].count += 1;
      angleStats[angleKey].likes += likes;
    }

    const overallAvgViews = totalPosts > 0 ? totalViews / totalPosts : 0;

    const angleInsights = Object.entries(angleStats).map(([angle, stats]) => {
      const avgViews =
        stats.count > 0 ? Math.round(stats.views / stats.count) : 0;
      const performanceMultiplier =
        overallAvgViews > 0
          ? Number((avgViews / overallAvgViews).toFixed(2))
          : 1;

      return {
        contentType: angle,
        totalPosts: stats.count,
        totalViews: stats.views,
        avgViews,
        performanceMultiplier,
        recommendation:
          performanceMultiplier >= 1.2
            ? `Góc nhìn "${angle}" đạt trung bình ${avgViews.toLocaleString()} lượt xem (${Math.round((performanceMultiplier - 1) * 100)}% cao hơn trung bình). Khuyên dùng tiếp tục nhân bản!`
            : `Góc nhìn "${angle}" đang đạt mức hiệu suất bình thường (${avgViews.toLocaleString()} views/video).`,
      };
    });

    angleInsights.sort((a, b) => b.avgViews - a.avgViews);

    const topAngle = angleInsights[0];

    return {
      totalPostsAnalyzed: totalPosts,
      totalViewsAnalyzed: totalViews,
      overallAvgViews: Math.round(overallAvgViews),
      topPerformingAngle: topAngle ? topAngle.contentType : 'product_review',
      insights: angleInsights,
      recommendedNextSteps: topAngle
        ? [
            `Tập trung tạo thêm 3-5 video mới sử dụng định dạng nội dung "${topAngle.contentType}".`,
            `Thử nghiệm kết hợp Hook mở đầu của video hot nhất với sản phẩm cùng danh mục.`,
          ]
        : [
            'Tiếp tục đăng thêm video để hệ thống tích lũy đủ dữ liệu phân tích.',
          ],
    };
  }
}

import {
  Injectable,
  Logger,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';
import { PrismaService } from '../database/prisma.service';
import { LlmService } from '../llm/llm.service';
import { QueueService, type VideoJobConfig } from '../queue/queue.service';
import { InjectQueue } from '@nestjs/bullmq';
import { Queue } from 'bullmq';
import {
  CONTENT_TYPES,
  type ContentIdeaResponse,
  type ContentStrategyGenerateResult,
  type ContentStrategyJobPayload,
  type RawContentIdeaItem,
} from './types/content-idea.types';

const CONTENT_STRATEGY_PROMPT = `
Bạn là một Giám đốc Chiến lược Nội dung (Content Strategy Director) chuyên về video ngắn (TikTok, Facebook Reels, YouTube Shorts).
Dựa trên thông tin nghiên cứu sản phẩm đã được trích xuất thực tế dưới đây, hãy lập chiến lược nội dung và đề xuất từ 10 đến 20 Ý TƯỞNG NỘI DUNG (Content Ideas) khác nhau để làm video tiếp thị sản phẩm.

==================================================
QUY TẮC AN TOÀN AI VÀ TÍNH XÁC THỰC DỮ LIỆU (FACTUAL ACCURACY):
==================================================
1. KHÔNG ĐƯỢC TỰ BỊA TẠO thông số kỹ thuật, giá cả, xuất xứ, chứng nhận, mô hình hay tính năng sản phẩm không có trong dữ liệu nghiên cứu.
2. TẤT CẢ thông tin thực tế về sản phẩm PHẢI xuất phát từ DỮ LIỆU NGHIÊN CỨU SẢN PHẨM bên dưới.
3. Phân biệt rõ:
   - DỮ LIỆU THỰC TẾ (Factual Product Data): Tính năng, lợi ích, giá, nhược điểm thực tế.
   - GÓC NHÌN SÁNG TẠO (Creative Angles): Cách tiếp cận khán giả, câu hỏi gợi mở, kịch bản tình huống.

==================================================
YÊU CẦU ĐA DẠNG NỘI DUNG (CONTENT DIVERSITY):
==================================================
Tạo ra 10 - 20 ý tưởng đa dạng góc nhìn. KHÔNG tạo các bài review lặp đi lặp lại.
Sử dụng đa dạng các loại contentType sau:
- product_review: Đánh giá tổng quan hoặc trải nghiệm
- problem_solution: Đặt vấn đề nỗi đau và giải pháp
- comparison: So sánh với phương pháp cũ hoặc giải pháp khác
- listicle: Danh sách (Top 3 lý do, 3 mẹo...)
- educational: Hướng dẫn mẹo sử dụng, kiến thức hữu ích
- storytelling: Câu chuyện thực tế/tình huống thường gặp
- testimonial: Góc nhìn người dùng phản hồi
- myth_busting: Giải mã hiểu lầm phổ biến
- use_case: Kịch bản sử dụng thực tế theo hoàn cảnh
- value_for_money: Phân tích đáng tiền hay không
- pros_cons: Phân tích ưu nhược điểm thẳng thắn
- FAQ: Giải đáp thắc mắc thường gặp

==================================================
CẤU TRÚC MỖI Ý TƯỞNG (IDEA QUALITY):
==================================================
Mỗi ý tưởng trong mảng JSON phải chứa đúng các trường:
1. title: Tiêu đề video cụ thể, hấp dẫn, tò mò (không dùng tiêu đề chung chung)
2. description: Mô tả chi tiết nội dung video và kịch bản bối cảnh hình ảnh
3. contentType: Một trong các giá trị enum nêu trên
4. marketingAngle: Góc độ tiếp thị khai thác (ví dụ: tiết kiệm thời gian, tối ưu chi phí, sự tiện lợi)
5. targetAudience: Đối tượng người xem cụ thể hướng tới
6. painPoint: Nỗi đau hoặc vấn đề người xem đang gặp phải
7. keyMessage: Thông điệp cốt lõi cần truyền tải
8. hook: Câu mở đầu (Hook) gây chú ý mạnh trong 3-5 giây đầu (dưới 15 từ)
9. recommendedCTA: Kêu gọi hành động phù hợp (CTA)
10. priority: Mức độ ưu tiên thương mại từ 1 đến 5 (1 = cao nhất)

DỮ LIỆU NGHIÊN CỨU SẢN PHẨM:
---
{PRODUCT_RESEARCH_DATA}
---

Yêu cầu trả về duy nhất một mảng JSON thuần túy (JSON Array), KHÔNG chứa văn bản giải thích bên ngoài, KHÔNG bọc trong markdown block.
Ví dụ định dạng trả về:
[
  {
    "title": "2.5 triệu mua nồi Philips có đáng không?",
    "description": "Video phân tích thực tế dành cho gia đình nhỏ băn khoăn về giá trị sử dụng so với số tiền bỏ ra.",
    "contentType": "value_for_money",
    "marketingAngle": "Phân tích giá trị sử dụng thực tế",
    "targetAudience": "Gia đình nhỏ và người đi làm bận rộn",
    "painPoint": "Không biết có nên bỏ số tiền lớn cho nồi chiên không",
    "keyMessage": "Giá trị bền bỉ và tiện lợi hoàn toàn xứng đáng với mức giá",
    "hook": "2.5 triệu cho một chiếc nồi chiên, liệu có thực sự đáng tiền?",
    "recommendedCTA": "Bấm vào link bên dưới để xem ưu đãi giá mới nhất",
    "priority": 1
  }
]
`.trim();

@Injectable()
export class ContentStrategyService {
  private readonly logger = new Logger(ContentStrategyService.name);

  constructor(
    private prisma: PrismaService,
    private llmService: LlmService,
    private queueService: QueueService,
    @InjectQueue('content-strategy')
    private strategyQueue?: Queue<ContentStrategyJobPayload>,
  ) {}

  /**
   * Main entrypoint for content idea generation.
   * Can be enqueued or executed directly.
   */
  async generateContentIdeas(
    productId: string,
  ): Promise<ContentStrategyGenerateResult> {
    this.logger.log(
      `[ContentStrategy] Starting idea generation for productId=${productId}`,
    );

    const product = await this.prisma.product.findUnique({
      where: { id: productId },
    });

    if (!product) {
      throw new NotFoundException('Không tìm thấy sản phẩm');
    }

    let jobId: string | undefined;

    // Enqueue if BullMQ queue is connected
    if (this.strategyQueue) {
      try {
        const job = await this.strategyQueue.add(
          'generate-content-ideas',
          { productId },
          {
            attempts: 2,
            backoff: 5000,
            removeOnComplete: 100,
            removeOnFail: 200,
          },
        );
        jobId = job.id;
        this.logger.log(
          `[Worker] Enqueued content strategy job ${jobId} for product ${productId}`,
        );
      } catch (queueErr) {
        this.logger.warn(
          `[Worker] Redis queue enqueue failed, executing content strategy inline: ${queueErr}`,
        );
      }
    }

    try {
      const ideas = await this.executeStrategyPipeline(productId);

      return {
        success: true,
        jobId,
        count: ideas.length,
        ideas,
      };
    } catch (err) {
      this.logger.error(
        `[ContentStrategy] Top-level failure in generateContentIdeas: ${err}`,
      );
      if (err instanceof NotFoundException) throw err;
      throw new BadRequestException(
        'Không thể khởi tạo ý tưởng nội dung. Vui lòng kiểm tra lại dữ liệu sản phẩm.',
      );
    }
  }

  /**
   * AI Strategy Pipeline execution:
   * Build research context -> Query LLM -> Parse & Validate JSON -> Persist ideas
   */
  async executeStrategyPipeline(
    productId: string,
  ): Promise<ContentIdeaResponse[]> {
    try {
      const product = await this.prisma.product.findUnique({
        where: { id: productId },
      });

      if (!product) {
        throw new NotFoundException('Không tìm thấy sản phẩm');
      }

      const { provider, apiKey, model } =
        await this.llmService.getActiveProviderConfig();

      let rawIdeas: RawContentIdeaItem[] = [];

      if (apiKey) {
        try {
          const researchContext = this.buildResearchContext(product);
          const prompt = CONTENT_STRATEGY_PROMPT.replace(
            '{PRODUCT_RESEARCH_DATA}',
            researchContext,
          );
          const responseText = await this.callLlm(
            provider,
            apiKey,
            model,
            prompt,
          );
          rawIdeas = this.parseAndValidateResponse(responseText);
        } catch (err) {
          this.logger.warn(
            `[ContentStrategy] LLM API call or context building failed (${err instanceof Error ? err.message : String(err)}). Falling back to rule-based research synthesis.`,
          );
        }
      } else {
        this.logger.warn(
          '[ContentStrategy] No LLM API key configured. Using rule-based research synthesis fallback.',
        );
      }

      if (rawIdeas.length === 0) {
        rawIdeas = this.buildFallbackIdeas(product);
      }

      // Clear old draft ideas for this product if re-generating (catch DB error if linked scripts exist)
      try {
        await this.prisma.contentIdea.deleteMany({
          where: { productId, status: 'draft' },
        });
      } catch (dbErr) {
        this.logger.warn(
          `[ContentStrategy] Unable to clear previous draft ideas for product ${productId}: ${dbErr}`,
        );
      }

      // Save newly generated ideas into DB with safe individual creation
      const savedIdeas = [];
      for (let index = 0; index < rawIdeas.length; index++) {
        const item = rawIdeas[index];
        try {
          const created = await this.prisma.contentIdea.create({
            data: {
              productId,
              title: item.title || 'Ý tưởng nội dung',
              description: item.description || item.title || 'Mô tả ý tưởng',
              contentType: this.normalizeContentType(item.contentType),
              marketingAngle: item.marketingAngle || 'Tổng quan',
              targetAudience: item.targetAudience || 'Khách hàng mục tiêu',
              painPoint: item.painPoint || 'Vấn đề thực tế',
              keyMessage: item.keyMessage || item.title || 'Thông điệp cốt lõi',
              hook: item.hook || item.title || 'Hook mở đầu',
              recommendedCTA: item.recommendedCTA || 'Xem thêm chi tiết',
              priority:
                item.priority && item.priority >= 1 && item.priority <= 5
                  ? item.priority
                  : (index % 5) + 1,
              status: 'draft',
            },
          });
          savedIdeas.push(created);
        } catch (createErr) {
          this.logger.error(
            `[ContentStrategy] Failed to persist idea index ${index} for product ${productId}: ${createErr}`,
          );
        }
      }

      this.logger.log(
        `[ContentStrategy] Successfully created ${savedIdeas.length} content ideas for product ${productId}`,
      );

      return savedIdeas.map((idea) => this.mapToResponse(idea));
    } catch (topErr) {
      this.logger.error(
        `[ContentStrategy] Unhandled exception in executeStrategyPipeline for productId=${productId}: ${topErr}`,
      );
      if (topErr instanceof NotFoundException) throw topErr;
      const product = await this.prisma.product.findUnique({
        where: { id: productId },
      });
      if (!product) throw new NotFoundException('Không tìm thấy sản phẩm');
      const fallbackIdeas = this.buildFallbackIdeas(product);
      return fallbackIdeas.map((item, index) => ({
        id: `fallback-${Date.now()}-${index}`,
        productId,
        title: item.title,
        description: item.description,
        contentType: item.contentType,
        marketingAngle: item.marketingAngle,
        targetAudience: item.targetAudience,
        painPoint: item.painPoint,
        keyMessage: item.keyMessage,
        hook: item.hook,
        recommendedCTA: item.recommendedCTA,
        priority: item.priority ?? index + 1,
        status: 'draft',
        createdAt: new Date(),
        updatedAt: new Date(),
      }));
    }
  }

  async getContentIdeasByProduct(
    productId: string,
  ): Promise<ContentIdeaResponse[]> {
    const ideas = await this.prisma.contentIdea.findMany({
      where: { productId },
      orderBy: [{ priority: 'asc' }, { createdAt: 'desc' }],
    });
    return ideas.map((idea) => this.mapToResponse(idea));
  }

  async getContentIdeaById(id: string): Promise<ContentIdeaResponse> {
    const idea = await this.prisma.contentIdea.findUnique({
      where: { id },
    });
    if (!idea) {
      throw new NotFoundException('Không tìm thấy ý tưởng nội dung');
    }
    return this.mapToResponse(idea);
  }

  async deleteContentIdea(id: string): Promise<{ success: boolean }> {
    await this.getContentIdeaById(id);
    await this.prisma.contentIdea.delete({
      where: { id },
    });
    return { success: true };
  }

  /**
   * Content Idea -> Video Generation Integration:
   * Selects a ContentIdea, converts it into a full script context with Product + Brief,
   * creates an Idea and GenerationJob record, and triggers BullMQ Video Processor.
   */
  async generateVideoFromIdea(
    contentIdeaId: string,
    config: VideoJobConfig = {},
  ) {
    const contentIdea = await this.prisma.contentIdea.findUnique({
      where: { id: contentIdeaId },
      include: { product: true },
    });

    if (!contentIdea) {
      throw new NotFoundException('Không tìm thấy ý tưởng nội dung');
    }

    const product = contentIdea.product;

    // Build complete context combining Product Research + Content Idea Strategy
    const richScriptPrompt = `
[CONTENT STRATEGY & MARKETING ANGLE]
Title: ${contentIdea.title}
Content Type: ${contentIdea.contentType}
Marketing Angle: ${contentIdea.marketingAngle}
Target Audience: ${contentIdea.targetAudience}
Pain Point Solved: ${contentIdea.painPoint}
Key Message: ${contentIdea.keyMessage}
Hook (Opening Line): ${contentIdea.hook}
Recommended CTA: ${contentIdea.recommendedCTA}
Visual / Concept Description: ${contentIdea.description}

[FACTUAL PRODUCT RESEARCH DATA]
Product Name: ${product.name}
Brand: ${product.brand || 'N/A'}
Category: ${product.category || 'N/A'}
Price: ${product.price ? `${product.price} ${product.currency}` : 'N/A'}
Key Features: ${product.features.join(', ') || 'N/A'}
Key Benefits: ${product.benefits.join(', ') || 'N/A'}
USP: ${product.usp.join(', ') || 'N/A'}
Target Audience: ${product.targetAudience || 'N/A'}
`.trim();

    // Mark content idea status as selected
    await this.prisma.contentIdea.update({
      where: { id: contentIdeaId },
      data: { status: 'selected' },
    });

    // Create Idea entity connected to product
    const idea = await this.prisma.idea.create({
      data: {
        title: contentIdea.title,
        topic: product.name,
        description: richScriptPrompt,
        language: 'vi',
        status: 'ready',
        productId: product.id,
      },
    });

    // Create GenerationJob record
    const job = await this.prisma.generationJob.create({
      data: {
        ideaId: idea.id,
        productId: product.id,
        status: 'queued',
        config: config as any,
      },
    });

    // Queue job to BullMQ video-generation queue
    await this.queueService.addVideoJob(
      job.id,
      idea.id,
      contentIdea.title,
      undefined,
      'vi',
      {
        ...config,
        productId: product.id,
      },
    );

    this.logger.log(
      `[ContentStrategy] Triggered video generation job ${job.id} for content idea ${contentIdeaId}`,
    );

    return {
      contentIdea: this.mapToResponse(contentIdea),
      idea,
      job,
    };
  }

  /**
   * Batch Video Generation:
   * Accepts product ID, optional list of contentIdeaIds (or takes top N priority ideas),
   * and triggers video generation jobs for all selected ideas concurrently.
   */
  async batchGenerateVideosFromIdeas(
    productId: string,
    ideaIds?: string[],
    config: VideoJobConfig = {},
    limit = 3,
  ) {
    let targetIdeaIds = ideaIds && ideaIds.length > 0 ? ideaIds : [];

    if (targetIdeaIds.length === 0) {
      const topIdeas = await this.prisma.contentIdea.findMany({
        where: { productId },
        orderBy: [{ priority: 'asc' }, { createdAt: 'desc' }],
        take: limit,
      });
      targetIdeaIds = topIdeas.map((idea) => idea.id);
    }

    if (targetIdeaIds.length === 0) {
      throw new BadRequestException(
        'Không tìm thấy ý tưởng nội dung nào để tạo video',
      );
    }

    this.logger.log(
      `[ContentStrategy] Starting batch video generation for ${targetIdeaIds.length} content ideas (productId=${productId})`,
    );

    const results = [];
    for (const id of targetIdeaIds) {
      try {
        const result = await this.generateVideoFromIdea(id, config);
        results.push(result);
      } catch (err) {
        this.logger.error(
          `[ContentStrategy] Batch generate failed for idea ${id}: ${err}`,
        );
      }
    }

    return {
      success: true,
      count: results.length,
      jobs: results.map((r) => r.job),
      ideas: results.map((r) => r.contentIdea),
    };
  }

  // ---------------------------------------------------------------------------
  // Helper methods
  // ---------------------------------------------------------------------------

  private safeArrayJoin(val: any, delimiter = '; '): string {
    if (Array.isArray(val)) {
      const items = val.filter(
        (item) =>
          item !== null && item !== undefined && String(item).trim().length > 0,
      );
      return items.length > 0 ? items.join(delimiter) : 'Không có';
    }
    if (typeof val === 'string' && val.trim().length > 0) {
      return val.trim();
    }
    return 'Không có';
  }

  private firstArrayItem(val: any, fallback: string): string {
    if (Array.isArray(val) && val.length > 0) {
      const first = val[0];
      if (
        first !== null &&
        first !== undefined &&
        String(first).trim().length > 0
      ) {
        return String(first).trim();
      }
    }
    if (typeof val === 'string' && val.trim().length > 0) {
      return val.trim();
    }
    return fallback;
  }

  private buildResearchContext(product: any): string {
    const brief = product.contentBrief;
    const painPointsText = this.safeArrayJoin(product.painPoints);
    return `
Tên sản phẩm: ${product.name || 'Sản phẩm'}
Thương hiệu: ${product.brand || 'N/A'}
Danh mục: ${product.category || 'N/A'}
Mô tả: ${product.description || 'N/A'}
Giá bán: ${product.price ? `${product.price} ${product.currency || 'VND'}` : 'Chưa rõ'}
Tính năng nổi bật: ${this.safeArrayJoin(product.features)}
Lợi ích sử dụng: ${this.safeArrayJoin(product.benefits)}
Điểm bán hàng độc nhất (USP): ${this.safeArrayJoin(product.usp)}
Đối tượng khách hàng mục tiêu: ${product.targetAudience || brief?.targetAudience || 'Khách hàng quan tâm'}
Nỗi đau / Vấn đề cần giải quyết: ${painPointsText !== 'Không có' ? painPointsText : brief?.mainPainPoint || 'Không có'}
Trường hợp sử dụng (Use cases): ${this.safeArrayJoin(product.useCases)}
Ưu điểm: ${this.safeArrayJoin(product.pros)}
Nhược điểm: ${this.safeArrayJoin(product.cons)}
`.trim();
  }

  private async callLlm(
    provider: string,
    apiKey: string,
    model: string,
    prompt: string,
  ): Promise<string> {
    const openAIBaseUrl = (): string => {
      const urls: Record<string, string> = {
        groq: 'https://api.groq.com/openai/v1/chat/completions',
        openai: 'https://api.openai.com/v1/chat/completions',
        deepseek: 'https://api.deepseek.com/v1/chat/completions',
        moonshot: 'https://api.moonshot.cn/v1/chat/completions',
        qwen: 'https://dashscope.aliyuncs.com/compatible-mode/v1/chat/completions',
        grok: 'https://api.x.ai/v1/chat/completions',
        volcengine: 'https://ark.cn-beijing.volces.com/api/v3/chat/completions',
      };
      return urls[provider] || '';
    };

    let responseText = '';

    if (provider === 'gemini') {
      const url = `https://generativelanguage.googleapis.com/v1beta/models/${model || 'gemini-2.0-flash'}:generateContent?key=${apiKey}`;
      const response = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          contents: [{ parts: [{ text: prompt }] }],
        }),
      });
      if (!response.ok) {
        throw new Error(
          `Gemini API returned status ${response.status}: ${await response.text()}`,
        );
      }
      const data = await response.json();
      responseText = data.candidates?.[0]?.content?.parts?.[0]?.text || '';
    } else {
      const url = openAIBaseUrl();
      if (!url) {
        throw new Error(`Unsupported LLM provider: ${provider}`);
      }
      const response = await fetch(url, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${apiKey}`,
        },
        body: JSON.stringify({
          model: model || 'llama-3.3-70b-versatile',
          messages: [{ role: 'user', content: prompt }],
          temperature: 0.7,
        }),
      });
      if (!response.ok) {
        throw new Error(
          `${provider} API returned status ${response.status}: ${await response.text()}`,
        );
      }
      const data = await response.json();
      responseText = data.choices?.[0]?.message?.content || '';
    }

    return responseText;
  }

  private parseAndValidateResponse(rawText: string): RawContentIdeaItem[] {
    if (!rawText || !rawText.trim()) return [];

    let cleaned = rawText.trim();
    cleaned = cleaned
      .replace(/```json/g, '')
      .replace(/```/g, '')
      .trim();

    // Locate first '[' and last ']' if extra narrative wrapped the response
    const firstBracket = cleaned.indexOf('[');
    const lastBracket = cleaned.lastIndexOf(']');
    if (
      firstBracket !== -1 &&
      lastBracket !== -1 &&
      lastBracket > firstBracket
    ) {
      cleaned = cleaned.substring(firstBracket, lastBracket + 1);
    }

    try {
      const parsed = JSON.parse(cleaned);
      if (!Array.isArray(parsed)) return [];

      const validItems: RawContentIdeaItem[] = [];
      for (const item of parsed) {
        if (
          typeof item === 'object' &&
          item !== null &&
          typeof item.title === 'string' &&
          item.title.trim().length > 0
        ) {
          validItems.push({
            title: item.title.trim(),
            description: item.description || item.title,
            contentType: item.contentType || 'product_review',
            marketingAngle: item.marketingAngle || 'Tổng quan sản phẩm',
            targetAudience: item.targetAudience || 'Khách hàng tiềm năng',
            painPoint: item.painPoint || 'Tìm kiếm giải pháp tốt',
            keyMessage: item.keyMessage || item.title,
            hook: item.hook || item.title,
            recommendedCTA: item.recommendedCTA || 'Xem thêm chi tiết bên dưới',
            priority: Number(item.priority) || 1,
          });
        }
      }
      return validItems;
    } catch (e) {
      this.logger.error(`[ContentStrategy] Failed to parse LLM JSON: ${e}`);
      return [];
    }
  }

  private normalizeContentType(typeInput: string): string {
    const lower = typeInput?.toLowerCase().trim() || '';
    for (const valid of CONTENT_TYPES) {
      if (lower.includes(valid) || valid.includes(lower)) {
        return valid;
      }
    }
    return 'product_review';
  }

  private mapToResponse(idea: any): ContentIdeaResponse {
    return {
      id: idea.id,
      productId: idea.productId,
      title: idea.title,
      description: idea.description,
      contentType: idea.contentType,
      marketingAngle: idea.marketingAngle,
      targetAudience: idea.targetAudience,
      painPoint: idea.painPoint,
      keyMessage: idea.keyMessage,
      hook: idea.hook,
      recommendedCTA: idea.recommendedCTA,
      priority: idea.priority,
      status: idea.status,
      createdAt: idea.createdAt,
      updatedAt: idea.updatedAt,
    };
  }

  private buildFallbackIdeas(product: any): RawContentIdeaItem[] {
    const pName = product.name || 'Sản phẩm';
    const pPrice = product.price
      ? `${product.price} ${product.currency || 'VND'}`
      : 'mức giá hiện tại';
    const mainAudience = product.targetAudience || 'người tiêu dùng hiện đại';
    const firstPain = this.firstArrayItem(
      product.painPoints,
      'chưa tìm được giải pháp tối ưu',
    );
    const firstBenefit = this.firstArrayItem(
      product.benefits,
      'mang lại trải nghiệm tuyệt vời',
    );
    const firstFeature = this.firstArrayItem(
      product.features,
      'thiết kế thông minh',
    );
    const firstUsp = this.firstArrayItem(product.usp, 'chất lượng vượt trội');

    return [
      {
        title: `${pPrice} mua ${pName} có thực sự đáng tiền?`,
        description: `Phân tích thực tế giá trị sử dụng và độ bền của ${pName} so với mức giá ${pPrice}.`,
        contentType: 'value_for_money',
        marketingAngle: 'Phân tích giá trị & ROI',
        targetAudience: mainAudience,
        painPoint: 'Lo lắng mua đắt hoặc không đúng nhu cầu',
        keyMessage: `Giá trị sử dụng và sự tiện lợi của ${pName} hoàn toàn tương xứng với chi phí`,
