/**
 * Generic product data extractor.
 *
 * Layered extraction strategy:
 * 1. JSON-LD / Schema.org Product (highest priority)
 * 2. OpenGraph metadata & meta tags
 * 3. HTML structured elements (specifications, ratings, prices)
 * 4. Microdata / Fallback HTML selectors
 */
export class GenericProductAdapter extends ProductSourceAdapter {
  readonly name = 'generic';
  private readonly logger = new Logger(GenericProductAdapter.name);

  canHandle(_url: string): boolean {
    return true;
  }

  async extract(url: string): Promise<RawProductData> {
    this.logger.log(`[Extract] Starting layered extraction for URL: ${url}`);
    this.validateUrl(url);

    const html = await this.fetchPage(url);
    const $ = cheerio.load(html);

    // Layer 1: JSON-LD Structured Data
    const jsonLd = this.extractJsonLd($);
    if (jsonLd.name) {
      this.logger.log(`[Extract] JSON-LD Product found: "${jsonLd.name}"`);
    }

    // Layer 2: OpenGraph metadata
    const og = this.extractOpenGraph($);

    // Layer 3: Standard Meta & Microdata
    const meta = this.extractHtmlMeta($);

    // Layer 4: HTML DOM details (prices, ratings, specs, gallery)
    const domData = this.extractDomData($, url);

    // Normalize & merge data in priority order
    const title =
      jsonLd.name || og.title || meta.title || domData.title || null;
    const brand =
      jsonLd.brand || og.brand || meta.brand || domData.brand || null;
    const category =
      jsonLd.category ||
      og.category ||
      meta.category ||
      domData.category ||
      null;
    const description =
      jsonLd.description ||
      og.description ||
      meta.description ||
      domData.description ||
      null;

    const priceData = this.mergePrices(jsonLd, og, meta, domData);
    const ratingData = this.mergeRatings(jsonLd, meta, domData);
    const images = this.mergeImages(
      jsonLd.images,
      og.image,
      meta.images,
      domData.images,
    );
    const videos = this.mergeVideos(jsonLd.videos, og.video, domData.videos);
    const features = Array.from(
      new Set([...jsonLd.features, ...meta.features, ...domData.features]),
    );
    const specifications = {
      ...jsonLd.specifications,
      ...domData.specifications,
    };

    this.logger.log(
      `[Normalize] Extracted title="${title || 'N/A'}", price="${priceData.price || 'N/A'}", images=${images.length}, rating=${ratingData.rating || 'N/A'}`,
    );

    return {
      title: title ? this.cleanText(title) : null,
      brand: brand ? this.cleanText(brand) : null,
      category: category ? this.cleanText(category) : null,
      description: description ? this.cleanText(description) : null,
      price: priceData.price,
      originalPrice: priceData.originalPrice,
      currency: priceData.currency || 'VND',
      discountPercent: priceData.discountPercent,
      rating: ratingData.rating,
      reviewCount: ratingData.reviewCount,
      images,
      videos,
      features,
      specifications,
      productUrl: url,
      sourcePlatform: this.name,
    };
  }

  // ---------------------------------------------------------------------------
  // URL validation & SSRF prevention
  // ---------------------------------------------------------------------------

  private validateUrl(url: string): void {
    let parsed: URL;
    try {
      parsed = new URL(url);
    } catch {
      throw new Error('URL không hợp lệ');
    }

    if (!['http:', 'https:'].includes(parsed.protocol)) {
      throw new Error('Chỉ hỗ trợ URL HTTP và HTTPS');
    }

    const hostname = parsed.hostname.toLowerCase();

    if (BLOCKED_HOSTS.includes(hostname)) {
      throw new Error('Không thể truy cập địa chỉ nội bộ');
    }

    if (BLOCKED_IP_PREFIXES.some((prefix) => hostname.startsWith(prefix))) {
      throw new Error('Không thể truy cập địa chỉ IP nội bộ');
    }
  }

  // ---------------------------------------------------------------------------
  // HTTP fetch
  // ---------------------------------------------------------------------------

  private async fetchPage(url: string): Promise<string> {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), FETCH_TIMEOUT_MS);

    try {
      const response = await fetch(url, {
        signal: controller.signal,
        headers: {
          'User-Agent':
            'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0.0.0 Safari/537.36',
          Accept:
            'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
          'Accept-Language': 'vi-VN,vi;q=0.9,en-US;q=0.8,en;q=0.7',
        },
        redirect: 'follow',
      });

      this.logger.log(`[Fetch] HTTP ${response.status} for ${url}`);

      if (!response.ok) {
        throw new Error(
          `Không thể tải trang sản phẩm (HTTP ${response.status})`,
        );
      }

      const contentType = response.headers.get('content-type') || '';
      if (
        !contentType.includes('text/html') &&
        !contentType.includes('application/xhtml')
      ) {
        throw new Error(
          `URL không trỏ đến trang HTML (content-type: ${contentType})`,
        );
      }

      const arrayBuffer = await response.arrayBuffer();
      if (arrayBuffer.byteLength > MAX_RESPONSE_BYTES) {
        throw new Error('Trang sản phẩm quá lớn (vượt quá 8MB)');
      }

      const decoder = new TextDecoder('utf-8', { fatal: false });
      return decoder.decode(arrayBuffer);
    } catch (error: unknown) {
      if (error instanceof Error) {
        if (error.name === 'AbortError') {
          throw new Error(
            'Hết thời gian chờ khi tải trang sản phẩm (timeout 12s)',
          );
        }
        throw error;
      }
      throw new Error('Lỗi không xác định khi tải trang sản phẩm');
    } finally {
      clearTimeout(timeout);
    }
  }

  // ---------------------------------------------------------------------------
  // JSON-LD extraction
  // ---------------------------------------------------------------------------

  private extractJsonLd($: cheerio.CheerioAPI) {
    const result = {
      name: null as string | null,
      brand: null as string | null,
      category: null as string | null,
      description: null as string | null,
      images: [] as string[],
      videos: [] as string[],
      features: [] as string[],
      specifications: {} as Record<string, string>,
      price: null as string | null,
      originalPrice: null as string | null,
      currency: null as string | null,
      rating: null as number | null,
      reviewCount: null as number | null,
    };

    try {
      $('script[type="application/ld+json"]').each((_, el) => {
        try {
          const text = $(el).html();
          if (!text) return;

          const data = JSON.parse(text);
          const items = Array.isArray(data) ? data : [data];

          for (const item of items) {
            const candidates = item['@graph']
              ? [...item['@graph'], item]
              : [item];

            for (const candidate of candidates) {
              const type = (candidate['@type'] || '').toString().toLowerCase();
              if (
                !type.includes('product') &&
                !type.includes('offer') &&
                !type.includes('item')
              ) {
                continue;
              }

              if (!result.name && candidate.name)
                result.name = String(candidate.name).trim();
              if (!result.brand && candidate.brand) {
                result.brand =
                  typeof candidate.brand === 'string'
                    ? candidate.brand
                    : candidate.brand?.name || null;
              }
              if (!result.category && candidate.category) {
                result.category = String(candidate.category).trim();
              }
              if (!result.description && candidate.description) {
                result.description = String(candidate.description).trim();
              }

              // Images
              if (candidate.image) {
                const imgList = Array.isArray(candidate.image)
                  ? candidate.image
                  : [candidate.image];
                for (const img of imgList) {
                  const url =
                    typeof img === 'string' ? img : img?.url || img?.contentUrl;
                  if (url) result.images.push(String(url));
                }
              }

              // Videos
              if (candidate.video) {
                const vidList = Array.isArray(candidate.video)
                  ? candidate.video
                  : [candidate.video];
                for (const vid of vidList) {
                  const url =
                    typeof vid === 'string'
                      ? vid
                      : vid?.contentUrl || vid?.embedUrl;
                  if (url) result.videos.push(String(url));
                }
              }

              // Price from offers
              if (candidate.offers) {
                const offers = Array.isArray(candidate.offers)
                  ? candidate.offers
                  : [candidate.offers];
                for (const offer of offers) {
                  if (offer.price != null) {
                    result.price = String(offer.price);
                    if (offer.priceCurrency)
                      result.currency = String(offer.priceCurrency);
                  }
                  if (offer.highPrice != null && !result.originalPrice) {
                    result.originalPrice = String(offer.highPrice);
                  }
                }
              }

              // AggregateRating
              if (candidate.aggregateRating) {
                const r = candidate.aggregateRating;
                if (r.ratingValue != null)
                  result.rating = parseFloat(String(r.ratingValue));
                if (r.reviewCount != null)
                  result.reviewCount = parseInt(String(r.reviewCount), 10);
                else if (r.ratingCount != null)
                  result.reviewCount = parseInt(String(r.ratingCount), 10);
              }

              // Specifications
              if (candidate.additionalProperty) {
                const props = Array.isArray(candidate.additionalProperty)
                  ? candidate.additionalProperty
                  : [candidate.additionalProperty];
                for (const prop of props) {
                  if (prop.name && prop.value) {
                    result.specifications[String(prop.name)] = String(
                      prop.value,
                    );
                    result.features.push(`${prop.name}: ${prop.value}`);
                  }
                }
              }
            }
          }
        } catch {
          // Ignore JSON-LD parse errors silently per chunk
        }
      });
    } catch (err) {
      this.logger.debug(`JSON-LD extraction warning: ${err}`);
    }

    return result;
  }

  // ---------------------------------------------------------------------------
  // OpenGraph extraction
  // ---------------------------------------------------------------------------

  private extractOpenGraph($: cheerio.CheerioAPI) {
    const ogImages: string[] = [];
    $(
      'meta[property="og:image"], meta[property="og:image:url"], meta[property="og:image:secure_url"], meta[name="twitter:image"], meta[name="image"]',
    ).each((_, el) => {
      const content = $(el).attr('content')?.trim();
      if (content) ogImages.push(content);
    });

    return {
      title: $('meta[property="og:title"]').attr('content')?.trim() || null,
      brand:
        $('meta[property="product:brand"]').attr('content')?.trim() || null,
      category:
        $('meta[property="product:category"]').attr('content')?.trim() || null,
      description:
        $('meta[property="og:description"]').attr('content')?.trim() || null,
      image: ogImages,
      video: $('meta[property="og:video"]').attr('content')?.trim() || null,
      price:
        $('meta[property="product:price:amount"]').attr('content')?.trim() ||
        null,
      currency:
        $('meta[property="product:price:currency"]').attr('content')?.trim() ||
        null,
    };
  }

  // ---------------------------------------------------------------------------
  // Standard HTML meta extraction
  // ---------------------------------------------------------------------------

  private extractHtmlMeta($: cheerio.CheerioAPI) {
    const title = $('title').first().text()?.trim() || null;
    const description =
      $('meta[name="description"]').attr('content')?.trim() || null;
    const brand = $('meta[name="brand"]').attr('content')?.trim() || null;
    const category = $('meta[name="category"]').attr('content')?.trim() || null;

    const images: string[] = [];
    $(
      'img[src*="product"], img[src*="item"], img[src*="gallery"], img[data-src*="product"], img[data-src*="item"]',
    ).each((_, el) => {
      const src =
        $(el).attr('src') ||
        $(el).attr('data-src') ||
        $(el).attr('data-lazy-src');
      if (src) images.push(src);
    });

    const features: string[] = [];
    $('.product-features li, .key-features li, .features-list li').each(
      (_, el) => {
        const txt = $(el).text().trim();
        if (txt) features.push(txt);
      },
    );

    return { title, description, brand, category, images, features };
  }

  // ---------------------------------------------------------------------------
  // HTML DOM fallbacks & Rich Gallery Extraction
  // ---------------------------------------------------------------------------

  private extractDomData($: cheerio.CheerioAPI, baseUrl?: string) {
    const title =
      $('h1.product-title, h1.product-name, h1[itemprop="name"], h1')
        .first()
        .text()
        ?.trim() || null;

    const description =
      $('.product-description, #product-description, [itemprop="description"]')
        .first()
        .text()
        ?.trim() || null;

    const brand =
      $('[itemprop="brand"], .product-brand, .brand-name')
        .first()
        .text()
        ?.trim() || null;

    const category =
      $('.breadcrumb span, .breadcrumbs a').last().text()?.trim() || null;

    // Price selectors
    let price: string | null = null;
    let originalPrice: string | null = null;

    const currentPriceText = $(
      '.current-price, .price-current, .product-price, [itemprop="price"]',
    )
      .first()
      .text()
      ?.trim();
    if (currentPriceText) price = this.cleanPriceString(currentPriceText);

    const oldPriceText = $('.old-price, .price-old, .original-price, del')
      .first()
      .text()
      ?.trim();
    if (oldPriceText) originalPrice = this.cleanPriceString(oldPriceText);

    // Rating & Reviews
    let rating: number | null = null;
    let reviewCount: number | null = null;

    const ratingText = $(
      '[itemprop="ratingValue"], .rating-score, .star-rating',
    )
      .first()
      .text()
      ?.trim();
    if (ratingText) {
      const num = parseFloat(ratingText.replace(',', '.'));
      if (!isNaN(num)) rating = num;
    }

    const reviewCountText = $(
      '[itemprop="reviewCount"], .review-count, .total-reviews',
    )
      .first()
      .text()
      ?.trim();
    if (reviewCountText) {
      const match = reviewCountText.match(/\d+/);
      if (match) reviewCount = parseInt(match[0], 10);
    }

    // Specifications table
    const specifications: Record<string, string> = {};
    const features: string[] = [];

    $('table.specifications tr, table.product-spec tr, .spec-item').each(
      (_, el) => {
        const key = $(el).find('td:nth-child(1), .spec-title').text().trim();
        const val = $(el).find('td:nth-child(2), .spec-value').text().trim();
        if (key && val) {
          specifications[key] = val;
          features.push(`${key}: ${val}`);
        }
      },
    );

    const rawCandidateUrls: string[] = [];

    // 1. Target Product Gallery Elements
    const gallerySelectors = [
      '.product-gallery img',
      '.product-images img',
      '.gallery img',
      '.carousel img',
      '.slider img',
      '.swiper-slide img',
      '.slick-slide img',
      '[class*="gallery"] img',
      '[class*="carousel"] img',
      '[class*="thumb"] img',
      '[class*="product"] img',
      '[class*="image"] img',
      'img[itemprop="image"]',
      'img[data-src]',
      'img[data-lazy]',
      'img[srcset]',
      'img',
    ];

    $(gallerySelectors.join(', ')).each((_, el) => {
      const attributes = [
        $(el).attr('data-zoom-image'),
        $(el).attr('data-large_image'),
        $(el).attr('data-large-image'),
        $(el).attr('data-high-res-src'),
        $(el).attr('data-original'),
        $(el).attr('data-src'),
        $(el).attr('data-lazy-src'),
        $(el).attr('data-lazy'),
        $(el).attr('src'),
      ];

      for (const attr of attributes) {
        if (attr) rawCandidateUrls.push(attr);
      }

      // Handle srcset / data-srcset
      const srcset = $(el).attr('srcset') || $(el).attr('data-srcset');
      if (srcset) {
        const parts = srcset.split(',');
        for (const part of parts) {
          const u = part.trim().split(/\s+/)[0];
          if (u) rawCandidateUrls.push(u);
        }
      }
    });

    // 2. Inline Page Scripts (State / JSON variables & E-commerce CDNs)
    $('script').each((_, el) => {
      const scriptText = $(el).html();
      if (!scriptText || scriptText.length > 500000) return;

      // Standard image extension matches
      const stdMatches = scriptText.match(
        /https?:\/\/[^"'\s\\]+?\.(?:jpg|jpeg|png|webp)/gi,
      );
      if (stdMatches) {
        for (const m of stdMatches) {
          rawCandidateUrls.push(m);
        }
      }

      // E-commerce CDN matches (Shopee, Lazada, TikTok Shop, AliExpress, etc.)
      const cdnMatches = scriptText.match(
        /https?:\/\/[^"'\s\\]*?(?:susercontent\.com\/file|ibyteimg\.com|alicdn\.com|cdnm-shopline|shopify\.com)\/[a-zA-Z0-9_\/-]+/gi,
      );
      if (cdnMatches) {
        for (const m of cdnMatches) {
          rawCandidateUrls.push(m);
        }
      }
    });

    // Resolve & Clean URLs
    const images: string[] = [];
    for (const raw of rawCandidateUrls) {
      const resolved = this.resolveAndUpgradeImageUrl(raw, baseUrl);
      if (resolved) images.push(resolved);
    }

    // Videos
    const videos: string[] = [];
    $('video source, video, iframe[src*="youtube"], iframe[src*="vimeo"]').each(
      (_, el) => {
        const src = $(el).attr('src');
        if (src) {
          const resolvedVid = this.resolveUrl(src, baseUrl);
          if (resolvedVid) videos.push(resolvedVid);
        }
      },
    );

    return {
      title,
      description,
      brand,
      category,
      price,
      originalPrice,
      rating,
      reviewCount,
      specifications,
      features,
      images,
      videos,
    };
  }

  private resolveAndUpgradeImageUrl(
    raw: string,
    baseUrl?: string,
  ): string | null {
    if (!raw || typeof raw !== 'string') return null;
    let urlStr = raw.trim();
    if (urlStr.startsWith('//')) urlStr = 'https:' + urlStr;

    let absolute: string;
    try {
      if (
        baseUrl &&
        !urlStr.startsWith('http://') &&
        !urlStr.startsWith('https://')
      ) {
        absolute = new URL(urlStr, baseUrl).href;
      } else {
        absolute = new URL(urlStr).href;
      }
    } catch {
      return null;
    }

    const lower = absolute.toLowerCase();
    if (
      lower.includes('data:image/') ||
      lower.includes('.svg') ||
      lower.endsWith('.gif')
    ) {
      return null;
    }
    if (
      lower.includes('favicon') ||
      lower.includes('logo') ||
      lower.includes('avatar') ||
      lower.includes('icon') ||
      lower.includes('sprite') ||
      lower.includes('shopeemobile.com')
    ) {
      return null;
    }

    // Clean @resize_... parameters
    absolute = absolute.replace(/@resize_[^?#]+/i, '');

    // Upgrade known thumbnail resolutions to full resolution
    // Shopee thumbnails (_tn, _cover, _100x100, etc. with or without extension)
    absolute = absolute.replace(
      /_(tn|cover|100x100|60x60|80x80|200x200)(\.[a-z]+)?$/i,
      (_, __, g2) => g2 || '',
    );
    // Lazada thumbnails (_80x80q80.jpg)
    absolute = absolute.replace(/_\d+x\d+q\d+\.[a-z]+$/i, '');
    // Amazon thumbnails (._AC_US40_, etc.)
    absolute = absolute.replace(
      /\._[A-Z0-9_]+_(\.[a-z]+)?$/i,
      (_, g1) => g1 || '',
    );

    return absolute;
  }

  private resolveUrl(raw: string, baseUrl?: string): string | null {
    if (!raw || typeof raw !== 'string') return null;
    let u = raw.trim();
    if (u.startsWith('//')) u = 'https:' + u;
    try {
      return baseUrl && !u.startsWith('http')
        ? new URL(u, baseUrl).href
        : new URL(u).href;
    } catch {
      return null;
    }
  }

  // ---------------------------------------------------------------------------
  // Helpers
  // ---------------------------------------------------------------------------

  private mergePrices(
    jsonLd: any,
    og: any,
    meta: any,
    dom: any,
  ): {
    price: string | null;
    originalPrice: string | null;
    currency: string | null;
    discountPercent: number | null;
  } {
    const rawPrice = jsonLd.price || og.price || dom.price || null;
    const rawOriginalPrice = jsonLd.originalPrice || dom.originalPrice || null;
    const currency = jsonLd.currency || og.currency || 'VND';

    const pNum = rawPrice ? parseFloat(rawPrice.replace(/[^0-9.]/g, '')) : null;
    const origNum = rawOriginalPrice
      ? parseFloat(rawOriginalPrice.replace(/[^0-9.]/g, ''))
      : null;

    let discountPercent: number | null = null;
    if (pNum && origNum && origNum > pNum) {
      discountPercent = Math.round(((origNum - pNum) / origNum) * 100);
    }

    return {
      price: rawPrice ? this.cleanPriceString(rawPrice) : null,
      originalPrice: rawOriginalPrice
        ? this.cleanPriceString(rawOriginalPrice)
        : null,
      currency,
      discountPercent,
    };
  }

  private mergeRatings(jsonLd: any, meta: any, dom: any) {
    return {
      rating: jsonLd.rating ?? dom.rating ?? null,
      reviewCount: jsonLd.reviewCount ?? dom.reviewCount ?? null,
    };
  }

  private mergeImages(
    ...lists: (string | string[] | null | undefined)[]
  ): string[] {
    const seen = new Set<string>();
    const result: string[] = [];

    for (const item of lists) {
      if (!item) continue;
      const urls = Array.isArray(item) ? item : [item];
      for (const raw of urls) {
        if (typeof raw !== 'string') continue;
        const cleaned = this.resolveAndUpgradeImageUrl(raw);
        if (cleaned && !seen.has(cleaned)) {
          seen.add(cleaned);
          result.push(cleaned);
        }
      }
    }

    return result.slice(0, 30);
  }

  private mergeVideos(
    ...lists: (string | string[] | null | undefined)[]
  ): string[] {
    const seen = new Set<string>();
    const result: string[] = [];

    for (const item of lists) {
      if (!item) continue;
      const urls = Array.isArray(item) ? item : [item];
      for (const raw of urls) {
        if (typeof raw !== 'string') continue;
        const cleaned = raw.trim();
        if (cleaned && !seen.has(cleaned)) {
          seen.add(cleaned);
          result.push(cleaned);
        }
      }
    }

    return result.slice(0, 10);
  }

  private cleanPriceString(str: string): string {
    return str.replace(/\s+/g, ' ').trim();
  }

  private cleanText(str: string): string {
    return str
      .replace(/\s+/g, ' ')
      .replace(/[\r\n\t]+/g, ' ')
      .trim();
  }
}

import { Injectable, Logger, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../database/prisma.service';
import { StorageService } from '../storage/storage.service';
import { GenericProductAdapter } from './adapters/generic-product.adapter';
import axios from 'axios';
import * as cheerio from 'cheerio';

export type AssetDiscoveryResult = {
  success: boolean;
  importedCount: number;
  newImages: string[];
  message?: string;
};

@Injectable()
export class AssetDiscoveryService {
  private readonly logger = new Logger(AssetDiscoveryService.name);
  private readonly genericAdapter = new GenericProductAdapter();

  constructor(
    private readonly prisma: PrismaService,
    private readonly storageService: StorageService,
  ) {}

  /**
   * Search the internet for real product images, evaluate suitability,
   * download candidate image buffers, store them in MinIO, and append URLs to product.images.
   * If search results = 0, fallback to extracting product gallery directly from product.sourceUrl.
   */
  async discoverAndImportAssets(
    productId: string,
    maxImages = 5,
  ): Promise<AssetDiscoveryResult> {
    const product = await this.prisma.product.findUnique({
      where: { id: productId },
    });

    if (!product) {
      throw new NotFoundException(`Product ${productId} not found`);
    }

    const sourceUrl = product.sourceUrl || product.affiliateUrl || '';

    this.logger.log(
      `[AssetDiscovery]\nProduct: ${product.name} (${product.id})\nSource URL: ${sourceUrl || 'N/A'}`,
    );

    const cleanName = (product.name || '')
      .replace(/^Đang nghiên cứu.*/i, '')
      .replace(/^Sản phẩm từ.*/i, '')
      .trim();

    let sourceDomain = '';
    if (sourceUrl) {
      try {
        sourceDomain = new URL(sourceUrl).hostname;
      } catch {
        // ignore invalid URL
      }
    }

    // Build Search Queries
    const queries: string[] = [];

    if (product.brand && cleanName) {
      queries.push(`${product.brand} ${cleanName}`);
    }
    if (cleanName) {
      queries.push(cleanName);
      queries.push(`${cleanName} product image`);
    }
    if (sourceDomain && cleanName) {
      queries.push(`site:${sourceDomain} ${cleanName}`);
    }
    if (product.brand) {
      queries.push(`${product.brand} product`);
    }

    // Deduplicate queries
    const uniqueQueries = Array.from(new Set(queries.filter(Boolean)));

    this.logger.log(
      `[Queries]\n` +
        uniqueQueries.map((q, idx) => `- query ${idx + 1}: "${q}"`).join('\n'),
    );

    const candidateUrls: string[] = [];

    // Search Execution across queries
    for (const query of uniqueQueries) {
      const results = await this.searchCandidateImageUrls(query);
      if (results.length > 0) {
        candidateUrls.push(...results);
      }
      if (candidateUrls.length >= 10) break;
    }

    this.logger.log(
      `[Search]\nRaw results: ${candidateUrls.length}\nParsed results: ${candidateUrls.length}`,
    );

    // SOURCE URL FALLBACK: If web search returns 0 candidates and sourceUrl exists, extract gallery directly from sourceUrl!
    if (candidateUrls.length === 0 && sourceUrl) {
      this.logger.log(
        `[Fallback] Web search returned 0 results. Triggering Source URL Gallery Extraction for ${sourceUrl}`,
      );
      try {
        const rawExtracted = await this.genericAdapter.extract(sourceUrl);
        if (rawExtracted.images && rawExtracted.images.length > 0) {
          candidateUrls.push(...rawExtracted.images);
          this.logger.log(
            `[Fallback] Extracted ${rawExtracted.images.length} gallery images from Source URL`,
          );
        }
      } catch (fallbackErr) {
        this.logger.warn(
          `[Fallback] Source URL extraction failed: ${fallbackErr}`,
        );
      }
    }

    this.logger.log(
      `[Extraction]\nImages found: ${candidateUrls.length}\nVideos found: 0`,
    );

    if (candidateUrls.length === 0) {
      this.logger.warn(
        `[AssetDiscovery] No valid candidate images found for product ${productId}`,
      );
      return {
        success: true,
        importedCount: 0,
        newImages: [],
        message: 'Không tìm thấy ảnh phù hợp trên Internet hoặc trang nguồn',
      };
    }

    // Filter & Deduplicate
    const existingSet = new Set((product.images || []).map((u) => u.trim()));
    const acceptedCandidates: string[] = [];
    const rejectedCandidates: string[] = [];

    for (const rawUrl of candidateUrls) {
      const cleaned = rawUrl.trim();
      if (existingSet.has(cleaned) || acceptedCandidates.includes(cleaned)) {
        rejectedCandidates.push(`${cleaned} (duplicate)`);
      } else if (!this.isValidImageUrl(cleaned)) {
        rejectedCandidates.push(`${cleaned} (invalid url/icon)`);
      } else {
        acceptedCandidates.push(cleaned);
      }
    }

    this.logger.log(
      `[Filtering]\nAccepted: ${acceptedCandidates.length}\nRejected: ${rejectedCandidates.length}`,
    );

    // Import Candidate Images
    const newlyImportedUrls: string[] = [];
    const duplicateCount = rejectedCandidates.filter((r) =>
      r.includes('(duplicate)'),
    ).length;
    let failedCount = 0;

    for (
      let i = 0;
      i < acceptedCandidates.length && newlyImportedUrls.length < maxImages;
      i++
    ) {
      const imgUrl = acceptedCandidates[i];
      try {
        const importedUrl = await this.downloadAndStoreImage(imgUrl, productId);
        if (importedUrl) {
          newlyImportedUrls.push(importedUrl);
        } else {
          failedCount++;
        }
      } catch (err) {
        failedCount++;
        this.logger.debug(
          `[Import] Failed downloading ${imgUrl}: ${err instanceof Error ? err.message : String(err)}`,
        );
      }
    }

    if (newlyImportedUrls.length > 0) {
      const updatedImages = [...(product.images || []), ...newlyImportedUrls];
      await this.prisma.product.update({
        where: { id: productId },
        data: { images: updatedImages },
      });
    }

    this.logger.log(
      `[Import]\nDownloaded: ${newlyImportedUrls.length}\nImported: ${newlyImportedUrls.length}\nDuplicate: ${duplicateCount}\nFailed: ${failedCount}`,
    );

    return {
      success: true,
      importedCount: newlyImportedUrls.length,
      newImages: newlyImportedUrls,
      message: `Đã tự động tìm và bổ sung ${newlyImportedUrls.length} hình ảnh sản phẩm thực tế.`,
    };
  }

  private async searchCandidateImageUrls(query: string): Promise<string[]> {
    const candidateUrls: string[] = [];

    try {
      const searchUrl = `https://www.bing.com/images/search?q=${encodeURIComponent(query)}&form=HDRSC2`;
      const response = await axios.get(searchUrl, {
        headers: {
          'User-Agent':
            'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
          'Accept-Language': 'en-US,en;q=0.9,vi;q=0.8',
        },
        timeout: 10000,
      });

      const $ = cheerio.load(response.data);

      // Extract image URLs from Bing's m attribute in a.iusc elements
      $('a.iusc').each((_, element) => {
        const mAttr = $(element).attr('m');
        if (mAttr) {
          try {
            const mJson = JSON.parse(mAttr);
            if (mJson.murl && typeof mJson.murl === 'string') {
              const url = mJson.murl.trim();
              if (this.isValidImageUrl(url)) {
                candidateUrls.push(url);
              }
            }
          } catch {
            // Ignore JSON parse errors
          }
        }
      });
    } catch (err) {
      this.logger.warn(
        `[AssetDiscovery] Image scraping failed for query "${query}": ${
          err instanceof Error ? err.message : String(err)
        }`,
      );
    }

    return candidateUrls;
  }

  private isValidImageUrl(url: string): boolean {
    if (!url || typeof url !== 'string') return false;
    if (!url.startsWith('http://') && !url.startsWith('https://')) return false;
    const lower = url.toLowerCase();
    if (
      lower.includes('data:image/') ||
      lower.endsWith('.svg') ||
      lower.endsWith('.gif')
    ) {
      return false;
    }
    if (
      lower.includes('favicon') ||
      lower.includes('logo') ||
      lower.includes('avatar') ||
      lower.includes('icon') ||
      lower.includes('sprite')
    ) {
      return false;
    }
    return true;
  }

  private async downloadAndStoreImage(
    imageUrl: string,
    productId: string,
  ): Promise<string | null> {
    const res = await axios.get(imageUrl, {
      responseType: 'arraybuffer',
      timeout: 5000,
      signal: AbortSignal.timeout(5000),
      headers: {
        'User-Agent':
          'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
      },
    });

    const contentType = (res.headers['content-type'] as string) || 'image/jpeg';
    if (!contentType.startsWith('image/')) {
      return null;
    }

    const buffer = Buffer.from(res.data);
    // Minimum 10KB to avoid tiny thumbnails/logos
    if (buffer.length < 10240) {
      return null;
    }

    const ext = contentType.includes('png')
      ? 'png'
      : contentType.includes('webp')
        ? 'webp'
        : 'jpg';
    const timestamp = Date.now();
    const rand = Math.floor(Math.random() * 10000);
    const key = `product-assets/discovered-${productId.substring(0, 8)}-${timestamp}-${rand}.${ext}`;

    await this.storageService.uploadBuffer(buffer, key, contentType);
    const publicUrl = await this.storageService.getDownloadUrl(key, 604800);
    return publicUrl;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { LlmService } from '../llm/llm.service';
import { PrismaService } from '../database/prisma.service';
import type {
  RawProductData,
  AiProductAnalysis,
  MarketingAngle,
} from './types/product-research.types';

type GeminiResponse = {
  candidates?: Array<{
    content?: {
      parts?: Array<{
        text?: string;
      }>;
    };
  }>;
};

type OpenAICompatibleResponse = {
  choices?: Array<{
    message?: {
      content?: string;
    };
  }>;
};

const PRODUCT_ANALYSIS_PROMPT = `
You are a senior product marketing strategist. Analyze the following product information and generate structured marketing insights.

IMPORTANT ENGINEERING & TRUTH RULES:
1. Do NOT invent factual product specifications, prices, warranties, certifications, model numbers, dimensions, or technical numbers.
2. Separate FACTUAL DATA (from product info) from your AI MARKETING INSIGHTS (target audience, hooks, marketing angles).
3. If factual data is missing, keep empty array [] or null.
4. Respond in Vietnamese.
5. Return ONLY a valid JSON object matching the requested schema. No markdown code blocks, no explanation text outside JSON.

Product Information:
---
{PRODUCT_DATA}
---

Return this exact JSON structure:
{
  "summary": "Concise 2-3 sentence overview of the product",
  "category": "Standard product category (e.g. Kitchen Appliance, Electronics, Fashion) or null",
  "features": ["List of key physical or functional features based strictly on provided data"],
  "benefits": ["Derived customer benefits of using this product"],
  "sellingPoints": ["Key selling points / unique value propositions"],
  "usp": ["Unique selling points that differentiate this product"],
  "targetAudience": ["Specific buyer personas / ideal customer profiles"],
  "useCases": ["Real-world scenarios and situations where this product is useful"],
  "painPoints": ["Customer pain points or problems this product solves"],
  "pros": ["Major advantages and positive aspects"],
  "cons": ["Potential limitations or drawbacks to consider"],
  "marketingAngles": [
    {
      "title": "Short marketing angle title (e.g. 'Busy Office Workers')",
      "description": "Brief strategy explanation",
      "hook": "Attention-grabbing video hook opening line (under 15 words)"
    }
  ]
}
`.trim();

@Injectable()
export class ProductAnalysisService {
  private readonly logger = new Logger(ProductAnalysisService.name);

  constructor(
    private prisma: PrismaService,
    private llmService: LlmService,
  ) {}

  /**
   * Analyze raw product data with LLM and return validated AiProductAnalysis.
   * Includes safe retries on invalid JSON.
   */
  async analyzeProduct(rawData: RawProductData): Promise<AiProductAnalysis> {
    this.logger.log(
      `[AIAnalysis] Starting AI product analysis for "${rawData.title}"`,
    );

    const { provider, apiKey, model } =
      await this.llmService.getActiveProviderConfig();

    if (!apiKey) {
      this.logger.warn(
        '[AIAnalysis] No API key configured. Returning raw analysis fallback.',
      );
      return this.fallbackFromRaw(rawData);
    }

    const productSummaryText = this.buildPromptContext(rawData);
    const prompt = PRODUCT_ANALYSIS_PROMPT.replace(
      '{PRODUCT_DATA}',
      productSummaryText,
    );

    // Attempt 1
    try {
      const responseText = await this.callLlm(provider, apiKey, model, prompt);
      const parsed = this.parseAndValidateResponse(responseText);
      if (parsed) return parsed;
    } catch (err) {
      this.logger.warn(
        `[AIAnalysis] Attempt 1 failed: ${err instanceof Error ? err.message : String(err)}. Retrying...`,
      );
    }

    // Attempt 2 (Retry with strict JSON instruction)
    try {
      const retryPrompt = `${prompt}\n\nSTRICT NOTICE: Previous output was invalid. Reply strictly with raw valid JSON only!`;
      const responseText = await this.callLlm(
        provider,
        apiKey,
        model,
        retryPrompt,
      );
      const parsed = this.parseAndValidateResponse(responseText);
      if (parsed) return parsed;
    } catch (retryErr) {
      this.logger.error(
        `[AIAnalysis] Attempt 2 failed: ${retryErr instanceof Error ? retryErr.message : String(retryErr)}`,
      );
    }

    this.logger.warn(
      '[AIAnalysis] AI response parsing failed after retries. Using raw fallback.',
    );
    return this.fallbackFromRaw(rawData);
  }

  private buildPromptContext(rawData: RawProductData): string {
    const parts: string[] = [];

    if (rawData.title) parts.push(`Tên sản phẩm: ${rawData.title}`);
    if (rawData.brand) parts.push(`Thương hiệu: ${rawData.brand}`);
    if (rawData.category) parts.push(`Danh mục: ${rawData.category}`);
    if (rawData.price)
      parts.push(`Giá bán: ${rawData.price} ${rawData.currency || ''}`);
    if (rawData.originalPrice) parts.push(`Giá gốc: ${rawData.originalPrice}`);
    if (rawData.discountPercent != null)
      parts.push(`Giảm giá: ${rawData.discountPercent}%`);
    if (rawData.rating != null)
      parts.push(
        `Đánh giá: ${rawData.rating}/5 (${rawData.reviewCount || 0} lượt đánh giá)`,
      );

    if (rawData.description) {
      parts.push(`Mô tả chi tiết: ${rawData.description.substring(0, 2500)}`);
    }

    if (rawData.features && rawData.features.length > 0) {
      parts.push(`Tính năng nổi bật: ${rawData.features.join('; ')}`);
    }

    if (
      rawData.specifications &&
      Object.keys(rawData.specifications).length > 0
    ) {
      const specsStr = Object.entries(rawData.specifications)
        .map(([k, v]) => `${k}: ${v}`)
        .join('; ');
      parts.push(`Thông số kỹ thuật: ${specsStr}`);
    }

    parts.push(`URL: ${rawData.productUrl}`);

    return parts.join('\n');
  }

  private async callLlm(
    provider: string,
    apiKey: string,
    model: string,
    prompt: string,
  ): Promise<string> {
    const openAIBaseUrl = (): string => {
      const urls: Record<string, string> = {
        groq: 'https://api.groq.com/openai/v1/chat/completions',
        openai: 'https://api.openai.com/v1/chat/completions',
        deepseek: 'https://api.deepseek.com/v1/chat/completions',
        moonshot: 'https://api.moonshot.cn/v1/chat/completions',
        qwen: 'https://dashscope.aliyuncs.com/compatible-mode/v1/chat/completions',
        grok: 'https://api.x.ai/v1/chat/completions',
        volcengine: 'https://ark.cn-beijing.volces.com/api/v3/chat/completions',
      };
      return urls[provider] || '';
    };

    const defaultModel = (): string => {
      const models: Record<string, string> = {
        groq: 'llama-3.3-70b-versatile',
        openai: 'gpt-4o-mini',
        deepseek: 'deepseek-chat',
        moonshot: 'moonshot-v1-8k',
        qwen: 'qwen-max',
        azure: 'gpt-35-turbo',
        grok: 'grok-4.3',
        volcengine: 'doubao-seed-2-1-turbo-260628',
      };
      return models[provider] || '';
    };

    if (provider === 'gemini') {
      const targetModel = model || 'gemini-1.5-flash';
      const url = `https://generativelanguage.googleapis.com/v1beta/models/${targetModel}:generateContent?key=${apiKey}`;
      const response = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          contents: [{ parts: [{ text: prompt }] }],
          generationConfig: {
            temperature: 0.2,
            maxOutputTokens: 4096,
          },
        }),
      });
      if (!response.ok) {
        throw new Error(
          `Gemini API error ${response.status}: ${await response.text()}`,
        );
      }
      const data = (await response.json()) as GeminiResponse;
      const text = data.candidates?.[0]?.content?.parts?.[0]?.text || '';
      if (!text) throw new Error('Gemini returned empty response');
      return text;
    }

    if (provider === 'azure') {
      const baseUrl = await this.getAzureBaseUrl();
      const url = `${baseUrl}/openai/deployments/${model}/chat/completions?api-version=2024-08-01-preview`;
      const response = await fetch(url, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'api-key': apiKey,
        },
        body: JSON.stringify({
          messages: [{ role: 'user', content: prompt }],
          temperature: 0.2,
        }),
      });
      if (!response.ok) {
        throw new Error(
          `Azure API error ${response.status}: ${await response.text()}`,
        );
      }
      const data = (await response.json()) as OpenAICompatibleResponse;
      return data.choices?.[0]?.message?.content || '';
    }

    const url = openAIBaseUrl();
    if (!url) {
      throw new Error(`Unsupported LLM provider: ${provider}`);
    }

    const response = await fetch(url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${apiKey}`,
      },
      body: JSON.stringify({
        model: model || defaultModel(),
        messages: [{ role: 'user', content: prompt }],
        temperature: 0.2,
      }),
    });

    if (!response.ok) {
      throw new Error(
        `${provider} API error ${response.status}: ${await response.text()}`,
      );
    }
    const data = (await response.json()) as OpenAICompatibleResponse;
    return data.choices?.[0]?.message?.content || '';
  }

  private async getAzureBaseUrl(): Promise<string> {
    const setting = await this.prisma.systemSetting.findUnique({
      where: { key: 'azure_base_url' },
    });
    return setting?.value || '';
  }

  private parseAndValidateResponse(text: string): AiProductAnalysis | null {
    const cleaned = text
      .replace(/```json\s*/gi, '')
      .replace(/```\s*/g, '')
      .replace(/<think\b[^>]*>.*?<\/think>/gis, '')
      .trim();

    const jsonMatch = cleaned.match(/\{[\s\S]*\}/);
    if (!jsonMatch) return null;

    try {
      const obj = JSON.parse(jsonMatch[0]);
      return {
        summary: typeof obj.summary === 'string' ? obj.summary.trim() : null,
        category: typeof obj.category === 'string' ? obj.category.trim() : null,
        features: this.toStringArray(obj.features),
        benefits: this.toStringArray(obj.benefits),
        sellingPoints: this.toStringArray(obj.sellingPoints),
        usp: this.toStringArray(obj.usp),
        targetAudience: this.toStringArray(obj.targetAudience),
        useCases: this.toStringArray(obj.useCases),
        painPoints: this.toStringArray(obj.painPoints),
        pros: this.toStringArray(obj.pros),
        cons: this.toStringArray(obj.cons),
        marketingAngles: this.toMarketingAngles(obj.marketingAngles),
      };
    } catch {
      return null;
    }
  }

  private fallbackFromRaw(rawData: RawProductData): AiProductAnalysis {
    return {
      summary: rawData.description
        ? rawData.description.substring(0, 300)
        : rawData.title,
      category: rawData.category || null,
      features: rawData.features || [],
      benefits: [],
      sellingPoints: rawData.features ? rawData.features.slice(0, 5) : [],
      usp: [],
      targetAudience: [],
      useCases: [],
      painPoints: [],
      pros: [],
      cons: [],
      marketingAngles: [
        {
          title: 'Tổng quan sản phẩm',
          description: `Giới thiệu sản phẩm ${rawData.title || ''}`,
          hook: `Khám phá ngay ${rawData.title || 'sản phẩm hot nhât'}!`,
        },
      ],
    };
  }

  private toStringArray(value: unknown): string[] {
    if (!Array.isArray(value)) return [];
    return value
      .filter((item) => typeof item === 'string' && item.trim())
      .map((item) => String(item).trim());
  }

  private toMarketingAngles(value: unknown): MarketingAngle[] {
    if (!Array.isArray(value)) return [];
    return value
      .filter(
        (item) =>
          typeof item === 'object' &&
          item !== null &&
          typeof item.title === 'string',
      )
      .map((item: any) => ({
        title: String(item.title || '').trim(),
        description: String(item.description || '').trim(),
        hook: String(item.hook || '').trim(),
      }));
  }
}

import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { Prisma } from '@prisma/client';
import { PrismaService } from '../database/prisma.service';
import { ProductAnalysisService } from './product-analysis.service';
import { ContentBriefService } from './content-brief.service';
import { ProductSourceAdapter } from './adapters/product-source.adapter';
import { GenericProductAdapter } from './adapters/generic-product.adapter';
import { ShopeeAdapter } from './adapters/shopee.adapter';
import { LazadaAdapter } from './adapters/lazada.adapter';
import { TikTokShopAdapter } from './adapters/tiktok-shop.adapter';
import { AmazonAdapter } from './adapters/amazon.adapter';
import { InjectQueue } from '@nestjs/bullmq';
import { Queue } from 'bullmq';
import type { ProductResearchJobPayload } from './product-research.processor';
import type {
  ProductResearchResult,
  RawProductData,
  MarketingAngle,
} from './types/product-research.types';
import { ResearchStatus } from './types/product-research.types';
import { AssetDiscoveryService } from './asset-discovery.service';
import { UrlResolverService } from './url-resolver.service';

@Injectable()
export class ProductResearchService {
  private readonly logger = new Logger(ProductResearchService.name);
  private readonly adapters: ProductSourceAdapter[];
  private readonly resolver: UrlResolverService;

  constructor(
    private prisma: PrismaService,
    private productAnalysisService: ProductAnalysisService,
    private contentBriefService: ContentBriefService,
    private assetDiscoveryService: AssetDiscoveryService,
    private urlResolverService?: UrlResolverService,
    @InjectQueue('product-research')
    private researchQueue?: Queue<ProductResearchJobPayload>,
  ) {
    this.resolver = urlResolverService || new UrlResolverService();
    // Platform adapters registered in priority order before generic fallback
    this.adapters = [
      new ShopeeAdapter(),
      new LazadaAdapter(),
      new TikTokShopAdapter(),
      new AmazonAdapter(),
      new GenericProductAdapter(),
    ];
  }

  /**
   * API entrypoint: Accepts URL, selects adapter, creates pending Product record,
   * enqueues background worker job, and returns initial result immediately.
   */
  async researchProduct(url: string): Promise<ProductResearchResult> {
    this.logger.log(`[ProductResearch] Starting research for: ${url}`);

    if (!url || typeof url !== 'string' || !url.trim()) {
      throw new BadRequestException('Vui lòng cung cấp URL sản phẩm hợp lệ');
    }

    const cleanedUrl = url.trim();

    // Resolve & normalize URL before adapter selection
    const resolved = await this.resolver.resolveAndNormalizeUrl(cleanedUrl);
    const targetUrl = resolved.canonicalUrl || resolved.finalUrl;
    const adapter =
      this.selectAdapter(targetUrl) || this.selectAdapter(cleanedUrl);

    if (!adapter) {
      return {
        success: false,
        error: {
          code: 'NO_ADAPTER',
          message: 'Không hỗ trợ URL này. Vui lòng kiểm tra lại đường dẫn.',
        },
      };
    }

    // Create pending Product record
    const product = await this.prisma.product.create({
      data: {
        name: 'Đang nghiên cứu sản phẩm...',
        affiliateUrl: cleanedUrl,
        sourceUrl: targetUrl,
        sourcePlatform: adapter.name,
        researchStatus: ResearchStatus.PENDING,
      },
    });

    this.logger.log(
      `[Database] Initial pending Product created: ${product.id}`,
    );

    let jobId: string | undefined;

    // Enqueue job if BullMQ queue is available
    if (this.researchQueue) {
      try {
        const job = await this.researchQueue.add(
          'process-product-research',
          { productId: product.id, url: cleanedUrl },
          {
            attempts: 2,
            backoff: 5000,
            removeOnComplete: 100,
            removeOnFail: 200,
          },
        );
        jobId = job.id;
        this.logger.log(
          `[Worker] Enqueued research job ${jobId} for product ${product.id}`,
        );

        await this.prisma.product.update({
          where: { id: product.id },
          data: { researchStatus: ResearchStatus.PROCESSING },
        });
      } catch (queueErr) {
        this.logger.warn(
          `[Worker] Failed to enqueue job via Redis queue, falling back to inline execution: ${queueErr}`,
        );
        // Fallback to inline async execution
        this.executeResearchPipeline(product.id, cleanedUrl).catch((err) => {
          this.logger.error(
            `[Worker] Async inline research pipeline error: ${err}`,
          );
        });
      }
    } else {
      // Fallback to inline async execution
      this.executeResearchPipeline(product.id, cleanedUrl).catch((err) => {
        this.logger.error(
          `[Worker] Async inline research pipeline error: ${err}`,
        );
      });
    }

    return {
      success: true,
      jobId,
      product: this.mapProductToResult(product),
    };
  }

  /**
   * Worker / Queue Execution Pipeline:
   * Fetch -> Extract -> Normalize -> AI Analysis -> Content Brief -> DB Update
   */
  async executeResearchPipeline(
    productId: string,
    url: string,
  ): Promise<ProductResearchResult> {
    this.logger.log(
      `[ProductResearch] Executing pipeline for productId=${productId}`,
    );

    await this.prisma.product.update({
      where: { id: productId },
      data: { researchStatus: ResearchStatus.PROCESSING, researchError: null },
    });

    const resolved = await this.resolver.resolveAndNormalizeUrl(url);
    const targetUrl = resolved.canonicalUrl || resolved.finalUrl;
    const adapter = this.selectAdapter(targetUrl) || this.selectAdapter(url);

    if (!adapter) {
      throw new Error(`No adapter found for URL: ${targetUrl}`);
    }

    try {
      // Step 1: Extraction
      const platformName = adapter.name === 'shopee' ? 'Shopee' : adapter.name;
      this.logger.log(
        `[ProductResearch] Starting ${platformName} product extraction...`,
      );
      const rawData: RawProductData = await adapter.extract(targetUrl);

      if (
        !rawData.title &&
        !rawData.description &&
        rawData.images.length === 0
      ) {
        if (resolved.platform === 'shopee') {
          throw new Error(
            'Shopee product URL was resolved, but shop ID/item ID could not be extracted.',
          );
        }
        throw new Error(
          'Không thể trích xuất thông tin sản phẩm từ trang này. Trang có thể bị chặn hoặc không có nội dung.',
        );
      }

      this.logger.log(
        `[Normalize] Extracted raw product data: title="${rawData.title}", images=${rawData.images.length}, price="${rawData.price || 'N/A'}"`,
      );

      // Step 2: AI Analysis
      this.logger.log(`[AIAnalysis] Starting AI analysis...`);
      let aiAnalysis;
      let isPartial = false;

      try {
        aiAnalysis = await this.productAnalysisService.analyzeProduct(rawData);
        this.logger.log(
          `[AIAnalysis] Completed successfully: category="${aiAnalysis.category || 'N/A'}", angles=${aiAnalysis.marketingAngles.length}`,
        );
      } catch (aiErr) {
        isPartial = true;
        this.logger.warn(`[AIAnalysis] Warning during AI analysis: ${aiErr}`);
      }

      // Step 3: Content Brief Generation
      this.logger.log(
        `[ContentBrief] Generating reusable Product Content Brief...`,
      );
      const contentBrief = aiAnalysis
        ? this.contentBriefService.generateBrief(rawData, aiAnalysis)
        : null;

      // Step 4: DB Update
      const finalStatus = isPartial
        ? ResearchStatus.PARTIAL
        : ResearchStatus.COMPLETED;

      const derivedName =
        rawData.title?.trim() ||
        (contentBrief?.product && contentBrief.product !== 'Sản phẩm'
          ? contentBrief.product
          : null) ||
        (rawData.brand ? `Sản phẩm ${rawData.brand}` : null) ||
        (rawData.description ? rawData.description.substring(0, 60) : null) ||
        `Sản phẩm từ ${adapter.name}`;

      const updatedProduct = await this.prisma.product.update({
        where: { id: productId },
        data: {
          name: derivedName,
          brand: rawData.brand || aiAnalysis?.category || null,
          category: aiAnalysis?.category || rawData.category || null,
          description: rawData.description || aiAnalysis?.summary || null,
          price: rawData.price || null,
          originalPrice: rawData.originalPrice || null,
          currency: rawData.currency || 'VND',
          discountPercent: rawData.discountPercent || null,
          rating: rawData.rating || null,
          reviewCount: rawData.reviewCount || null,
          affiliateUrl: url,
          sourceUrl: targetUrl,
          sourcePlatform: adapter.name,
          images: rawData.images || [],
          videos: rawData.videos || [],
          features: aiAnalysis?.features || rawData.features || [],
          specifications: rawData.specifications
            ? (rawData.specifications as unknown as Prisma.InputJsonValue)
            : Prisma.DbNull,
          benefits: aiAnalysis?.benefits || [],
          pros: aiAnalysis?.pros || [],
          cons: aiAnalysis?.cons || [],
          targetAudience: aiAnalysis?.targetAudience
            ? aiAnalysis.targetAudience.join(', ')
            : null,
          useCases: aiAnalysis?.useCases || [],
          usp: aiAnalysis?.usp || aiAnalysis?.sellingPoints || [],
          painPoints: aiAnalysis?.painPoints || [],
          marketingAngles: aiAnalysis?.marketingAngles
            ? (aiAnalysis.marketingAngles as unknown as Prisma.InputJsonValue)
            : Prisma.DbNull,
          contentBrief: contentBrief
            ? (contentBrief as unknown as Prisma.InputJsonValue)
            : Prisma.DbNull,
          researchRawData: rawData as unknown as Prisma.InputJsonValue,
          researchStatus: finalStatus,
          researchedAt: new Date(),
          researchError: null,
        },
      });

      this.logger.log(
        `[Database] Product saved successfully: id=${updatedProduct.id}, status=${finalStatus}`,
      );

      // Trigger Automatic Product Asset Discovery asynchronously
      this.assetDiscoveryService
        .discoverAndImportAssets(updatedProduct.id)
        .catch((err) => {
          this.logger.error(
            `[AssetDiscovery] Automatic asset discovery error: ${err}`,
          );
        });

      return {
        success: true,
        product: this.mapProductToResult(updatedProduct),
      };
    } catch (error: unknown) {
      const errorMessage =
        error instanceof Error ? error.message : String(error);
      this.logger.error(
        `[ProductResearch] Pipeline failed for productId=${productId}: ${errorMessage}`,
      );

      const failedProduct = await this.prisma.product
        .update({
          where: { id: productId },
          data: {
            researchStatus: ResearchStatus.FAILED,
            researchError: errorMessage,
            name: 'Nghiên cứu thất bại',
          },
        })
        .catch(() => null);

      return {
        success: false,
        product: failedProduct
          ? this.mapProductToResult(failedProduct)
          : undefined,
        error: {
          code: 'RESEARCH_FAILED',
          message: errorMessage,
        },
      };
    }
  }

  // ---------------------------------------------------------------------------
  // Status and detail lookups
  // ---------------------------------------------------------------------------

  async getProductResearchStatus(id: string): Promise<ProductResearchResult> {
    const product = await this.prisma.product.findUnique({
      where: { id },
    });

    if (!product) {
      return {
        success: false,
        error: { code: 'NOT_FOUND', message: 'Không tìm thấy sản phẩm' },
      };
    }

    return {
      success: true,
      product: this.mapProductToResult(product),
    };
  }

  private selectAdapter(url: string): ProductSourceAdapter | null {
    for (const adapter of this.adapters) {
      if (adapter.canHandle(url)) {
        return adapter;
      }
    }
    return null;
  }

  private mapProductToResult(product: any) {
    return {
      id: product.id,
      name: product.name,
      brand: product.brand || null,
      category: product.category || null,
      description: product.description || null,
      price: product.price || null,
      originalPrice: product.originalPrice || null,
      currency: product.currency || 'VND',
      discountPercent: product.discountPercent || null,
      rating: product.rating || null,
      reviewCount: product.reviewCount || null,
      affiliateUrl: product.affiliateUrl,
      sourceUrl: product.sourceUrl || null,
      sourcePlatform: product.sourcePlatform || null,
      images: product.images || [],
      videos: product.videos || [],
      features: product.features || [],
      specifications: product.specifications || null,
      benefits: product.benefits || [],
      pros: product.pros || [],
      cons: product.cons || [],
      targetAudience: product.targetAudience || null,
      useCases: product.useCases || [],
      usp: product.usp || [],
      painPoints: product.painPoints || [],
      marketingAngles: product.marketingAngles as MarketingAngle[] | null,
      contentBrief: product.contentBrief,
      researchStatus: product.researchStatus || null,
      researchError: product.researchError || null,
      researchedAt: product.researchedAt || null,
      createdAt: product.createdAt,
      updatedAt: product.updatedAt,
    };
  }
}

import { Injectable, Logger, BadRequestException } from '@nestjs/common';

export interface ResolvedUrlResult {
  originalUrl: string;
  finalUrl: string;
  canonicalUrl: string;
  platform: string;
  urlType: 'direct_product_url' | 'affiliate_short_link' | 'generic_url';
  redirectHops: number;
  redirectChain: string[];
  shopeeIds?: {
    shopId: string;
    itemId: string;
  };
}

const BLOCKED_HOSTS = [
  'localhost',
  '127.0.0.1',
  '0.0.0.0',
  '[::1]',
  'metadata.google.internal',
  '169.254.169.254',
];

const BLOCKED_IP_PREFIXES = [
  '10.',
  '172.16.',
  '172.17.',
  '172.18.',
  '172.19.',
  '172.20.',
  '172.21.',
  '172.22.',
  '172.23.',
  '172.24.',
  '172.25.',
  '172.26.',
  '172.27.',
  '172.28.',
  '172.29.',
  '172.30.',
  '172.31.',
  '192.168.',
  '0.',
];

const MAX_REDIRECTS_DEFAULT = 10;
const FETCH_TIMEOUT_MS_DEFAULT = 10_000;

@Injectable()
export class UrlResolverService {
  private readonly logger = new Logger(UrlResolverService.name);

  /**
   * Main entrypoint to resolve and normalize product URLs.
   */
  async resolveAndNormalizeUrl(
    inputUrl: string,
    options?: { maxRedirects?: number; timeoutMs?: number },
  ): Promise<ResolvedUrlResult> {
    if (!inputUrl || typeof inputUrl !== 'string' || !inputUrl.trim()) {
      throw new BadRequestException('Vui lòng cung cấp URL sản phẩm hợp lệ');
    }

    const cleanedInput = inputUrl.trim();
    this.validateUrlSyntaxAndSecurity(cleanedInput);

    const safeInputLog = this.redactSensitiveParams(cleanedInput);
    this.logger.log(`[ProductResearch] Input URL: ${safeInputLog}`);

    const initialPlatformInfo = this.detectPlatform(cleanedInput);
    const urlType:
      'direct_product_url' | 'affiliate_short_link' | 'generic_url' =
      initialPlatformInfo.isShortLink
        ? 'affiliate_short_link'
        : initialPlatformInfo.platform !== 'generic'
          ? 'direct_product_url'
          : 'generic_url';

    this.logger.log(
      `[ProductResearch] Detected platform: ${initialPlatformInfo.platform}`,
    );
    this.logger.log(`[ProductResearch] URL type: ${urlType}`);

    let resolvedFinalUrl = cleanedInput;
    let redirectHops = 0;
    let redirectChain: string[] = [cleanedInput];

    // Always attempt redirect resolution if short link or if shopee url requires follow
    if (
      initialPlatformInfo.isShortLink ||
      initialPlatformInfo.platform === 'shopee'
    ) {
      this.logger.log(`[ProductResearch] Resolving URL...`);
      const res = await this.resolveRedirects(
        cleanedInput,
        options?.maxRedirects ?? MAX_REDIRECTS_DEFAULT,
        options?.timeoutMs ?? FETCH_TIMEOUT_MS_DEFAULT,
      );
      resolvedFinalUrl = res.finalUrl;
      redirectHops = res.hops;
      redirectChain = res.redirectChain;

      const safeFinalLog = this.redactSensitiveParams(resolvedFinalUrl);
      this.logger.log(`[ProductResearch] Redirect hops: ${redirectHops}`);
      this.logger.log(`[ProductResearch] Final URL: ${safeFinalLog}`);
    }

    // Re-detect platform on final URL in case short link redirected across platforms
    const finalPlatformInfo = this.detectPlatform(resolvedFinalUrl);
    const platform = finalPlatformInfo.platform;

    let canonicalUrl = resolvedFinalUrl;
    let shopeeIds: { shopId: string; itemId: string } | undefined;

    if (platform === 'shopee') {
      const extracted = this.extractShopeeIds(resolvedFinalUrl);
      if (extracted) {
        shopeeIds = { shopId: extracted.shopId, itemId: extracted.itemId };
        canonicalUrl = extracted.canonicalUrl;
        this.logger.log(
          `[ProductResearch] Extracted shopId: ${shopeeIds.shopId}`,
        );
        this.logger.log(
          `[ProductResearch] Extracted itemId: ${shopeeIds.itemId}`,
        );
        this.logger.log(
          `[ProductResearch] Canonical URL: ${this.redactSensitiveParams(canonicalUrl)}`,
        );
      } else if (initialPlatformInfo.isShortLink) {
        throw new BadRequestException(
          'The Shopee link was resolved successfully, but it does not point to a supported product page.',
        );
      }
    }

    return {
      originalUrl: cleanedInput,
      finalUrl: resolvedFinalUrl,
      canonicalUrl,
      platform,
      urlType,
      redirectHops,
      redirectChain,
      shopeeIds,
    };
  }

  /**
   * Safe HTTP Redirect Resolver with max hops, loop detection, timeout, and SSRF validation.
   */
  async resolveRedirects(
    startUrl: string,
    maxRedirects = MAX_REDIRECTS_DEFAULT,
    timeoutMs = FETCH_TIMEOUT_MS_DEFAULT,
  ): Promise<{ finalUrl: string; hops: number; redirectChain: string[] }> {
    let currentUrl = startUrl;
    let hops = 0;
    const visited = new Set<string>([startUrl]);
    const redirectChain: string[] = [startUrl];
    let cookiesToPass: string[] = [];

    while (hops < maxRedirects) {
      this.validateUrlSyntaxAndSecurity(currentUrl);

      const controller = new AbortController();
      const timeout = setTimeout(() => controller.abort(), timeoutMs);

      try {
        const headers: Record<string, string> = {
          'User-Agent':
            'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0.0.0 Safari/537.36',
          Accept:
            'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
          'Accept-Language': 'vi-VN,vi;q=0.9,en-US;q=0.8,en;q=0.7',
        };

        if (cookiesToPass.length > 0) {
          headers['Cookie'] = cookiesToPass.join('; ');
        }

        const response = await fetch(currentUrl, {
          method: 'GET',
          headers,
          redirect: 'manual',
          signal: controller.signal,
        });

        // Collect cookies set by redirect responses
        const setCookieHeader = response.headers.get('set-cookie');
        if (setCookieHeader) {
          const newCookies = setCookieHeader
            .split(',')
            .map((c) => c.split(';')[0].trim());
          cookiesToPass = Array.from(
            new Set([...cookiesToPass, ...newCookies]),
          );
        }

        const status = response.status;
        if ([301, 302, 303, 307, 308].includes(status)) {
          const location = response.headers.get('location');
          if (!location) {
            break;
          }

          let nextUrl: string;
          try {
            nextUrl = new URL(location, currentUrl).href;
          } catch {
            throw new BadRequestException(
              `Invalid redirect location header: ${location}`,
            );
          }

          if (visited.has(nextUrl)) {
            throw new BadRequestException(
              `Unable to resolve Shopee affiliate URL. Detection of redirect loop at: ${this.redactSensitiveParams(nextUrl)}`,
            );
          }

          visited.add(nextUrl);
          redirectChain.push(nextUrl);
          currentUrl = nextUrl;
          hops++;
          continue;
        }

        // Non-redirect response reached
        break;
      } catch (err: unknown) {
        if (err instanceof BadRequestException) {
          throw err;
        }
        if (err instanceof Error && err.name === 'AbortError') {
          throw new BadRequestException(
            'Unable to resolve Shopee affiliate URL. Request timed out during redirect resolution.',
          );
        }
        const msg = err instanceof Error ? err.message : String(err);
        throw new BadRequestException(
          `Unable to resolve Shopee affiliate URL. ${msg}`,
        );
      } finally {
        clearTimeout(timeout);
      }
    }

    if (hops >= maxRedirects) {
      throw new BadRequestException(
        `Unable to resolve Shopee affiliate URL. Exceeded maximum redirect limit (${maxRedirects} hops).`,
      );
    }

    return {
      finalUrl: currentUrl,
      hops,
      redirectChain,
    };
  }

  /**
   * Hostname platform detector with strict domain boundaries.
   */
  detectPlatform(urlStr: string): { platform: string; isShortLink: boolean } {
    try {
      const parsed = new URL(urlStr);
      const host = parsed.hostname.toLowerCase();

      // Shopee check
      if (
        host === 'shopee.vn' ||
        host.endsWith('.shopee.vn') ||
        host === 'shopee.com' ||
        host.endsWith('.shopee.com') ||
        host === 'shp.ee' ||
        host.endsWith('.shp.ee')
      ) {
        const isShort =
          host === 's.shopee.vn' ||
          host === 'shp.ee' ||
          host.endsWith('.shp.ee') ||
          parsed.pathname.startsWith('/universal-link');
        return { platform: 'shopee', isShortLink: isShort };
      }

      // Lazada check
      if (
        host === 'lazada.vn' ||
        host.endsWith('.lazada.vn') ||
        host === 's.lazada.vn'
      ) {
        return { platform: 'lazada', isShortLink: host === 's.lazada.vn' };
      }

      // TikTok Shop check
      if (
        host === 'tiktok.com' ||
        host.endsWith('.tiktok.com') ||
        host === 'vt.tiktok.com'
      ) {
        return { platform: 'tiktok', isShortLink: host === 'vt.tiktok.com' };
      }

      // Amazon check
      if (
        host === 'amazon.com' ||
        host.endsWith('.amazon.com') ||
        host === 'amzn.to'
      ) {
        return { platform: 'amazon', isShortLink: host === 'amzn.to' };
      }

      return { platform: 'generic', isShortLink: false };
    } catch {
      return { platform: 'generic', isShortLink: false };
    }
  }

  /**
   * Extract shopId and itemId from any Shopee URL format and produce canonical URL.
   */
  extractShopeeIds(
    urlStr: string,
  ): { shopId: string; itemId: string; canonicalUrl: string } | null {
    try {
      const parsed = new URL(urlStr);
      const pathname = parsed.pathname;

      let shopId: string | null = null;
      let itemId: string | null = null;

      // Pattern 1: /product/{shopId}/{itemId}
      const productMatch = pathname.match(/\/product\/(\d+)\/(\d+)/i);
      if (productMatch) {
        shopId = productMatch[1];
        itemId = productMatch[2];
      }

      // Pattern 2: /-i.{shopId}.{itemId} or /i.{shopId}.{itemId} or /any-name-i.{shopId}.{itemId}
      if (!shopId || !itemId) {
        const iMatch = pathname.match(/-?i\.(\d+)\.(\d+)/i);
        if (iMatch) {
          shopId = iMatch[1];
          itemId = iMatch[2];
        }
      }

      // Pattern 3: /{shopSlug}/{shopId}/{itemId} (e.g., /opaanlp/1016604648/23552060269)
      if (!shopId || !itemId) {
        const slugMatch = pathname.match(
          /\/([a-zA-Z0-9_\-\.]+)\/(\d+)\/(\d+)/i,
        );
        if (slugMatch) {
          shopId = slugMatch[2];
          itemId = slugMatch[3];
        }
      }

      // Pattern 4: Query parameters shopid / itemid or shop_id / item_id
      if (!shopId || !itemId) {
        const qShop =
          parsed.searchParams.get('shopid') ||
          parsed.searchParams.get('shop_id');
        const qItem =
          parsed.searchParams.get('itemid') ||
          parsed.searchParams.get('item_id');
        if (qShop && qItem && /^\d+$/.test(qShop) && /^\d+$/.test(qItem)) {
          shopId = qShop;
          itemId = qItem;
        }
      }

      if (shopId && itemId) {
        const canonicalUrl = `https://shopee.vn/product/${shopId}/${itemId}`;
        return { shopId, itemId, canonicalUrl };
      }

      return null;
    } catch {
      return null;
    }
  }

  /**
   * Redacts sensitive token values in URLs for safe logging.
   */
  redactSensitiveParams(urlStr: string): string {
    if (!urlStr) return urlStr;
    try {
      const parsed = new URL(urlStr);
      const sensitiveKeys = [
        'credential_token',
        'access_token',
        'token',
        'secret',
        'gads_t_sig',
        'auth',
      ];
      let modified = false;

      for (const key of sensitiveKeys) {
        if (parsed.searchParams.has(key)) {
          parsed.searchParams.set(key, '[REDACTED]');
          modified = true;
        }
      }

      return modified ? parsed.href : urlStr;
    } catch {
      return urlStr.replace(
        /(credential_token|access_token|token|secret|gads_t_sig)=[^&]+/gi,
        '$1=[REDACTED]',
      );
    }
  }

  private validateUrlSyntaxAndSecurity(urlStr: string): void {
    let parsed: URL;
    try {
      parsed = new URL(urlStr);
    } catch {
      throw new BadRequestException('URL không hợp lệ');
    }

    if (!['http:', 'https:'].includes(parsed.protocol)) {
      throw new BadRequestException('Chỉ hỗ trợ URL HTTP và HTTPS');
    }

    const hostname = parsed.hostname.toLowerCase();

    if (BLOCKED_HOSTS.includes(hostname)) {
      throw new BadRequestException('Không thể truy cập địa chỉ nội bộ');
    }

    if (BLOCKED_IP_PREFIXES.some((prefix) => hostname.startsWith(prefix))) {
      throw new BadRequestException('Không thể truy cập địa chỉ IP nội bộ');
    }
  }
}

import { UrlResolverService } from './url-resolver.service';
import { BadRequestException } from '@nestjs/common';

describe('UrlResolverService Unit Tests', () => {
