  describe('HTTP Redirect Resolution', () => {
    it('Test 4 — Multiple redirect hops (mocked fetch)', async () => {
      const mockFetch = jest
        .fn()
        .mockResolvedValueOnce({
          status: 301,
          headers: new Map([['location', 'https://redirect-a.com/step1']]),
        })
        .mockResolvedValueOnce({
          status: 302,
          headers: new Map([
            ['location', 'https://shopee.vn/product/1016604648/23552060269'],
          ]),
        })
        .mockResolvedValueOnce({
          status: 200,
          headers: new Map(),
        });

      global.fetch = mockFetch as any;

      const result = await resolver.resolveRedirects(
        'https://s.shopee.vn/mock-short',
      );

      expect(result.hops).toBe(2);
      expect(result.finalUrl).toBe(
        'https://shopee.vn/product/1016604648/23552060269',
      );
      expect(result.redirectChain).toEqual([
        'https://s.shopee.vn/mock-short',
        'https://redirect-a.com/step1',
        'https://shopee.vn/product/1016604648/23552060269',
      ]);
    });

    it('Test 5 — Redirect loop protection', async () => {
      const mockFetch = jest
        .fn()
        .mockResolvedValueOnce({
          status: 301,
          headers: new Map([['location', 'https://redirect-b.com/loop']]),
        })
        .mockResolvedValueOnce({
          status: 301,
          headers: new Map([['location', 'https://redirect-a.com/loop']]),
        });

      global.fetch = mockFetch as any;

      await expect(
        resolver.resolveRedirects('https://redirect-a.com/loop', 10),
      ).rejects.toThrow(BadRequestException);
    });

    it('Exceeds maximum redirect count', async () => {
      let count = 0;
      const mockFetch = jest.fn().mockImplementation(() => {
        count++;
        return Promise.resolve({
          status: 301,
          headers: new Map([
            ['location', `https://infinite-redirect.com/next-${count}`],
          ]),
        });
      });

      global.fetch = mockFetch as any;

      await expect(
        resolver.resolveRedirects('https://infinite-redirect.com/start', 3),
      ).rejects.toThrow('Exceeded maximum redirect limit');
    });
  });

  describe('Validation & Security', () => {
    it('Test 6 — Unsupported URL platform detection', () => {
      const url = 'https://example.com/product/123';
      const platformInfo = resolver.detectPlatform(url);
      expect(platformInfo.platform).toBe('generic');
      expect(platformInfo.isShortLink).toBe(false);
    });

    it('Test 7 — Invalid / Unsafe URL validation', async () => {
      await expect(resolver.resolveAndNormalizeUrl('')).rejects.toThrow(
        BadRequestException,
      );
      await expect(
        resolver.resolveAndNormalizeUrl('not-a-url'),
      ).rejects.toThrow(BadRequestException);
      await expect(resolver.resolveAndNormalizeUrl('https://')).rejects.toThrow(
        BadRequestException,
      );
      await expect(
        resolver.resolveAndNormalizeUrl('http://127.0.0.1/admin'),
      ).rejects.toThrow('Không thể truy cập địa chỉ nội bộ');
      await expect(
        resolver.resolveAndNormalizeUrl('http://169.254.169.254/metadata'),
      ).rejects.toThrow('Không thể truy cập địa chỉ nội bộ');
    });

    it('Test 8 — Redaction of sensitive parameters in logs', () => {
      const sensitiveUrl =
        'https://shopee.vn/product/123/456?credential_token=secret_12345&access_token=token_abc&other=normal';
      const redacted = resolver.redactSensitiveParams(sensitiveUrl);

      expect(redacted).not.toContain('secret_12345');
      expect(redacted).not.toContain('token_abc');
      expect(redacted).toContain('credential_token=%5BREDACTED%5D');
      expect(redacted).toContain('other=normal');
    });
  });
});

import {
  Injectable,
  NotFoundException,
  Logger,
  BadRequestException,
} from '@nestjs/common';
import { PrismaService } from '../database/prisma.service';
import { QueueService, type VideoJobConfig } from '../queue/queue.service';
import { StorageService } from '../storage/storage.service';
import { Prisma } from '@prisma/client';

export type CreateProductDto = {
  name: string;
  brand?: string;
  category?: string;
  description?: string;
  price?: string;
  originalPrice?: string;
  currency?: string;
  discountPercent?: number;
  rating?: number;
  reviewCount?: number;
  affiliateUrl: string;
  sourceUrl?: string;
  sourcePlatform?: string;
  features?: string[];
  specifications?: Record<string, any>;
  benefits?: string[];
  pros?: string[];
  cons?: string[];
  targetAudience?: string;
  useCases?: string[];
  usp?: string[];
  painPoints?: string[];
  marketingAngles?: any;
  contentBrief?: any;
  images?: string[];
  videos?: string[];
};

export type UpdateProductDto = Partial<CreateProductDto>;

@Injectable()
export class ProductsService {
  private readonly logger = new Logger(ProductsService.name);

  constructor(
    private prisma: PrismaService,
    private queueService: QueueService,
    private storageService: StorageService,
  ) {}

  async uploadAsset(file: any): Promise<{ url: string; key: string }> {
    if (!file || !file.buffer) {
      throw new BadRequestException('Vui lòng chọn file hợp lệ để tải lên');
    }

    const timestamp = Date.now();
    const originalName = file.originalname || 'asset.bin';
    const cleanFilename = originalName.replace(/[^a-zA-Z0-9._-]/g, '_');
    const key = `product-assets/${timestamp}-${cleanFilename}`;
    const contentType = file.mimetype || 'application/octet-stream';

    this.logger.log(
      `[ProductsService] Uploading asset ${key} (${file.size} bytes, ${contentType})`,
    );
    await this.storageService.uploadBuffer(file.buffer, key, contentType);

    const url = await this.storageService.getDownloadUrl(key, 86400 * 365);
    return { url, key };
  }

  async getAssetStream(key: string, range?: string) {
    return this.storageService.getFileStream(key, range);
  }

  async create(dto: CreateProductDto) {
    return this.prisma.product.create({
      data: {
        name: dto.name,
        brand: dto.brand,
        category: dto.category,
        description: dto.description,
        price: dto.price,
        originalPrice: dto.originalPrice,
        currency: dto.currency || 'VND',
        discountPercent: dto.discountPercent,
        rating: dto.rating,
        reviewCount: dto.reviewCount,
        affiliateUrl: dto.affiliateUrl,
        sourceUrl: dto.sourceUrl || dto.affiliateUrl,
        sourcePlatform: dto.sourcePlatform || 'generic',
        features: dto.features || [],
        specifications: dto.specifications
          ? (dto.specifications as unknown as Prisma.InputJsonValue)
          : Prisma.DbNull,
        benefits: dto.benefits || [],
        pros: dto.pros || [],
        cons: dto.cons || [],
        targetAudience: dto.targetAudience,
        useCases: dto.useCases || [],
        usp: dto.usp || [],
        painPoints: dto.painPoints || [],
        marketingAngles: dto.marketingAngles
          ? (dto.marketingAngles as unknown as Prisma.InputJsonValue)
          : Prisma.DbNull,
        contentBrief: dto.contentBrief
          ? (dto.contentBrief as unknown as Prisma.InputJsonValue)
          : Prisma.DbNull,
        images: dto.images || [],
        videos: dto.videos || [],
      },
    });
  }

  async findAll() {
    return this.prisma.product.findMany({
      include: {
        _count: {
          select: { ideas: true, jobs: true },
        },
      },
      orderBy: { createdAt: 'desc' },
    });
  }

  async findOne(id: string) {
    const product = await this.prisma.product.findUnique({
      where: { id },
      include: {
        ideas: {
          orderBy: { createdAt: 'desc' },
          take: 10,
        },
        jobs: {
          orderBy: { createdAt: 'desc' },
          include: {
            videos: true,
          },
          take: 10,
        },
      },
    });

    if (!product) {
      throw new NotFoundException('Không tìm thấy sản phẩm');
    }

    return product;
  }

  async update(id: string, dto: UpdateProductDto) {
    await this.findOne(id);
    return this.prisma.product.update({
      where: { id },
      data: {
        ...(dto.name && { name: dto.name }),
        ...(dto.brand !== undefined && { brand: dto.brand }),
        ...(dto.category !== undefined && { category: dto.category }),
        ...(dto.description !== undefined && { description: dto.description }),
        ...(dto.price !== undefined && { price: dto.price }),
        ...(dto.originalPrice !== undefined && {
          originalPrice: dto.originalPrice,
        }),
        ...(dto.currency && { currency: dto.currency }),
        ...(dto.discountPercent !== undefined && {
          discountPercent: dto.discountPercent,
        }),
        ...(dto.rating !== undefined && { rating: dto.rating }),
        ...(dto.reviewCount !== undefined && { reviewCount: dto.reviewCount }),
        ...(dto.affiliateUrl && { affiliateUrl: dto.affiliateUrl }),
        ...(dto.sourceUrl !== undefined && { sourceUrl: dto.sourceUrl }),
        ...(dto.sourcePlatform && { sourcePlatform: dto.sourcePlatform }),
        ...(dto.features && { features: dto.features }),
        ...(dto.specifications !== undefined && {
          specifications: dto.specifications
            ? (dto.specifications as unknown as Prisma.InputJsonValue)
            : Prisma.DbNull,
        }),
        ...(dto.benefits && { benefits: dto.benefits }),
        ...(dto.pros && { pros: dto.pros }),
        ...(dto.cons && { cons: dto.cons }),
        ...(dto.targetAudience !== undefined && {
          targetAudience: dto.targetAudience,
        }),
        ...(dto.useCases && { useCases: dto.useCases }),
        ...(dto.usp && { usp: dto.usp }),
        ...(dto.painPoints && { painPoints: dto.painPoints }),
        ...(dto.marketingAngles !== undefined && {
          marketingAngles: dto.marketingAngles
            ? (dto.marketingAngles as unknown as Prisma.InputJsonValue)
            : Prisma.DbNull,
        }),
        ...(dto.contentBrief !== undefined && {
          contentBrief: dto.contentBrief
            ? (dto.contentBrief as unknown as Prisma.InputJsonValue)
            : Prisma.DbNull,
        }),
        ...(dto.images && { images: dto.images }),
        ...(dto.videos && { videos: dto.videos }),
      },
    });
  }

  async remove(id: string) {
    await this.findOne(id);
    return this.prisma.product.delete({
      where: { id },
    });
  }

  /**
   * Integrated Video Generation pipeline:
   * Consumes product research data (Content Brief, selling points, marketing angles)
   * to enrich AI video script generation while maintaining 100% backward compatibility.
   */
  async generateVideo(id: string, config: VideoJobConfig = {}) {
    const product = await this.findOne(id);

    // Build rich context for video script generator if research contentBrief exists
    let topicDescription = product.description || `Sản phẩm: ${product.name}`;
    if (product.contentBrief && typeof product.contentBrief === 'object') {
      const brief = product.contentBrief as any;
      topicDescription = `[Product Content Brief]\nProduct: ${product.name}\nTarget Audience: ${brief.targetAudience || product.targetAudience || 'Khách hàng'}\nMain Pain Point: ${brief.mainPainPoint || ''}\nMain Benefit: ${brief.mainBenefit || ''}\nHook: ${brief.recommendedHook || ''}\nCTA: ${brief.recommendedCTA || ''}`;
    }

    // Create Idea associated with product
    const idea = await this.prisma.idea.create({
      data: {
        title: product.name,
        topic: product.name,
        description: topicDescription,
        language: 'vi',
        status: 'ready',
        productId: product.id,
      },
    });

    // Create GenerationJob associated with idea and product
    const job = await this.prisma.generationJob.create({
      data: {
        ideaId: idea.id,
        productId: product.id,
        status: 'queued',
        config,
      },
    });

    // Queue video generation job
    await this.queueService.addVideoJob(
      job.id,
      idea.id,
      product.name,
      undefined,
      'vi',
      {
        ...config,
        productId: product.id,
      },
    );

    this.logger.log(
      `[VideoIntegration] Created video job ${job.id} with product research brief context for product ${product.id}`,
    );

    return {
      product,
      idea,
      job,
    };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { PlatformAccount } from '@prisma/client';
import axios from 'axios';
import {
  PlatformAdapter,
  PlatformType,
  PublishParams,
  PublishResult,
  PlatformMetrics,
  OAuthAuthUrlResult,
  OAuthTokenResult,
} from './platform-adapter.interface';
import { EncryptionService } from '../encryption.service';

@Injectable()
export class FacebookAdapter implements PlatformAdapter {
  readonly platform: PlatformType = 'FACEBOOK';
  private readonly logger = new Logger(FacebookAdapter.name);

  constructor(
    private readonly configService: ConfigService,
    private readonly encryptionService: EncryptionService,
  ) {}

  getMissingConfig(): string[] {
    const missing: string[] = [];
    const appId = (
      this.configService.get<string>('FACEBOOK_CLIENT_ID') ||
      this.configService.get<string>('FACEBOOK_APP_ID') ||
      ''
    ).trim();
    const appSecret = (
      this.configService.get<string>('FACEBOOK_CLIENT_SECRET') ||
      this.configService.get<string>('FACEBOOK_APP_SECRET') ||
      ''
    ).trim();

    if (!appId) missing.push('FACEBOOK_APP_ID');
    if (!appSecret) missing.push('FACEBOOK_APP_SECRET');

    return missing;
  }

  isConfigured(): boolean {
    return this.getMissingConfig().length === 0;
  }

  getAuthUrl(redirectUri: string, state = 'facebook_auth'): OAuthAuthUrlResult {
    const appId =
      this.configService.get<string>('FACEBOOK_CLIENT_ID') ||
      this.configService.get<string>('FACEBOOK_APP_ID') ||
      '';
    const scope =
      'pages_show_list,pages_read_engagement,pages_manage_posts,publish_video';
    const url = `https://www.facebook.com/v19.0/dialog/oauth?client_id=${encodeURIComponent(appId)}&redirect_uri=${encodeURIComponent(redirectUri)}&scope=${encodeURIComponent(scope)}&response_type=code&state=${encodeURIComponent(state)}`;
    return { url, state };
  }

  async handleCallback(
    code: string,
    redirectUri: string,
  ): Promise<OAuthTokenResult> {
    const appId =
      this.configService.get<string>('FACEBOOK_CLIENT_ID') ||
      this.configService.get<string>('FACEBOOK_APP_ID') ||
      '';
    const appSecret =
      this.configService.get<string>('FACEBOOK_CLIENT_SECRET') ||
      this.configService.get<string>('FACEBOOK_APP_SECRET') ||
      '';

    if (!appId || !appSecret) {
      throw new Error('Facebook app ID or secret is not configured.');
    }

    try {
      const tokenRes = await axios.get(
        `https://graph.facebook.com/v19.0/oauth/access_token?client_id=${appId}&redirect_uri=${encodeURIComponent(redirectUri)}&client_secret=${appSecret}&code=${code}`,
      );

      const userToken = tokenRes.data.access_token;
      const expiresIn = tokenRes.data.expires_in || 5184000;

      // Get Page Access Token from Graph API
      const pagesRes = await axios.get(
        `https://graph.facebook.com/v19.0/me/accounts?access_token=${userToken}`,
      );

      const pages = pagesRes.data?.data;
      if (!Array.isArray(pages) || pages.length === 0) {
        throw new Error(
          'Facebook authorization succeeded, but no Facebook Page was found for this user account. A Facebook Page is required to publish Facebook Reels.',
        );
      }

      const page = pages[0];
      const accountId = page.id;
      const accountName = page.name || 'Facebook Page';
      const pageAccessToken = page.access_token || userToken;

      if (!accountId || accountId === 'facebook_page') {
        throw new Error(
          'Could not resolve valid Facebook Page ID from user accounts.',
        );
      }

      return {
        accessToken: pageAccessToken,
        expiresAt: new Date(Date.now() + expiresIn * 1000),
        accountId,
        accountName,
      };
    } catch (err: any) {
      if (axios.isAxiosError(err) && err.response?.data?.error) {
        const metaErr = err.response.data.error;
        this.logger.error(`Facebook OAuth error: ${JSON.stringify(metaErr)}`);
        throw new Error(
          `Facebook OAuth token exchange failed: ${metaErr.message || JSON.stringify(metaErr)}`,
        );
      }
      throw err;
    }
  }

  async publish(
    account: PlatformAccount,
    params: PublishParams,
  ): Promise<PublishResult> {
    const decryptedToken = this.encryptionService.decrypt(account.accessToken);

    if (!this.isConfigured() || !decryptedToken || !account.accountId) {
      this.logger.warn(
        `Facebook Reels publishing failed: Adapter not fully configured or missing page token/ID for account ${account.id}`,
      );
      return {
        success: false,
        errorCode: 'NOT_CONFIGURED',
        errorMessage:
          'Facebook Reels API is not fully configured with Graph API app credentials or connected Page account.',
      };
    }

    try {
      const description =
        params.description || params.caption || params.title || '';

      // Step 1: Start upload phase for Facebook Video Reel
      const startRes = await axios.post(
        `https://graph.facebook.com/v19.0/${account.accountId}/video_reels`,
        {
          upload_phase: 'start',
          access_token: decryptedToken,
        },
      );

      const videoId = startRes.data?.video_id;
      const uploadUrl = startRes.data?.upload_url;

      if (!videoId) {
        return {
          success: false,
          errorCode: 'REEL_START_FAILED',
          errorMessage:
            'Facebook Graph API did not initialize Reel upload session.',
          rawResponse: startRes.data,
        };
      }

      // Step 2: Upload file / URL
      if (uploadUrl && params.videoBuffer) {
        await axios.post(uploadUrl, params.videoBuffer, {
          headers: {
            Authorization: `OAuth ${decryptedToken}`,
            file_url: params.downloadUrl,
          },
        });
      }

      // Step 3: Finish upload phase
      const finishRes = await axios.post(
        `https://graph.facebook.com/v19.0/${account.accountId}/video_reels`,
        {
          upload_phase: 'finish',
          video_id: videoId,
          video_state: 'PUBLISHED',
          description,
          access_token: decryptedToken,
        },
      );

      return {
        success: Boolean(finishRes.data?.success || videoId),
        platformPostId: videoId,
        platformUrl: `https://www.facebook.com/reel/${videoId}`,
        publishedAt: new Date(),
        rawResponse: finishRes.data,
      };
    } catch (error: any) {
      this.logger.error(
        `Facebook Reels publish request failed: ${error.message}`,
        error.stack,
      );
      return {
        success: false,
        errorCode: error.response?.data?.error?.code || 'FACEBOOK_API_ERROR',
        errorMessage:
          error.response?.data?.error?.message ||
          error.message ||
          'Error executing Facebook API request.',
        rawResponse: error.response?.data,
      };
    }
  }

  async getPostStatus(
    account: PlatformAccount,
    platformPostId: string,
  ): Promise<PublishResult> {
    const decryptedToken = this.encryptionService.decrypt(account.accessToken);
    if (!decryptedToken) {
      return {
        success: false,
        errorCode: 'NOT_CONFIGURED',
        errorMessage: 'Missing access token.',
      };
    }

    try {
      const response = await axios.get(
        `https://graph.facebook.com/v19.0/${platformPostId}?fields=id,status&access_token=${decryptedToken}`,
      );

      return {
        success: Boolean(response.data?.id),
        platformPostId: response.data?.id || platformPostId,
        platformUrl: `https://www.facebook.com/reel/${platformPostId}`,
        rawResponse: response.data,
      };
    } catch (error: any) {
      return {
        success: false,
        errorCode: 'STATUS_CHECK_FAILED',
        errorMessage: error.message,
      };
    }
  }

  async fetchAnalytics(
    account: PlatformAccount,
    platformPostId: string,
  ): Promise<PlatformMetrics> {
    const decryptedToken = this.encryptionService.decrypt(account.accessToken);
    if (!decryptedToken) {
      return {
        views: 0,
        likes: 0,
        comments: 0,
        shares: 0,
        saves: 0,
        clicks: 0,
      };
    }

    try {
      const response = await axios.get(
        `https://graph.facebook.com/v19.0/${platformPostId}?fields=views,likes.summary(true),comments.summary(true),shares&access_token=${decryptedToken}`,
      );

      const data = response.data || {};
      const views = Number(data.views || 0);
      const likes = Number(data.likes?.summary?.total_count || 0);
      const comments = Number(data.comments?.summary?.total_count || 0);
      const shares = Number(data.shares?.count || 0);
      const engagementRate =
        views > 0 ? (likes + comments + shares) / views : 0;

      return {
        views,
        likes,
        comments,
        shares,
        saves: 0,
        clicks: 0,
        engagementRate,
        rawMetadata: data,
      };
    } catch (error) {
      this.logger.warn(
        `Failed to fetch Facebook analytics for post ${platformPostId}: ${(error as Error).message}`,
      );
      return {
        views: 0,
        likes: 0,
        comments: 0,
        shares: 0,
        saves: 0,
        clicks: 0,
      };
    }
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { PlatformAccount } from '@prisma/client';
import axios from 'axios';
import {
  PlatformAdapter,
  PlatformType,
  PublishParams,
  PublishResult,
  PlatformMetrics,
  OAuthAuthUrlResult,
  OAuthTokenResult,
} from './platform-adapter.interface';
import { EncryptionService } from '../encryption.service';

@Injectable()
export class InstagramAdapter implements PlatformAdapter {
  readonly platform: PlatformType = 'INSTAGRAM';
  private readonly logger = new Logger(InstagramAdapter.name);

  constructor(
    private readonly configService: ConfigService,
    private readonly encryptionService: EncryptionService,
  ) {}

  getMissingConfig(): string[] {
    const missing: string[] = [];
    const appId = (
      this.configService.get<string>('INSTAGRAM_CLIENT_ID') ||
      this.configService.get<string>('FACEBOOK_APP_ID') ||
      ''
    ).trim();
    const appSecret = (
      this.configService.get<string>('INSTAGRAM_CLIENT_SECRET') ||
      this.configService.get<string>('FACEBOOK_APP_SECRET') ||
      ''
    ).trim();

    if (!appId) missing.push('INSTAGRAM_CLIENT_ID (or FACEBOOK_APP_ID)');
    if (!appSecret)
      missing.push('INSTAGRAM_CLIENT_SECRET (or FACEBOOK_APP_SECRET)');

    return missing;
  }

  isConfigured(): boolean {
    return this.getMissingConfig().length === 0;
  }

  getAuthUrl(
    redirectUri: string,
    state = 'instagram_auth',
  ): OAuthAuthUrlResult {
    const appId =
      this.configService.get<string>('INSTAGRAM_CLIENT_ID') ||
      this.configService.get<string>('FACEBOOK_APP_ID') ||
      '';
    const scope =
      'instagram_basic,instagram_content_publish,instagram_manage_insights,pages_show_list,pages_read_engagement';
    const url = `https://www.facebook.com/v19.0/dialog/oauth?client_id=${encodeURIComponent(appId)}&redirect_uri=${encodeURIComponent(redirectUri)}&scope=${encodeURIComponent(scope)}&response_type=code&state=${encodeURIComponent(state)}`;
    return { url, state };
  }

  async handleCallback(
    code: string,
    redirectUri: string,
  ): Promise<OAuthTokenResult> {
    const appId =
      this.configService.get<string>('INSTAGRAM_CLIENT_ID') ||
      this.configService.get<string>('FACEBOOK_APP_ID') ||
      '';
    const appSecret =
      this.configService.get<string>('INSTAGRAM_CLIENT_SECRET') ||
      this.configService.get<string>('FACEBOOK_APP_SECRET') ||
      '';

    if (!appId || !appSecret) {
      throw new Error('Instagram app ID or secret is not configured.');
    }

    try {
      const tokenRes = await axios.get(
        `https://graph.facebook.com/v19.0/oauth/access_token?client_id=${appId}&redirect_uri=${encodeURIComponent(redirectUri)}&client_secret=${appSecret}&code=${code}`,
      );

      const accessToken = tokenRes.data.access_token;
      const expiresIn = tokenRes.data.expires_in || 5184000;

      // 1. Fetch user's Facebook pages
      const meRes = await axios.get(
        `https://graph.facebook.com/v19.0/me/accounts?access_token=${accessToken}`,
      );

      const pages = meRes.data?.data;
      if (!Array.isArray(pages) || pages.length === 0) {
        throw new Error(
          'Instagram connection failed: No Facebook Page was found for this Meta account. Instagram Business publishing requires a Facebook Page linked to an Instagram Professional account.',
        );
      }

      // 2. Search pages for a connected Instagram Business/Creator Account
      let accountId: string | null = null;
      let accountName = 'Instagram Account';

      for (const page of pages) {
        const pageId = page.id;
        const igRes = await axios.get(
          `https://graph.facebook.com/v19.0/${pageId}?fields=instagram_business_account,name&access_token=${accessToken}`,
        );

        const igBusinessId = igRes.data?.instagram_business_account?.id;
        if (igBusinessId) {
          accountId = igBusinessId;

          // Fetch real Instagram username
          try {
            const igUserRes = await axios.get(
              `https://graph.facebook.com/v19.0/${igBusinessId}?fields=username,name&access_token=${accessToken}`,
            );
            if (igUserRes.data?.username) {
              accountName = `@${igUserRes.data.username}`;
            } else {
              accountName = `@${igRes.data.name || 'ig_user'}`;
            }
          } catch {
            accountName = `@${igRes.data.name || 'ig_user'}`;
          }
          break;
        }
      }

      if (!accountId || accountId === 'instagram_account') {
        throw new Error(
          'Instagram authorization succeeded, but no Instagram Professional (Business or Creator) account was found linked to your Facebook Page(s). Please connect an Instagram Professional account to a Facebook Page in Meta Business Suite.',
        );
      }

      return {
        accessToken,
        expiresAt: new Date(Date.now() + expiresIn * 1000),
        accountId,
        accountName,
      };
    } catch (err: any) {
      if (axios.isAxiosError(err) && err.response?.data?.error) {
        const metaErr = err.response.data.error;
        this.logger.error(`Instagram OAuth error: ${JSON.stringify(metaErr)}`);
        throw new Error(
          `Instagram OAuth token exchange failed: ${metaErr.message || JSON.stringify(metaErr)}`,
        );
      }
      throw err;
    }
  }

  async publish(
    account: PlatformAccount,
    params: PublishParams,
  ): Promise<PublishResult> {
    const decryptedToken = this.encryptionService.decrypt(account.accessToken);

    if (!this.isConfigured() || !decryptedToken || !account.accountId) {
      this.logger.warn(
        `Instagram Reels publishing failed: Adapter not fully configured or missing account ID/token for account ${account.id}`,
      );
      return {
        success: false,
        errorCode: 'NOT_CONFIGURED',
        errorMessage:
          'Instagram Reels API is not fully configured with Graph API credentials or connected account.',
      };
    }

    try {
      const captionText = [
        params.caption || params.title || '',
        ...(params.hashtags || []).map((h) =>
          h.startsWith('#') ? h : `#${h}`,
        ),
      ]
        .filter(Boolean)
        .join(' ');

      // Step 1: Create Container
      const createContainerRes = await axios.post(
        `https://graph.facebook.com/v19.0/${account.accountId}/media`,
        {
          media_type: 'REELS',
          video_url: params.downloadUrl,
          caption: captionText,
          access_token: decryptedToken,
        },
      );

      const creationId = createContainerRes.data?.id;
      if (!creationId) {
        return {
          success: false,
          errorCode: 'CONTAINER_CREATION_FAILED',
          errorMessage: 'Instagram API did not return container creation ID.',
          rawResponse: createContainerRes.data,
        };
      }

      // Step 2: Wait / Poll Container Status
      let isReady = false;
      let attempts = 0;
      while (!isReady && attempts < 10) {
        await new Promise((res) => setTimeout(res, 2000));
        attempts++;
        const statusRes = await axios.get(
          `https://graph.facebook.com/v19.0/${creationId}?fields=status_code,status&access_token=${decryptedToken}`,
        );
        const statusCode = statusRes.data?.status_code;
        if (statusCode === 'FINISHED') {
          isReady = true;
        } else if (statusCode === 'ERROR') {
          return {
            success: false,
            errorCode: 'PROCESSING_ERROR',
            errorMessage: 'Instagram media container processing failed.',
            rawResponse: statusRes.data,
          };
        }
      }

      // Step 3: Publish Container
      const publishRes = await axios.post(
        `https://graph.facebook.com/v19.0/${account.accountId}/media_publish`,
        {
          creation_id: creationId,
          access_token: decryptedToken,
        },
      );

      const mediaId = publishRes.data?.id;
      return {
        success: Boolean(mediaId),
        platformPostId: mediaId || creationId,
        platformUrl: mediaId
          ? `https://www.instagram.com/p/${mediaId}`
          : undefined,
        publishedAt: new Date(),
        rawResponse: publishRes.data,
      };
    } catch (error: any) {
      this.logger.error(
        `Instagram Reels publish request failed: ${error.message}`,
        error.stack,
      );
      return {
        success: false,
        errorCode: error.response?.data?.error?.code || 'INSTAGRAM_API_ERROR',
        errorMessage:
          error.response?.data?.error?.message ||
          error.message ||
          'Error executing Instagram API request.',
        rawResponse: error.response?.data,
      };
    }
  }

  async getPostStatus(
    account: PlatformAccount,
    platformPostId: string,
  ): Promise<PublishResult> {
    const decryptedToken = this.encryptionService.decrypt(account.accessToken);
    if (!decryptedToken) {
      return {
        success: false,
        errorCode: 'NOT_CONFIGURED',
        errorMessage: 'Missing access token.',
      };
    }

    try {
      const response = await axios.get(
        `https://graph.facebook.com/v19.0/${platformPostId}?fields=id,timestamp,permalink&access_token=${decryptedToken}`,
      );

      return {
        success: Boolean(response.data?.id),
        platformPostId: response.data?.id || platformPostId,
        platformUrl: response.data?.permalink,
        rawResponse: response.data,
      };
    } catch (error: any) {
      return {
        success: false,
        errorCode: 'STATUS_CHECK_FAILED',
        errorMessage: error.message,
      };
    }
  }

  async fetchAnalytics(
    account: PlatformAccount,
    platformPostId: string,
  ): Promise<PlatformMetrics> {
    const decryptedToken = this.encryptionService.decrypt(account.accessToken);
    if (!decryptedToken) {
      return {
        views: 0,
        likes: 0,
        comments: 0,
        shares: 0,
        saves: 0,
        clicks: 0,
      };
    }

    try {
      const response = await axios.get(
        `https://graph.facebook.com/v19.0/${platformPostId}/insights?metric=plays,reach,likes,comments,shares,saved&access_token=${decryptedToken}`,
      );

      const dataList = response.data?.data || [];
      const getVal = (name: string) => {
        const item = dataList.find((i: any) => i.name === name);
        return item?.values?.[0]?.value || 0;
      };

      const views = getVal('plays') || getVal('reach');
      const likes = getVal('likes');
      const comments = getVal('comments');
      const shares = getVal('shares');
      const saves = getVal('saved');
      const engagementRate =
        views > 0 ? (likes + comments + shares + saves) / views : 0;

      return {
        views,
        likes,
        comments,
        shares,
        saves,
        clicks: 0,
        engagementRate,
        rawMetadata: response.data,
      };
    } catch (error) {
      this.logger.warn(
        `Failed to fetch Instagram analytics for post ${platformPostId}: ${(error as Error).message}`,
      );
      return {
        views: 0,
        likes: 0,
        comments: 0,
        shares: 0,
        saves: 0,
        clicks: 0,
      };
    }
  }
}

import { PlatformAccount, PublishJob } from '@prisma/client';
import { Readable } from 'stream';

export type PlatformType = 'TIKTOK' | 'YOUTUBE' | 'INSTAGRAM' | 'FACEBOOK';

export interface PublishParams {
  jobId: string;
  videoId: string;
  title?: string;
  description?: string;
  caption?: string;
  hashtags?: string[];
  tags?: string[];
  privacyStatus?: string;
  platformMetadata?: Record<string, any>;
  videoStream?: Readable;
  videoBuffer?: Buffer;
  mimeType?: string;
  downloadUrl?: string;
}

export interface PublishResult {
  success: boolean;
  platformPostId?: string;
  platformUrl?: string;
  publishedAt?: Date;
  errorMessage?: string;
  errorCode?: string;
  rawResponse?: any;
}

export interface PlatformMetrics {
  views: number;
  likes: number;
  comments: number;
  shares: number;
  saves: number;
  clicks: number;
  watchTime?: number;
  averageWatchTime?: number;
  completionRate?: number;
  engagementRate?: number;
  rawMetadata?: any;
}

export interface OAuthAuthUrlResult {
  url: string;
  state?: string;
}

export interface OAuthTokenResult {
  accessToken: string;
  refreshToken?: string;
  expiresAt?: Date;
  accountId?: string;
  accountName?: string;
  metadata?: Record<string, any>;
}

export interface PlatformAdapter {
  readonly platform: PlatformType;
  isConfigured(): boolean;
  getMissingConfig?(): string[];
  publish(
    account: PlatformAccount,
    params: PublishParams,
  ): Promise<PublishResult>;
  getPostStatus(
    account: PlatformAccount,
    platformPostId: string,
  ): Promise<PublishResult>;
  fetchAnalytics(
    account: PlatformAccount,
    platformPostId: string,
  ): Promise<PlatformMetrics>;
  getAuthUrl?(redirectUri: string, state?: string): OAuthAuthUrlResult;
  handleCallback?(code: string, redirectUri: string): Promise<OAuthTokenResult>;
  refreshAuthToken?(account: PlatformAccount): Promise<OAuthTokenResult>;
}

import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { PlatformAccount } from '@prisma/client';
import axios from 'axios';
import {
  PlatformAdapter,
  PlatformType,
  PublishParams,
  PublishResult,
  PlatformMetrics,
  OAuthAuthUrlResult,
  OAuthTokenResult,
} from './platform-adapter.interface';
import { EncryptionService } from '../encryption.service';

@Injectable()
export class TikTokAdapter implements PlatformAdapter {
  readonly platform: PlatformType = 'TIKTOK';
  private readonly logger = new Logger(TikTokAdapter.name);

  constructor(
    private readonly configService: ConfigService,
    private readonly encryptionService: EncryptionService,
  ) {}

  getMissingConfig(): string[] {
    const missing: string[] = [];
    const clientKey = (
      this.configService.get<string>('TIKTOK_CLIENT_KEY') ||
      this.configService.get<string>('TIKTOK_CLIENT_ID') ||
      ''
    ).trim();
    const clientSecret = (
      this.configService.get<string>('TIKTOK_CLIENT_SECRET') || ''
    ).trim();

    if (!clientKey) missing.push('TIKTOK_CLIENT_KEY');
    if (!clientSecret) missing.push('TIKTOK_CLIENT_SECRET');

    return missing;
  }

  isConfigured(): boolean {
    return this.getMissingConfig().length === 0;
  }

  getAuthUrl(redirectUri: string, state = 'tiktok_auth'): OAuthAuthUrlResult {
    const missing = this.getMissingConfig();
    const clientKey = (
      this.configService.get<string>('TIKTOK_CLIENT_KEY') ||
      this.configService.get<string>('TIKTOK_CLIENT_ID') ||
      ''
    ).trim();

    this.logger.log(
      `[TikTok OAuth] Configuration check - clientKey: ${
        clientKey ? `configured (length ${clientKey.length})` : 'missing'
      }, clientSecret: ${
        missing.includes('TIKTOK_CLIENT_SECRET') ? 'missing' : 'configured'
      }, redirectUri: ${redirectUri}`,
    );

    if (missing.length > 0) {
      throw new Error(
        `TikTok integration is not configured. Missing configuration: ${missing.join(', ')}`,
      );
    }

    const scope = 'user.info.basic,video.upload,video.publish';
    const url = `https://www.tiktok.com/v2/auth/authorize/?client_key=${encodeURIComponent(clientKey)}&response_type=code&scope=${encodeURIComponent(scope)}&redirect_uri=${encodeURIComponent(redirectUri)}&state=${encodeURIComponent(state)}`;
    return { url, state };
  }

  async handleCallback(
    code: string,
    redirectUri: string,
  ): Promise<OAuthTokenResult> {
    const missing = this.getMissingConfig();
    if (missing.length > 0) {
      throw new Error(
        `TikTok integration is not configured. Missing configuration: ${missing.join(', ')}`,
      );
    }

    const clientKey = (
      this.configService.get<string>('TIKTOK_CLIENT_KEY') ||
      this.configService.get<string>('TIKTOK_CLIENT_ID') ||
      ''
    ).trim();
    const clientSecret = (
      this.configService.get<string>('TIKTOK_CLIENT_SECRET') || ''
    ).trim();

    this.logger.log(
      `[TikTok OAuth] Exchanging authorization code with TikTok token API (redirectUri: ${redirectUri})`,
    );

    try {
      const response = await axios.post(
        'https://open.tiktokapis.com/v2/oauth/token/',
        new URLSearchParams({
          client_key: clientKey,
          client_secret: clientSecret,
          code,
          grant_type: 'authorization_code',
          redirect_uri: redirectUri,
        }).toString(),
        {
          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        },
      );

      const data = response.data;
      if (data.error && data.error.code !== 'ok' && data.error.code !== 0) {
        this.logger.error(
          `[TikTok OAuth] Token exchange error response: ${JSON.stringify(data.error)}`,
        );
        throw new Error(
          `TikTok token exchange failed: ${data.error.message || JSON.stringify(data.error)}`,
        );
      }

      const accessToken = data.access_token || data.data?.access_token;
      const refreshToken = data.refresh_token || data.data?.refresh_token;
      const expiresIn = data.expires_in || data.data?.expires_in || 86400;
      const openId = data.open_id || data.data?.open_id;

      if (!accessToken) {
        throw new Error(
          'TikTok token exchange did not return an access token.',
        );
      }

      if (!openId) {
        throw new Error(
          'TikTok token exchange did not return a valid open_id user identifier.',
        );
      }

      this.logger.log(
        `[TikTok OAuth] Token exchange succeeded for openId ending with ...${openId.slice(-6)}`,
      );

      let accountName = `TikTok User (${openId.slice(-6)})`;
      try {
        const userInfoRes = await axios.get(
          'https://open.tiktokapis.com/v2/user/info/?fields=open_id,display_name,avatar_url',
          {
            headers: { Authorization: `Bearer ${accessToken}` },
          },
        );
        const userInfo = userInfoRes.data?.data?.user;
        if (userInfo?.display_name) {
          accountName = userInfo.display_name;
        }
      } catch (userErr: any) {
        this.logger.debug(
          `[TikTok OAuth] Could not fetch user profile details: ${userErr.message}`,
        );
      }

      return {
        accessToken,
        refreshToken,
        expiresAt: new Date(Date.now() + expiresIn * 1000),
        accountId: openId,
        accountName,
      };
    } catch (err: any) {
      if (axios.isAxiosError(err) && err.response?.data) {
        const apiErr = err.response.data.error || err.response.data;
        this.logger.error(
          `[TikTok OAuth] API error: ${JSON.stringify(apiErr)}`,
        );
        throw new Error(
          `TikTok token exchange failed: ${apiErr.message || JSON.stringify(apiErr)}`,
        );
      }
      throw err;
    }
  }

  async refreshAuthToken(account: PlatformAccount): Promise<OAuthTokenResult> {
    const decryptedRefreshToken = this.encryptionService.decrypt(
      account.refreshToken,
    );
    const missing = this.getMissingConfig();

    if (!decryptedRefreshToken || missing.length > 0) {
      throw new Error(
        `Cannot refresh TikTok token: missing refresh token or config (${missing.join(', ')})`,
      );
    }

    const clientKey = (
      this.configService.get<string>('TIKTOK_CLIENT_KEY') ||
      this.configService.get<string>('TIKTOK_CLIENT_ID') ||
      ''
    ).trim();
    const clientSecret = (
      this.configService.get<string>('TIKTOK_CLIENT_SECRET') || ''
    ).trim();

    try {
      const response = await axios.post(
        'https://open.tiktokapis.com/v2/oauth/token/',
        new URLSearchParams({
          client_key: clientKey,
          client_secret: clientSecret,
          refresh_token: decryptedRefreshToken,
          grant_type: 'refresh_token',
        }).toString(),
        {
          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        },
      );

      const data = response.data;
      if (data.error && data.error.code !== 'ok' && data.error.code !== 0) {
        throw new Error(
          `TikTok refresh error: ${data.error.message || JSON.stringify(data.error)}`,
        );
      }

      const accessToken = data.access_token || data.data?.access_token;
      const refreshToken =
        data.refresh_token || data.data?.refresh_token || decryptedRefreshToken;
      const expiresIn = data.expires_in || data.data?.expires_in || 86400;

      return {
        accessToken,
        refreshToken,
        expiresAt: new Date(Date.now() + expiresIn * 1000),
        accountId: account.accountId || undefined,
        accountName: account.accountName,
      };
    } catch (error: any) {
      this.logger.error(
        `[TikTok OAuth] Refresh token failed: ${error.message}`,
      );
      throw error;
    }
  }

  async publish(
    account: PlatformAccount,
    params: PublishParams,
  ): Promise<PublishResult> {
    const decryptedToken = this.encryptionService.decrypt(account.accessToken);

    if (!decryptedToken) {
      this.logger.warn(
        `TikTok publishing failed: missing access token for account ${account.id}`,
      );
      return {
        success: false,
        errorCode: 'NOT_CONFIGURED',
        errorMessage:
          'TikTok API requires a valid user access token to publish videos.',
      };
    }

    try {
      // Step 1: Initialize Video Direct Post / Inbox Post on TikTok API v2
      const initUrl = 'https://open.tiktokapis.com/v2/post/publish/video/init/';
      const captionText = [
        params.caption || params.title || '',
        ...(params.hashtags || []).map((h) =>
          h.startsWith('#') ? h : `#${h}`,
        ),
      ]
        .filter(Boolean)
        .join(' ');

      const initPayload = {
        post_info: {
          title: captionText.slice(0, 2200),
          privacy_level:
            params.privacyStatus === 'private'
              ? 'SELF_ONLY'
              : 'PUBLIC_TO_EVERYONE',
          disable_duet: false,
          disable_stitch: false,
          disable_comment: false,
        },
        source_info: {
          source: 'PULL_FROM_URL',
          video_url: params.downloadUrl,
        },
      };

      const initResponse = await axios.post(initUrl, initPayload, {
        headers: {
          Authorization: `Bearer ${decryptedToken}`,
          'Content-Type': 'application/json; charset=UTF-8',
        },
      });

      const responseData = initResponse.data;
      if (
        responseData.error &&
        responseData.error.code !== 'ok' &&
        responseData.error.code !== 0
      ) {
        return {
          success: false,
          errorCode: String(responseData.error.code || 'TIKTOK_API_ERROR'),
          errorMessage:
            responseData.error.message ||
            'Failed to initialize TikTok video post.',
          rawResponse: responseData,
        };
      }

      const publishId = responseData.data?.publish_id;
      return {
        success: true,
        platformPostId: publishId,
        platformUrl: publishId
          ? `https://www.tiktok.com/@${account.accountName}/video/${publishId}`
          : undefined,
        publishedAt: new Date(),
        rawResponse: responseData,
      };
    } catch (error: any) {
      this.logger.error(
        `TikTok publish request failed: ${error.message}`,
        error.stack,
      );
      return {
        success: false,
        errorCode: error.response?.data?.error?.code || 'NETWORK_ERROR',
        errorMessage:
          error.response?.data?.error?.message ||
          error.message ||
          'Error executing TikTok API request.',
        rawResponse: error.response?.data,
      };
    }
  }

  async getPostStatus(
    account: PlatformAccount,
    platformPostId: string,
  ): Promise<PublishResult> {
    const decryptedToken = this.encryptionService.decrypt(account.accessToken);
    if (!decryptedToken) {
      return {
        success: false,
        errorCode: 'NOT_CONFIGURED',
        errorMessage: 'Missing access token.',
      };
    }

    try {
      const response = await axios.post(
        'https://open.tiktokapis.com/v2/post/publish/status/fetch/',
        { publish_id: platformPostId },
        {
          headers: {
            Authorization: `Bearer ${decryptedToken}`,
            'Content-Type': 'application/json',
          },
        },
      );

      const status = response.data?.data?.status;
      const isPublished = status === 'SUCCESS' || status === 'PUBLISHED';
      return {
        success: isPublished,
        platformPostId,
        errorMessage: isPublished ? undefined : `TikTok post status: ${status}`,
        rawResponse: response.data,
      };
    } catch (error: any) {
      return {
        success: false,
        errorCode: 'STATUS_CHECK_FAILED',
        errorMessage: error.message,
      };
    }
  }

  async fetchAnalytics(
    account: PlatformAccount,
    platformPostId: string,
  ): Promise<PlatformMetrics> {
    const decryptedToken = this.encryptionService.decrypt(account.accessToken);
    if (!decryptedToken) {
      return {
        views: 0,
        likes: 0,
        comments: 0,
        shares: 0,
        saves: 0,
        clicks: 0,
      };
    }

    try {
      const response = await axios.post(
        'https://open.tiktokapis.com/v2/video/query/',
        {
          filters: { video_ids: [platformPostId] },
          fields: [
            'id',
            'title',
            'like_count',
            'comment_count',
            'share_count',
            'view_count',
          ],
        },
        {
          headers: {
            Authorization: `Bearer ${decryptedToken}`,
            'Content-Type': 'application/json',
          },
        },
      );

      const videoData = response.data?.data?.videos?.[0] || {};
      const views = Number(videoData.view_count || 0);
      const likes = Number(videoData.like_count || 0);
      const comments = Number(videoData.comment_count || 0);
      const shares = Number(videoData.share_count || 0);
      const engagementRate =
        views > 0 ? (likes + comments + shares) / views : 0;

      return {
        views,
        likes,
        comments,
        shares,
        saves: 0,
        clicks: 0,
        engagementRate,
        rawMetadata: response.data,
      };
    } catch (error) {
      this.logger.warn(
        `Failed to fetch TikTok analytics for post ${platformPostId}: ${(error as Error).message}`,
      );
      return {
        views: 0,
        likes: 0,
        comments: 0,
        shares: 0,
        saves: 0,
        clicks: 0,
      };
    }
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { PlatformAccount } from '@prisma/client';
import axios from 'axios';
import {
  PlatformAdapter,
  PlatformType,
  PublishParams,
  PublishResult,
  PlatformMetrics,
  OAuthAuthUrlResult,
  OAuthTokenResult,
} from './platform-adapter.interface';
import { EncryptionService } from '../encryption.service';

@Injectable()
export class YouTubeAdapter implements PlatformAdapter {
  readonly platform: PlatformType = 'YOUTUBE';
  private readonly logger = new Logger(YouTubeAdapter.name);

  constructor(
    private readonly configService: ConfigService,
    private readonly encryptionService: EncryptionService,
  ) {}

  isConfigured(): boolean {
    const clientId = this.configService.get<string>('YOUTUBE_CLIENT_ID');
    const clientSecret = this.configService.get<string>(
      'YOUTUBE_CLIENT_SECRET',
    );
    return Boolean(clientId && clientSecret);
  }

  getAuthUrl(redirectUri: string, state = 'youtube_auth'): OAuthAuthUrlResult {
    const clientId = this.configService.get<string>('YOUTUBE_CLIENT_ID') || '';
    const scope =
      'https://www.googleapis.com/auth/youtube.upload https://www.googleapis.com/auth/youtube.readonly';
    const url = `https://accounts.google.com/o/oauth2/v2/auth?client_id=${encodeURIComponent(clientId)}&response_type=code&scope=${encodeURIComponent(scope)}&redirect_uri=${encodeURIComponent(redirectUri)}&access_type=offline&prompt=consent&state=${encodeURIComponent(state)}`;
    return { url, state };
  }

  async handleCallback(
    code: string,
    redirectUri: string,
  ): Promise<OAuthTokenResult> {
    const clientId = this.configService.get<string>('YOUTUBE_CLIENT_ID') || '';
    const clientSecret =
      this.configService.get<string>('YOUTUBE_CLIENT_SECRET') || '';

    if (!clientId || !clientSecret) {
      throw new Error('YouTube client ID or secret is not configured.');
    }

    const response = await axios.post(
      'https://oauth2.googleapis.com/token',
      new URLSearchParams({
        code,
        client_id: clientId,
        client_secret: clientSecret,
        redirect_uri: redirectUri,
        grant_type: 'authorization_code',
      }).toString(),
      {
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      },
    );

    const data = response.data;
    const accessToken = data.access_token;
    const refreshToken = data.refresh_token;
    const expiresIn = data.expires_in || 3600;

    // Retrieve channel info
    let accountId = 'youtube_channel';
    let accountName = 'YouTube Channel';

    try {
      const channelRes = await axios.get(
        'https://www.googleapis.com/youtube/v3/channels?part=snippet&mine=true',
        {
          headers: { Authorization: `Bearer ${accessToken}` },
        },
      );
      const channelItem = channelRes.data?.items?.[0];
      if (channelItem) {
        accountId = channelItem.id;
        accountName = channelItem.snippet?.title || accountName;
      }
    } catch {
      // Fallback
    }

    return {
      accessToken,
      refreshToken,
      expiresAt: new Date(Date.now() + expiresIn * 1000),
      accountId,
      accountName,
    };
  }

  async refreshAuthToken(account: PlatformAccount): Promise<OAuthTokenResult> {
    const decryptedRefreshToken = this.encryptionService.decrypt(
      account.refreshToken,
    );
    const clientId = this.configService.get<string>('YOUTUBE_CLIENT_ID') || '';
    const clientSecret =
      this.configService.get<string>('YOUTUBE_CLIENT_SECRET') || '';

    if (!decryptedRefreshToken || !clientId || !clientSecret) {
      throw new Error(
        'Cannot refresh token: missing refresh token or client credentials.',
      );
    }

    const response = await axios.post(
      'https://oauth2.googleapis.com/token',
      new URLSearchParams({
        client_id: clientId,
        client_secret: clientSecret,
        refresh_token: decryptedRefreshToken,
        grant_type: 'refresh_token',
      }).toString(),
      {
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      },
    );

    const data = response.data;
    return {
      accessToken: data.access_token,
      refreshToken: data.refresh_token || decryptedRefreshToken,
      expiresAt: new Date(Date.now() + (data.expires_in || 3600) * 1000),
      accountId: account.accountId || undefined,
      accountName: account.accountName,
    };
  }

  async publish(
    account: PlatformAccount,
    params: PublishParams,
  ): Promise<PublishResult> {
    const decryptedToken = this.encryptionService.decrypt(account.accessToken);

    if (!decryptedToken) {
      this.logger.warn(
        `YouTube Shorts publishing failed: missing token for account ${account.id}`,
      );
      return {
        success: false,
        errorCode: 'NOT_CONFIGURED',
        errorMessage:
          'YouTube Shorts API requires a valid user token to publish videos.',
      };
    }

    try {
      const title = (params.title || 'Affiliate Short Video').slice(0, 100);
      const description = [
        params.description || params.caption || '',
        '#Shorts',
        ...(params.hashtags || []).map((h) =>
          h.startsWith('#') ? h : `#${h}`,
        ),
      ]
        .filter(Boolean)
        .join(' ')
        .slice(0, 5000);

      const snippet = {
        title,
        description,
        tags: [...(params.tags || []), 'Shorts'],
        categoryId: '22', // People & Blogs / General
      };

      const status = {
        privacyStatus: params.privacyStatus || 'public',
        selfDeclaredMadeForKids: false,
      };

      // YouTube API Upload (Metadata + Init upload session)
      const initResponse = await axios.post(
        'https://www.googleapis.com/upload/youtube/v3/videos?uploadType=resumable&part=snippet,status',
        { snippet, status },
        {
          headers: {
            Authorization: `Bearer ${decryptedToken}`,
            'Content-Type': 'application/json; charset=UTF-8',
            'X-Upload-Content-Type': params.mimeType || 'video/mp4',
          },
        },
      );

      const uploadUrl = initResponse.headers['location'];
      if (!uploadUrl && !initResponse.data?.id) {
        return {
          success: false,
          errorCode: 'UPLOAD_SESSION_FAILED',
          errorMessage: 'YouTube API did not return an upload session URL.',
          rawResponse: initResponse.data,
        };
      }

      // If uploadUrl returned, stream buffer/file bytes
      let finalVideoId = initResponse.data?.id;
      let bufferToUpload = params.videoBuffer;

      if (uploadUrl && !bufferToUpload && params.downloadUrl) {
        try {
          const downloadRes = await axios.get(params.downloadUrl, {
            responseType: 'arraybuffer',
          });
          bufferToUpload = Buffer.from(downloadRes.data);
        } catch (downloadErr: any) {
          this.logger.error(
            `Failed to download video bytes from downloadUrl: ${downloadErr.message || downloadErr}`,
          );
        }
      }

      if (uploadUrl && bufferToUpload) {
        const uploadRes = await axios.put(uploadUrl, bufferToUpload, {
          headers: {
            'Content-Type': params.mimeType || 'video/mp4',
            'Content-Length': bufferToUpload.length,
          },
        });
        finalVideoId = uploadRes.data?.id || finalVideoId;
      }

      if (!finalVideoId) {
        return {
          success: false,
          errorCode: 'YOUTUBE_UPLOAD_FAILED',
          errorMessage: 'YouTube video upload did not yield a valid video ID.',
        };
      }

      return {
        success: true,
        platformPostId: finalVideoId,
        platformUrl: `https://www.youtube.com/shorts/${finalVideoId}`,
        publishedAt: new Date(),
        rawResponse: initResponse.data,
      };
    } catch (error: any) {
      this.logger.error(
        `YouTube Shorts upload failed: ${error.message}`,
        error.stack,
      );
      const is401 =
        error.response?.status === 401 ||
        error.response?.data?.error?.code === 401;
      return {
        success: false,
        errorCode: is401
          ? '401'
          : error.response?.data?.error?.code || 'YOUTUBE_API_ERROR',
        errorMessage: is401
          ? 'Phiên đăng nhập YouTube đã hết hạn (Google OAuth 401). Vui lòng nhấn nút "Sign in YouTube Account" ở trên để kết nối lại tài khoản.'
          : error.response?.data?.error?.message ||
            error.message ||
            'Failed to publish video to YouTube Shorts.',
        rawResponse: error.response?.data,
      };
    }
  }

  async getPostStatus(
    account: PlatformAccount,
    platformPostId: string,
  ): Promise<PublishResult> {
    const decryptedToken = this.encryptionService.decrypt(account.accessToken);
    if (!decryptedToken) {
      return {
        success: false,
        errorCode: 'NOT_CONFIGURED',
        errorMessage: 'Missing access token.',
      };
    }

    try {
      const response = await axios.get(
        `https://www.googleapis.com/youtube/v3/videos?part=status,uploadStatus&id=${platformPostId}`,
        {
          headers: { Authorization: `Bearer ${decryptedToken}` },
        },
      );

      const item = response.data?.items?.[0];
      if (!item) {
        return {
          success: false,
          errorCode: 'POST_NOT_FOUND',
          errorMessage: 'YouTube video not found.',
        };
      }

      const status = item.status?.uploadStatus || 'processed';
      return {
        success: status === 'processed' || status === 'uploaded',
        platformPostId,
        platformUrl: `https://www.youtube.com/shorts/${platformPostId}`,
        rawResponse: response.data,
      };
    } catch (error: any) {
      return {
        success: false,
        errorCode: 'STATUS_CHECK_FAILED',
        errorMessage: error.message,
      };
    }
  }

  async fetchAnalytics(
    account: PlatformAccount,
    platformPostId: string,
  ): Promise<PlatformMetrics> {
    const decryptedToken = this.encryptionService.decrypt(account.accessToken);
    if (!decryptedToken) {
      return {
        views: 0,
        likes: 0,
        comments: 0,
        shares: 0,
        saves: 0,
        clicks: 0,
      };
    }

    try {
      const response = await axios.get(
        `https://www.googleapis.com/youtube/v3/videos?part=statistics&id=${platformPostId}`,
        {
          headers: { Authorization: `Bearer ${decryptedToken}` },
        },
      );

      const stats = response.data?.items?.[0]?.statistics || {};
      const views = Number(stats.viewCount || 0);
      const likes = Number(stats.likeCount || 0);
      const comments = Number(stats.commentCount || 0);
      const engagementRate = views > 0 ? (likes + comments) / views : 0;

      return {
        views,
        likes,
        comments,
        shares: 0,
        saves: 0,
        clicks: 0,
        engagementRate,
        rawMetadata: response.data,
      };
    } catch (error) {
      this.logger.warn(
        `Failed to fetch YouTube analytics for post ${platformPostId}: ${(error as Error).message}`,
      );
      return {
        views: 0,
        likes: 0,
        comments: 0,
        shares: 0,
        saves: 0,
        clicks: 0,
      };
    }
  }
}

import { Injectable } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import * as crypto from 'crypto';

@Injectable()
export class EncryptionService {
  private readonly algorithm = 'aes-256-gcm';
  private readonly secretKey: Buffer;

  constructor(private readonly configService: ConfigService) {
    const rawSecret = this.configService.get<string>(
      'TOKEN_ENCRYPTION_SECRET',
      'antigravity-default-secret-key-32-chars-long!',
    );
    // Ensure key length is exactly 32 bytes for aes-256
    this.secretKey = crypto.createHash('sha256').update(rawSecret).digest();
  }

  encrypt(text: string | null | undefined): string | null {
    if (!text) return null;
    try {
      const iv = crypto.randomBytes(12);
      const cipher = crypto.createCipheriv(this.algorithm, this.secretKey, iv);
      let encrypted = cipher.update(text, 'utf8', 'hex');
      encrypted += cipher.final('hex');
      const authTag = cipher.getAuthTag().toString('hex');
      return `${iv.toString('hex')}:${authTag}:${encrypted}`;
    } catch (error) {
      throw new Error(`Encryption failed: ${(error as Error).message}`);
    }
  }

  decrypt(cipherText: string | null | undefined): string | null {
    if (!cipherText) return null;
    try {
      const parts = cipherText.split(':');
      if (parts.length !== 3) {
        // Fallback for unencrypted legacy tokens if any
        return cipherText;
      }
      const [ivHex, authTagHex, encryptedHex] = parts;
      const iv = Buffer.from(ivHex, 'hex');
      const authTag = Buffer.from(authTagHex, 'hex');
      const decipher = crypto.createDecipheriv(
        this.algorithm,
        this.secretKey,
        iv,
      );
      decipher.setAuthTag(authTag);
      let decrypted = decipher.update(encryptedHex, 'hex', 'utf8');
      decrypted += decipher.final('utf8');
      return decrypted;
    } catch (error) {
      // In case decryption fails or token is plain text fallback
      return cipherText;
    }
  }

  sanitizeAccount<
    T extends { accessToken?: string | null; refreshToken?: string | null },
  >(
    account: T,
  ): Omit<T, 'accessToken' | 'refreshToken'> & {
    hasAccessToken: boolean;
    hasRefreshToken: boolean;
  } {
    const { accessToken, refreshToken, ...rest } = account;
    return {
      ...rest,
      hasAccessToken: Boolean(accessToken),
      hasRefreshToken: Boolean(refreshToken),
    };
  }
}

import {
  Controller,
  Get,
  Post,
  Delete,
  Body,
  Param,
  Query,
  HttpCode,
  HttpStatus,
  Res,
} from '@nestjs/common';
import type { Response } from 'express';
import {
  PublishingService,
  CreateAccountDto,
  CreatePublishJobDto,
  CreateBatchPublishJobsDto,
} from './publishing.service';
import { PlatformType } from './adapters/platform-adapter.interface';

@Controller('publishing')
export class PublishingController {
  constructor(private readonly publishingService: PublishingService) {}

  // --- ACCOUNTS ---

  @Get('config-status')
  @Get('accounts/config-status')
  async getConfigStatus() {
    return this.publishingService.getConfigStatus();
  }

  @Get('debug/:platform')
  async getPlatformDebugInfo(@Param('platform') platform: string) {
    const plat = platform.toUpperCase() as PlatformType;
    const adapter = this.publishingService.getAdapter(plat);
    const redirectUri = this.getDefaultRedirect(platform);
    const missingConfig = adapter.getMissingConfig
      ? adapter.getMissingConfig()
      : [];

    let oauthAuthUrl: string | null = null;
    let authUrlError: string | null = null;

    if (adapter.isConfigured() && adapter.getAuthUrl) {
      try {
        const res = adapter.getAuthUrl(redirectUri);
        oauthAuthUrl = res.url;
      } catch (err: any) {
        authUrlError = err.message || 'Error generating auth URL';
      }
    }

    return {
      platform: plat,
      isConfigured: adapter.isConfigured(),
      missingConfig,
      redirectUri,
      oauthAuthUrlGenerated: Boolean(oauthAuthUrl),
      authUrlError,
      environmentCheck: {
        oauthRedirectBaseUrl: process.env.OAUTH_REDIRECT_BASE_URL || null,
        frontendUrl: process.env.FRONTEND_URL || null,
      },
    };
  }

  @Get('accounts')
  async getAccounts() {
    return this.publishingService.getAccounts();
  }

  @Post('accounts')
  async createAccount(@Body() dto: CreateAccountDto) {
    return this.publishingService.createAccount(dto);
  }

  @Delete('accounts/:id')
  async deleteAccount(@Param('id') id: string) {
    return this.publishingService.deleteAccount(id);
  }

  private getDefaultRedirect(platform: string): string {
    const envKey = `${platform.toUpperCase()}_REDIRECT_URI`;
    if (process.env[envKey]) {
      return process.env[envKey];
    }
    const baseUrl =
      process.env.OAUTH_REDIRECT_BASE_URL ||
      process.env.CORS_ORIGIN ||
      'http://localhost:23000';
    return `${baseUrl}/api/publishing/accounts/${platform.toLowerCase()}/callback`;
  }

  @Get('accounts/:platform/connect')
  async getConnectUrl(
    @Param('platform') platform: string,
    @Query('redirectUri') redirectUri: string,
  ) {
    const plat = platform.toUpperCase() as PlatformType;
    const defaultRedirect = this.getDefaultRedirect(platform);
    return this.publishingService.getOAuthUrl(
      plat,
      redirectUri || defaultRedirect,
    );
  }

  @Get('accounts/:platform/callback')
  async handleCallback(
    @Param('platform') platform: string,
    @Query('code') code: string,
    @Query('redirectUri') redirectUri: string,
    @Res() res: Response,
  ) {
    const frontendUrl =
      process.env.FRONTEND_URL ||
      process.env.CORS_ORIGIN ||
      'http://localhost:23000';
    try {
      const plat = platform.toUpperCase() as PlatformType;
      const defaultRedirect = this.getDefaultRedirect(platform);
      const account = await this.publishingService.handleOAuthCallback(
        plat,
        code,
        redirectUri || defaultRedirect,
      );
      return res.redirect(
        `${frontendUrl}/publishing?accountConnected=${account.id}`,
      );
    } catch (err: any) {
      const errorMessage = encodeURIComponent(
        err.message || 'OAuth authorization failed.',
      );
      return res.redirect(`${frontendUrl}/publishing?error=${errorMessage}`);
    }
  }

  // --- PUBLISHING JOBS ---

  @Post('jobs')
  async createJob(@Body() dto: CreatePublishJobDto) {
    return this.publishingService.createJob(dto);
  }

  @Post('jobs/batch')
  async createBatchJobs(@Body() dto: CreateBatchPublishJobsDto) {
    return this.publishingService.createBatchJobs(dto);
  }

  @Get('jobs')
  async listJobs(
    @Query('platform') platform?: string,
    @Query('status') status?: string,
    @Query('videoId') videoId?: string,
  ) {
    return this.publishingService.listJobs({ platform, status, videoId });
  }

  @Get('jobs/:id')
  async getJobById(@Param('id') id: string) {
    return this.publishingService.getJobById(id);
  }

  @Post('jobs/:id/retry')
  @HttpCode(HttpStatus.OK)
  async retryJob(@Param('id') id: string) {
    return this.publishingService.retryJob(id);
  }

  @Post('jobs/:id/cancel')
  @HttpCode(HttpStatus.OK)
  async cancelJob(@Param('id') id: string) {
    return this.publishingService.cancelJob(id);
  }
}

