      (mockFacebookAdapter as any).handleCallback = jest
        .fn()
        .mockResolvedValue({
          accessToken: 'page_token_123',
          accountId: 'real_page_id_999',
          accountName: 'Official Fanpage',
        });
      mockPrismaService.platformAccount.create.mockResolvedValue({
        id: 'acc-fb-1',
        platform: 'FACEBOOK',
        accountName: 'Official Fanpage',
        accountId: 'real_page_id_999',
        status: 'ACTIVE',
      });

      const account = await service.handleOAuthCallback(
        'FACEBOOK',
        'valid_code',
        'http://localhost:23000/callback',
      );
      expect(account.id).toBe('acc-fb-1');
      expect(mockPrismaService.platformAccount.create).toHaveBeenCalledWith(
        expect.objectContaining({
          data: expect.objectContaining({
            platform: 'FACEBOOK',
            accountId: 'real_page_id_999',
          }),
        }),
      );
    });
  });
});

import {
  Injectable,
  Logger,
  NotFoundException,
  BadRequestException,
  ConflictException,
} from '@nestjs/common';
import { InjectQueue } from '@nestjs/bullmq';
import { Queue } from 'bullmq';
import { PrismaService } from '../database/prisma.service';
import { StorageService } from '../storage/storage.service';
import { EncryptionService } from './encryption.service';
import { TikTokAdapter } from './adapters/tiktok.adapter';
import { YouTubeAdapter } from './adapters/youtube.adapter';
import { InstagramAdapter } from './adapters/instagram.adapter';
import { FacebookAdapter } from './adapters/facebook.adapter';
import {
  IsString,
  IsOptional,
  IsBoolean,
  IsArray,
  IsEnum,
} from 'class-validator';
import {
  PlatformAdapter,
  PlatformType,
} from './adapters/platform-adapter.interface';

export class CreateAccountDto {
  @IsString()
  platform!: string;

  @IsString()
  accountName!: string;

  @IsOptional()
  @IsString()
  accountId?: string;

  @IsOptional()
  @IsString()
  accessToken?: string;

  @IsOptional()
  @IsString()
  refreshToken?: string;

  @IsOptional()
  tokenExpiresAt?: Date | string;

  @IsOptional()
  metadata?: Record<string, any>;
}

export class CreatePublishJobDto {
  @IsString()
  videoId!: string;

  @IsString()
  platformAccountId!: string;

  @IsOptional()
  @IsString()
  title?: string;

  @IsOptional()
  @IsString()
  description?: string;

  @IsOptional()
  @IsString()
  caption?: string;

  @IsOptional()
  @IsArray()
  hashtags?: string[];

  @IsOptional()
  @IsArray()
  tags?: string[];

  @IsOptional()
  @IsString()
  privacyStatus?: string;

  @IsOptional()
  platformMetadata?: Record<string, any>;

  @IsOptional()
  scheduledAt?: Date | string;

  @IsOptional()
  @IsBoolean()
  allowDuplicate?: boolean;
}

export class CreateBatchPublishJobsDto {
  @IsString()
  videoId!: string;

  @IsArray()
  platformAccountIds!: string[];

  @IsOptional()
  @IsString()
  title?: string;

  @IsOptional()
  @IsString()
  description?: string;

  @IsOptional()
  @IsString()
  caption?: string;

  @IsOptional()
  @IsArray()
  hashtags?: string[];

  @IsOptional()
  @IsArray()
  tags?: string[];

  @IsOptional()
  @IsString()
  privacyStatus?: string;

  @IsOptional()
  scheduledAt?: Date | string;

  @IsOptional()
  @IsBoolean()
  allowDuplicate?: boolean;
}

@Injectable()
export class PublishingService {
  private readonly logger = new Logger(PublishingService.name);
  private readonly adapters: Map<PlatformType, PlatformAdapter> = new Map();

  constructor(
    private readonly prisma: PrismaService,
    private readonly storageService: StorageService,
    private readonly encryptionService: EncryptionService,
    private readonly tiktokAdapter: TikTokAdapter,
    private readonly youtubeAdapter: YouTubeAdapter,
    private readonly instagramAdapter: InstagramAdapter,
    private readonly facebookAdapter: FacebookAdapter,
    @InjectQueue('publishing-queue') private readonly publishingQueue: Queue,
    @InjectQueue('analytics-queue') private readonly analyticsQueue: Queue,
  ) {
    this.adapters.set('TIKTOK', this.tiktokAdapter);
    this.adapters.set('YOUTUBE', this.youtubeAdapter);
    this.adapters.set('INSTAGRAM', this.instagramAdapter);
    this.adapters.set('FACEBOOK', this.facebookAdapter);
  }

  getAdapter(platform: PlatformType): PlatformAdapter {
    const adapter = this.adapters.get(platform);
    if (!adapter) {
      throw new BadRequestException(`Unsupported platform: ${platform}`);
    }
    return adapter;
  }

  // --- ACCOUNTS MANAGEMENT ---

  async getConfigStatus() {
    const status: Record<string, { isConfigured: boolean; missing: string[] }> =
      {};
    for (const [platform, adapter] of this.adapters.entries()) {
      status[platform] = {
        isConfigured: adapter.isConfigured(),
        missing: adapter.getMissingConfig ? adapter.getMissingConfig() : [],
      };
    }
    return status;
  }

  async createAccount(dto: CreateAccountDto) {
    const encryptedAccess = this.encryptionService.encrypt(dto.accessToken);
    const encryptedRefresh = this.encryptionService.encrypt(dto.refreshToken);

    const isAdapterConfigured = this.getAdapter(
      dto.platform.toUpperCase() as PlatformType,
    ).isConfigured();
    const hasToken = Boolean(dto.accessToken && dto.accessToken.trim());
    const status =
      hasToken || isAdapterConfigured ? 'ACTIVE' : 'NOT_CONFIGURED';

    const account = await this.prisma.platformAccount.create({
      data: {
        platform: dto.platform,
        accountName: dto.accountName,
        accountId: dto.accountId,
        accessToken: encryptedAccess,
        refreshToken: encryptedRefresh,
        tokenExpiresAt: dto.tokenExpiresAt
          ? new Date(dto.tokenExpiresAt)
          : null,
        status,
        metadata: dto.metadata || {},
      },
    });

    return this.encryptionService.sanitizeAccount(account);
  }

  async getAccounts() {
    const accounts = await this.prisma.platformAccount.findMany({
      orderBy: { createdAt: 'desc' },
    });

    return accounts.map((acc) => {
      const adapter = this.adapters.get(acc.platform as PlatformType);
      const isConfigured = adapter ? adapter.isConfigured() : false;
      return {
        ...this.encryptionService.sanitizeAccount(acc),
        isConfigured,
      };
    });
  }

  async getAccountById(id: string) {
    const account = await this.prisma.platformAccount.findUnique({
      where: { id },
    });
    if (!account) {
      throw new NotFoundException(`Platform account with ID ${id} not found.`);
    }
    return this.encryptionService.sanitizeAccount(account);
  }

  async deleteAccount(id: string) {
    await this.getAccountById(id);
    return this.prisma.platformAccount.delete({
      where: { id },
    });
  }

  async getOAuthUrl(platform: PlatformType, redirectUri: string) {
    const adapter = this.getAdapter(platform);
    if (!adapter.isConfigured()) {
      const missingKeys = adapter.getMissingConfig
        ? adapter.getMissingConfig()
        : [];
      if (missingKeys.length > 0) {
        throw new BadRequestException(
          `${platform} integration is not configured. Missing configuration: ${missingKeys.join(', ')}`,
        );
      }
      throw new BadRequestException(
        `API credentials for ${platform} are not configured in backend.`,
      );
    }
    if (!adapter.getAuthUrl) {
      throw new BadRequestException(`OAuth not supported for ${platform}`);
    }
    return adapter.getAuthUrl(redirectUri);
  }

  async handleOAuthCallback(
    platform: PlatformType,
    code: string,
    redirectUri: string,
  ) {
    const adapter = this.getAdapter(platform);
    if (!adapter.handleCallback) {
      throw new BadRequestException(
        `OAuth callback not supported for ${platform}`,
      );
    }

    const tokenResult = await adapter.handleCallback(code, redirectUri);
    const dummyIds = [
      'facebook_page',
      'instagram_account',
      'tiktok_user',
      'youtube_channel',
    ];
    if (!tokenResult.accountId || dummyIds.includes(tokenResult.accountId)) {
      throw new BadRequestException(
        `OAuth callback completed, but could not resolve a valid target ${platform} account identity.`,
      );
    }

    return this.createAccount({
      platform,
      accountName: tokenResult.accountName || `${platform} Account`,
      accountId: tokenResult.accountId,
      accessToken: tokenResult.accessToken,
      refreshToken: tokenResult.refreshToken,
      tokenExpiresAt: tokenResult.expiresAt,
      metadata: tokenResult.metadata,
    });
  }

  // --- PUBLISHING JOBS ---

  async createJob(dto: CreatePublishJobDto) {
    // 1. Verify Video existence
    const video = await this.prisma.video.findUnique({
      where: { id: dto.videoId },
    });
    if (!video) {
      throw new NotFoundException(`Video with ID ${dto.videoId} not found.`);
    }

    // 2. Verify Platform Account existence
    const account = await this.prisma.platformAccount.findUnique({
      where: { id: dto.platformAccountId },
    });
    if (!account) {
      throw new NotFoundException(
        `Platform Account with ID ${dto.platformAccountId} not found.`,
      );
    }

    // 3. Duplicate Protection Check
    if (!dto.allowDuplicate) {
      const activeJob = await this.prisma.publishJob.findFirst({
        where: {
          videoId: dto.videoId,
          platformAccountId: dto.platformAccountId,
          status: { in: ['SCHEDULED', 'QUEUED', 'PUBLISHING', 'PUBLISHED'] },
        },
      });

      if (activeJob) {
        throw new ConflictException(
          `A publish job already exists for video ${dto.videoId} on account ${account.accountName} (Status: ${activeJob.status}). Pass allowDuplicate=true to bypass.`,
        );
      }
    }

    // 4. Determine Status & Schedule Time
    const now = new Date();
    const scheduledDate = dto.scheduledAt ? new Date(dto.scheduledAt) : null;
    const isScheduled = Boolean(scheduledDate && scheduledDate > now);
    const initialStatus = isScheduled ? 'SCHEDULED' : 'QUEUED';

    const job = await this.prisma.publishJob.create({
      data: {
        videoId: dto.videoId,
        platformAccountId: dto.platformAccountId,
        platform: account.platform,
        title: dto.title || video.title,
        description: dto.description || video.script || undefined,
        caption: dto.caption || dto.title || video.title,
        hashtags: dto.hashtags || [],
        tags: dto.tags || [],
        privacyStatus: dto.privacyStatus || 'public',
        platformMetadata: dto.platformMetadata || {},
        scheduledAt: scheduledDate,
        status: initialStatus,
      },
    });

    // 5. Enqueue in BullMQ
    const delayMs =
      isScheduled && scheduledDate ? scheduledDate.getTime() - Date.now() : 0;
    await this.publishingQueue.add(
      'publish-video',
      { jobId: job.id },
      {
        delay: Math.max(0, delayMs),
        jobId: job.id,
      },
    );

    this.logger.log(
      `Created publish job ${job.id} for platform ${account.platform} (Status: ${initialStatus}, Delay: ${delayMs}ms)`,
    );
    return job;
  }

  async createBatchJobs(dto: CreateBatchPublishJobsDto) {
    if (!dto.platformAccountIds || dto.platformAccountIds.length === 0) {
      throw new BadRequestException(
        'Vui lòng chọn ít nhất một tài khoản mạng xã hội để đăng video',
      );
    }

    const createdJobs = [];
    const errors = [];

    for (const accountId of dto.platformAccountIds) {
      try {
        const job = await this.createJob({
          videoId: dto.videoId,
          platformAccountId: accountId,
          title: dto.title,
          description: dto.description,
          caption: dto.caption,
          hashtags: dto.hashtags,
          tags: dto.tags,
          privacyStatus: dto.privacyStatus,
          scheduledAt: dto.scheduledAt,
          allowDuplicate: dto.allowDuplicate,
        });
        createdJobs.push(job);
      } catch (err: any) {
        errors.push({ accountId, message: err.message || String(err) });
      }
    }

    return {
      success: createdJobs.length > 0,
      count: createdJobs.length,
      jobs: createdJobs,
      errors,
    };
  }

  async getJobById(id: string) {
    const job = await this.prisma.publishJob.findUnique({
      where: { id },
      include: {
        video: true,
        platformAccount: true,
        analyticsSnapshots: {
          orderBy: { collectedAt: 'desc' },
          take: 5,
        },
      },
    });

    if (!job) {
      throw new NotFoundException(`PublishJob with ID ${id} not found.`);
    }

    return {
      ...job,
      platformAccount: this.encryptionService.sanitizeAccount(
        job.platformAccount,
      ),
    };
  }

  async listJobs(filters?: {
    platform?: string;
    status?: string;
    videoId?: string;
  }) {
    const where: any = {};
    if (filters?.platform) where.platform = filters.platform;
    if (filters?.status) where.status = filters.status;
    if (filters?.videoId) where.videoId = filters.videoId;

    const jobs = await this.prisma.publishJob.findMany({
      where,
      include: {
        video: { select: { id: true, title: true, videoObjectKey: true } },
        platformAccount: {
          select: { id: true, platform: true, accountName: true, status: true },
        },
      },
      orderBy: { createdAt: 'desc' },
    });

    return jobs;
  }

  async retryJob(id: string) {
    const job = await this.prisma.publishJob.findUnique({
      where: { id },
    });

    if (!job) {
      throw new NotFoundException(`PublishJob with ID ${id} not found.`);
    }

    if (job.status === 'PUBLISHING' || job.status === 'PUBLISHED') {
      throw new BadRequestException(`Cannot retry job in status ${job.status}`);
    }

    const updatedJob = await this.prisma.publishJob.update({
      where: { id },
      data: {
        status: 'QUEUED',
        errorMessage: null,
        errorCode: null,
        retryCount: job.retryCount + 1,
        lastAttemptAt: new Date(),
      },
    });

    await this.publishingQueue.add(
      'publish-video',
      { jobId: updatedJob.id },
      { jobId: `${updatedJob.id}-retry-${updatedJob.retryCount}` },
    );

    return updatedJob;
  }

  async cancelJob(id: string) {
    const job = await this.prisma.publishJob.findUnique({
      where: { id },
    });

    if (!job) {
      throw new NotFoundException(`PublishJob with ID ${id} not found.`);
    }

    if (job.status === 'PUBLISHED') {
      throw new BadRequestException('Cannot cancel an already published job.');
    }

    const updated = await this.prisma.publishJob.update({
      where: { id },
      data: { status: 'CANCELLED' },
    });

    try {
      const bullJob = await this.publishingQueue.getJob(id);
      if (bullJob) {
        await bullJob.remove();
      }
    } catch {
      // Ignore if job missing from BullMQ queue
    }

    return updated;
  }

  private safeString(val: any, fallback = ''): string {
    if (val === null || val === undefined) return fallback;
    if (typeof val === 'string') return val;
    if (typeof val === 'object') {
      try {
        return JSON.stringify(val);
      } catch {
        return String(val);
      }
    }
    return String(val);
  }

  private async ensureFreshToken(
    account: any,
    adapter: PlatformAdapter,
  ): Promise<any> {
    if (!adapter.refreshAuthToken || !account.refreshToken) {
      return account;
    }

    const expiresAtMs = account.tokenExpiresAt
      ? new Date(account.tokenExpiresAt).getTime()
      : 0;
    const isExpiredOrExpiringSoon =
      !expiresAtMs || expiresAtMs - Date.now() < 5 * 60 * 1000;

    if (!isExpiredOrExpiringSoon) {
      return account;
    }

    try {
      this.logger.log(
        `Refreshing access token for ${account.platform} account "${account.accountName}" (${account.id})...`,
      );
      const refreshed = await adapter.refreshAuthToken(account);
      const encryptedAccess = this.encryptionService.encrypt(
        refreshed.accessToken,
      );
      const encryptedRefresh = refreshed.refreshToken
        ? this.encryptionService.encrypt(refreshed.refreshToken)
        : account.refreshToken;

      const updatedAccount = await this.prisma.platformAccount.update({
        where: { id: account.id },
        data: {
          accessToken: encryptedAccess,
          refreshToken: encryptedRefresh,
          tokenExpiresAt: refreshed.expiresAt,
          status: 'ACTIVE',
        },
      });

      this.logger.log(
        `Successfully refreshed access token for ${account.platform} account "${account.accountName}".`,
      );
      return updatedAccount;
    } catch (err: any) {
      this.logger.error(
        `Failed to auto-refresh token for account ${account.id}: ${err.message || err}`,
      );
      return account;
    }
  }

  // --- JOB EXECUTION WORKER STEP ---

  async executePublishJob(jobId: string): Promise<void> {
    const job = await this.prisma.publishJob.findUnique({
      where: { id: jobId },
      include: { video: true, platformAccount: true },
    });

    if (!job) {
      this.logger.error(`Cannot execute job ${jobId}: Job not found.`);
      return;
    }

    if (job.status === 'CANCELLED' || job.status === 'PUBLISHED') {
      this.logger.warn(
        `Skipping execution for job ${jobId} with status ${job.status}`,
      );
      return;
    }

    // Update status to PUBLISHING
    await this.prisma.publishJob.update({
      where: { id: jobId },
      data: {
        status: 'PUBLISHING',
        lastAttemptAt: new Date(),
      },
    });

    try {
      const adapter = this.getAdapter(job.platform as PlatformType);

      // Auto-refresh access token if expired or expiring soon
      let activeAccount = await this.ensureFreshToken(
        job.platformAccount,
        adapter,
      );

      // Get download URL / stream from MinIO / StorageService
      const downloadUrl = await this.storageService.getDownloadUrl(
        job.video.videoObjectKey,
        86400,
      );

      let videoBuffer: Buffer | undefined;
      try {
        const streamResult = await this.storageService.getFileStream(
          job.video.videoObjectKey,
        );
        const chunks: Uint8Array[] = [];
        for await (const chunk of streamResult.stream) {
          chunks.push(chunk);
        }
        videoBuffer = Buffer.concat(chunks);
      } catch (err: any) {
        this.logger.warn(
          `Could not load video buffer directly from MinIO: ${err.message || err}`,
        );
      }

      const publishParams = {
        jobId: job.id,
        videoId: job.videoId,
        title: job.title || job.video.title,
        description: job.description || undefined,
        caption: job.caption || undefined,
        hashtags: job.hashtags,
        tags: job.tags,
        privacyStatus: job.privacyStatus || 'public',
        platformMetadata: (job.platformMetadata as Record<string, any>) || {},
        downloadUrl,
        videoBuffer,
      };

      let publishResult = await adapter.publish(activeAccount, publishParams);

      // If failed with 401 Auth error, force a refresh once and retry publish
      const isAuthError =
        !publishResult.success &&
        (String(publishResult.errorCode) === '401' ||
          String(publishResult.errorCode) === 'UNAUTHORIZED' ||
          String(publishResult.errorMessage).includes(
            'invalid authentication credentials',
          ));

      if (
        isAuthError &&
        adapter.refreshAuthToken &&
        activeAccount.refreshToken
      ) {
        this.logger.warn(
          `Job ${jobId} failed with auth error 401. Attempting forced token refresh and retry...`,
        );
        try {
          const refreshed = await adapter.refreshAuthToken(activeAccount);
          const encryptedAccess = this.encryptionService.encrypt(
            refreshed.accessToken,
          );
          const encryptedRefresh = refreshed.refreshToken
            ? this.encryptionService.encrypt(refreshed.refreshToken)
            : activeAccount.refreshToken;

          activeAccount = await this.prisma.platformAccount.update({
            where: { id: activeAccount.id },
            data: {
              accessToken: encryptedAccess,
              refreshToken: encryptedRefresh,
              tokenExpiresAt: refreshed.expiresAt,
              status: 'ACTIVE',
            },
          });
          publishResult = await adapter.publish(activeAccount, publishParams);
        } catch (refreshErr: any) {
          this.logger.error(
            `Forced token refresh failed: ${refreshErr.message || refreshErr}`,
          );
        }
      }

      if (publishResult.success) {
        await this.prisma.publishJob.update({
          where: { id: jobId },
          data: {
            status: 'PUBLISHED',
            publishedAt: publishResult.publishedAt || new Date(),
            platformPostId: this.safeString(publishResult.platformPostId),
            platformUrl: this.safeString(publishResult.platformUrl),
            errorMessage: null,
            errorCode: null,
          },
        });

        this.logger.log(
          `Successfully published job ${jobId} to ${job.platform} (PostID: ${publishResult.platformPostId})`,
        );

        // Schedule initial analytics collection snapshot (after 1 hour)
        await this.analyticsQueue.add(
          'collect-analytics',
          { publishJobId: jobId, intervalLabel: '1h' },
          { delay: 3600 * 1000 },
        );
      } else {
        await this.prisma.publishJob.update({
          where: { id: jobId },
          data: {
            status: 'FAILED',
            errorMessage: this.safeString(
              publishResult.errorMessage,
              'Publishing failed without specific error message.',
            ),
            errorCode: this.safeString(
              publishResult.errorCode,
              'UNKNOWN_ERROR',
            ),
          },
        });

        this.logger.error(
          `Publish job ${jobId} failed: ${publishResult.errorMessage} (Code: ${publishResult.errorCode})`,
        );
      }
    } catch (error: any) {
      const errorMsg = this.safeString(
        error?.message || error,
        'Internal error during job execution.',
      );
      const errorCode = this.safeString(
        error?.code || error?.errorCode,
        'INTERNAL_JOB_ERROR',
      );

      this.logger.error(
        `Execution crash on publish job ${jobId}: ${errorMsg}`,
        error?.stack,
      );

      try {
        await this.prisma.publishJob.update({
          where: { id: jobId },
          data: {
            status: 'FAILED',
            errorMessage: errorMsg,
            errorCode: errorCode,
          },
        });
      } catch (updateErr: any) {
        this.logger.error(
          `Failed to record job ${jobId} failure state: ${updateErr?.message || updateErr}`,
        );
      }
    }
  }
}

import { Injectable, OnModuleInit, Logger } from '@nestjs/common';
import { Queue } from 'bullmq';
import { InjectQueue } from '@nestjs/bullmq';
import { cancelledJobs, killActiveProcess } from './video.processor';

export type VideoJobConfig = {
  voice_name?: string;
  aspect_ratio?: string;
  video_source?: string;
  video_concat_mode?: string;
  bgm_type?: string;
  bgm_file?: string;
  bgm_volume?: number;
  subtitle_enabled?: boolean;
  subtitle_position?: string;
  font_name?: string;
  font_size?: number;
  stroke_color?: string;
  stroke_width?: number;
  productId?: string;
};

export type VideoJobPayload = {
  jobId: string;
  ideaId: string;
  subject: string;
  script?: string;
  language: string;
  config: VideoJobConfig;
  productId?: string;
};

@Injectable()
export class QueueService implements OnModuleInit {
  private readonly logger = new Logger(QueueService.name);

  constructor(
    @InjectQueue('video-generation')
    private videoQueue: Queue<VideoJobPayload>,
  ) {}

  async onModuleInit() {
    await this.cleanStuckActiveJobs();
  }

  async cleanStuckActiveJobs() {
    try {
      const activeJobs = await this.videoQueue.getActive();
      for (const job of activeJobs) {
        this.logger.warn(`Cleaning up stuck active job in BullMQ: ${job.id}`);
        try {
          await job.moveToFailed(
            new Error('Stuck active job cleaned on module init'),
            '0',
            true,
          );
        } catch {
          await job.remove();
        }
      }
    } catch (err: unknown) {
      this.logger.error(`Failed to clean stuck active jobs: ${err}`);
    }
  }

  async addVideoJob(
    jobId: string,
    ideaId: string,
    subject: string,
    script: string | undefined,
    language: string,
    config: VideoJobConfig,
  ) {
    return this.videoQueue.add(
      'generate-video',
      {
        jobId,
        ideaId,
        subject,
        script,
        language,
        config,
      },
      {
        jobId,
        attempts: 1,
        removeOnComplete: true,
        removeOnFail: false,
      },
    );
  }

  async getJobStatus(jobId: string) {
    const job = await this.videoQueue.getJob(jobId);
    if (!job) return null;
    return await job.getState();
  }

  async cancelJob(jobId: string) {
    cancelledJobs.add(jobId);
    killActiveProcess(jobId);

    try {
      const job = await this.videoQueue.getJob(jobId);
      if (job) {
        const state = await job.getState();
        if (state === 'active') {
          try {
            await job.moveToFailed(
              new Error('Job was cancelled by user'),
              '0',
              true,
            );
          } catch {
            await job.discard();
          }
        } else {
          await job.remove();
        }
        return true;
      }
    } catch {
      // Ignore if BullMQ state mutation fails
    }
    return false;
  }
}

import { Processor, WorkerHost } from '@nestjs/bullmq';
import { Job } from 'bullmq';
import { PrismaService } from '../database/prisma.service';
import { StorageService } from '../storage/storage.service';
import type { Buffer } from 'node:buffer';
import { spawn, type ChildProcessWithoutNullStreams } from 'child_process';
import * as path from 'path';
import * as fs from 'fs';
import { Logger } from '@nestjs/common';
import ffmpeg from 'fluent-ffmpeg';
import { type VideoJobPayload } from './queue.service';
import { SettingsService } from '../settings/settings.service';

export const cancelledJobs = new Set<string>();
export const activeProcesses = new Map<
  string,
  ChildProcessWithoutNullStreams
>();

export function killActiveProcess(jobId: string) {
  const proc = activeProcesses.get(jobId);
  if (proc) {
    if (proc.pid) {
      try {
        process.kill(-proc.pid, 'SIGKILL');
      } catch {
        try {
          proc.kill('SIGKILL');
        } catch {
          // ignore
        }
      }
    } else {
      try {
        proc.kill('SIGKILL');
      } catch {
        // ignore
      }
    }
    activeProcesses.delete(jobId);
  }
  try {
    const { execSync } = require('child_process');
    execSync(`pkill -9 -f "task-id ${jobId}"`, { stdio: 'ignore' });
  } catch {
    // ignore
  }
}

type ScriptFile = {
  script?: string;
};

type JobProgressUpdate = {
  progress: number;
  status?: string;
};

function getErrorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

@Processor('video-generation', { concurrency: 1 })
export class VideoProcessor extends WorkerHost {
  private readonly logger = new Logger(VideoProcessor.name);

  constructor(
    private prisma: PrismaService,
    private storage: StorageService,
    private settingsService: SettingsService,
  ) {
    super();
  }

  async process(job: Job<VideoJobPayload, unknown, string>): Promise<unknown> {
    const { jobId, ideaId, subject, script, language, config } = job.data;
    this.logger.log(`Processing video generation job: ${jobId}`);

    // Check if job was cancelled before starting
    const currentJob = await this.prisma.generationJob.findUnique({
      where: { id: jobId },
      select: { status: true },
    });
    if (
      cancelledJobs.has(jobId) ||
      currentJob?.status === 'cancelled' ||
      currentJob?.status === 'failed'
    ) {
      cancelledJobs.delete(jobId);
      throw new Error('Job was cancelled before processing started');
    }

    // Update job status to running in DB
    await this.prisma.generationJob.update({
      where: { id: jobId },
      data: {
        status: 'running',
        startedAt: new Date(),
        progress: 5,
      },
    });

    const projectRoot = path.resolve(__dirname, '..', '..', '..', '..');
    const engineDir = path.join(projectRoot, 'engine');
    const taskStorageDir = path.join(engineDir, 'storage', 'tasks', jobId);

    // Fetch product if associated with job or idea
    const targetProductId =
      config.productId ||
      (
        await this.prisma.generationJob.findUnique({
          where: { id: jobId },
          select: { productId: true, idea: { select: { productId: true } } },
        })
      )?.productId ||
      (
        await this.prisma.generationJob.findUnique({
          where: { id: jobId },
          select: { idea: { select: { productId: true } } },
        })
      )?.idea?.productId;

    let productDataJson: string | null = null;
    if (targetProductId) {
      const product = await this.prisma.product.findUnique({
        where: { id: targetProductId },
      });
      if (product) {
        productDataJson = JSON.stringify({
          id: product.id,
          name: product.name,
          description: product.description || '',
          price: product.price || '',
          currency: product.currency || 'VND',
          affiliateUrl: product.affiliateUrl || '',
          features: product.features || [],
          benefits: product.benefits || [],
          targetAudience: product.targetAudience || '',
          images: product.images || [],
          videos: product.videos || [],
        });
      }
    }

    // Build args
    const args = [
      'engine/cli.py',
      '--video-subject',
      subject,
      '--task-id',
      jobId,
    ];

    if (productDataJson) {
      args.push('--product-data', productDataJson);
    }
    if (script) {
      args.push('--video-script', script);
    }
    if (language) {
      args.push('--video-language', language);
    }
    const settings: Record<string, any> =
      await this.settingsService.getSettings();
    const effectiveVoiceName =
      config.voice_name && config.voice_name.trim()
        ? config.voice_name
        : settings.default_voice || 'vi-VN-HoaiMyNeural';
    args.push('--voice-name', effectiveVoiceName);
    if (config.aspect_ratio) {
      args.push('--video-aspect', config.aspect_ratio);
    }
    if (config.video_source) {
      args.push('--video-source', config.video_source);
    }
    if (config.video_concat_mode) {
      args.push('--video-concat-mode', config.video_concat_mode);
    }
    if (config.bgm_type) {
      args.push('--bgm-type', config.bgm_type);
    }
    if (config.bgm_file) {
      args.push('--bgm-file', config.bgm_file);
    }
    if (config.bgm_volume !== undefined) {
      args.push('--bgm-volume', config.bgm_volume.toString());
    }
    const isSubtitleEnabled =
      config.subtitle_enabled !== undefined
        ? config.subtitle_enabled
        : settings.subtitle_enabled !== undefined
          ? String(settings.subtitle_enabled) === 'true'
          : true;

    if (isSubtitleEnabled) {
      args.push('--subtitle-enabled');
    } else {
      args.push('--no-subtitle-enabled');
    }

    const effectiveFontName =
      config.font_name ||
      settings.subtitle_font_name ||
      'BeVietnamPro-Bold.ttf';
    args.push('--font-name', effectiveFontName);

    if (config.subtitle_position || settings.subtitle_position) {
      args.push(
        '--subtitle-position',
        config.subtitle_position || settings.subtitle_position,
      );
    }
    if (config.font_size) {
      args.push('--font-size', config.font_size.toString());
    }
    if (config.stroke_color) {
      args.push('--stroke-color', config.stroke_color);
    }
    if (config.stroke_width !== undefined) {
      args.push('--stroke-width', config.stroke_width.toString());
    }

    function getPythonRunner(projectRoot: string, cliArgs: string[]) {
      try {
        const { execSync } = require('child_process');
        execSync('uv --version', { stdio: 'ignore' });
        return {
          cmd: 'uv',
          args: ['run', '--project', 'engine', 'python', ...cliArgs],
        };
      } catch {
        const venvPython = path.join(
          projectRoot,
          'engine',
          '.venv',
          'bin',
          'python',
        );
        if (fs.existsSync(venvPython)) {
          return {
            cmd: venvPython,
            args: cliArgs,
          };
        }
        return {
          cmd: 'python3',
          args: cliArgs,
        };
      }
    }

    const runner = getPythonRunner(projectRoot, args);
    this.logger.log(`Executing engine: ${runner.cmd} ${runner.args.join(' ')}`);

    return new Promise((resolve, reject) => {
      let pyProcess: ChildProcessWithoutNullStreams | null = null;
      let logQueue: Promise<void> = Promise.resolve();
      let settled = false;

      const cleanup = () => {
        if (pyProcess && !pyProcess.killed) {
          pyProcess.kill('SIGTERM');
          setTimeout(() => {
            if (pyProcess && !pyProcess.killed) pyProcess.kill('SIGKILL');
          }, 5000);
        }
      };

      const markFailed = async (errMsg: string) => {
        cleanup();
        this.logger.error(`Job ${jobId} failed: ${errMsg}`);
        await this.prisma.generationJob
          .update({
            where: { id: jobId },
            data: {
              status: 'failed',
              errorMessage: errMsg,
              finishedAt: new Date(),
            },
          })
          .catch((err: unknown) =>
            this.logger.error(
              `Failed to mark job as failed: ${getErrorMessage(err)}`,
            ),
          );
      };

      const logAndSave = async (
        dataStr: string,
        stream: 'stdout' | 'stderr',
      ) => {
        const lines = dataStr.split(/\r?\n/).filter((line) => line.trim());
        for (const line of lines) {
          this.logger.debug(`[Engine ${stream}] ${line}`);

          // Check if cancelled
          if (cancelledJobs.has(jobId)) {
            cleanup();
            return;
          }

          // Write log line to DB
          await this.prisma.jobLog
            .create({
              data: {
                jobId,
                level: stream === 'stderr' ? 'warn' : 'info',
                message: line,
              },
            })
            .catch((err) =>
              this.logger.error('Failed to write log to DB:', err),
            );

          // Analyze log to update progress
          let progress = -1;
          let status = '';

          if (line.includes('## generating video script')) {
            status = 'generating_script';
            progress = 10;
          } else if (line.includes('## generating video terms')) {
            status = 'generating_script';
            progress = 20;
          } else if (line.includes('## generating audio')) {
            status = 'generating_voice';
            progress = 35;
          } else if (
            line.includes('## generating subtitle') ||
            line.includes('## correcting subtitle')
          ) {
            status = 'generating_subtitle';
            progress = 50;
          } else if (line.includes('## preprocess local materials')) {
            status = 'fetching_materials';
            progress = 60;
          } else if (line.includes('## downloading videos from')) {
            status = 'fetching_materials';
            progress = 65;
          } else if (
            line.includes('## combining video') ||
            line.includes('concatenating')
          ) {
            status = 'rendering';
            progress = 75;
          } else if (
            line.includes('## generating video') ||
            line.includes('video combining completed')
          ) {
            status = 'rendering';
            progress = 85;
          } else if (
            line.includes('Writing video') ||
            line.includes('MoviePy') ||
            line.includes('video writer') ||
            line.includes('ffmpeg') ||
            line.includes('frame=')
          ) {
            status = 'rendering';
            progress = 92;
          }

          if (progress !== -1) {
            const updateData: JobProgressUpdate = { progress };
            if (status) {
              updateData.status = status;
            }
            await this.prisma.generationJob
              .update({
                where: { id: jobId },
                data: updateData,
              })
              .catch(() => undefined);
          }
        }
      };

      pyProcess = spawn(runner.cmd, runner.args, {
        cwd: projectRoot,
        env: { ...process.env, PYTHONIOENCODING: 'utf-8' },
        detached: true,
      });
      activeProcesses.set(jobId, pyProcess);

      pyProcess.on('close', () => {
        activeProcesses.delete(jobId);
      });

      if (pyProcess.stdout) {
        pyProcess.stdout.on('data', (data: Buffer) => {
          logQueue = logQueue.then(() => logAndSave(data.toString(), 'stdout'));
        });
        pyProcess.stdout.on('error', (err) => {
          this.logger.error(`stdout stream error: ${err.message}`);
        });
      }

      if (pyProcess.stderr) {
        pyProcess.stderr.on('data', (data: Buffer) => {
          logQueue = logQueue.then(() => logAndSave(data.toString(), 'stderr'));
        });
        pyProcess.stderr.on('error', (err) => {
          this.logger.error(`stderr stream error: ${err.message}`);
        });
      }

      pyProcess.on('error', (err) => {
        if (settled) return;
        settled = true;
        this.logger.error(`Failed to spawn process: ${err.message}`);
        void markFailed(`Process spawn failed: ${err.message}`);
        reject(err);
      });

      pyProcess.on('close', (code, signal) => {
        if (settled) return;
        settled = true;
        void (async () => {
          // Wait for all pending log writes
          await logQueue;

          // Check if cancelled during processing
          if (cancelledJobs.has(jobId)) {
            cancelledJobs.delete(jobId);
            reject(new Error('Job was cancelled'));
            return;
          }

          this.logger.log(
            `Engine CLI completed with exit code: ${code}, signal: ${signal}`,
          );

          const finalVideoPath = path.join(taskStorageDir, 'final-1.mp4');
          const videoExists = fs.existsSync(finalVideoPath);

          // Consider CLI execution successful if exit code is 0 OR if the output video was created
          const isSuccess = code === 0 || videoExists;

          if (!isSuccess) {
            const lastErrorLog = await this.prisma.jobLog.findFirst({
              where: {
                jobId,
                level: { in: ['error', 'warn'] },
                NOT: {
                  message: {
                    contains: 'SUCCESS',
                  },
                },
              },
              orderBy: { createdAt: 'desc' },
            });
            const exitDetail =
              code !== null ? `exit code ${code}` : `signal ${signal}`;
            const errMsg = lastErrorLog
              ? `${lastErrorLog.message} (Lỗi CLI: ${exitDetail})`
              : `CLI execution failed with ${exitDetail}`;
            await this.prisma.generationJob.update({
              where: { id: jobId },
              data: {
                status: 'failed',
                errorMessage: errMsg,
                finishedAt: new Date(),
              },
            });
            reject(new Error(errMsg));
            return;
          }

          try {
            // Check if video already exists (idempotency for worker retries)
            const existing = await this.prisma.video.findFirst({
              where: { jobId },
            });
            if (existing) {
              this.logger.log(
                `Video record already exists for job ${jobId}, skipping creation`,
              );
              await this.prisma.generationJob.update({
                where: { id: jobId },
                data: {
                  status: 'completed',
                  progress: 100,
                  finishedAt: new Date(),
                },
              });
              resolve(existing);
              return;
            }

            // Process success
            await this.prisma.generationJob.update({
              where: { id: jobId },
              data: { status: 'uploading', progress: 90 },
            });

            const finalVideoPath = path.join(taskStorageDir, 'final-1.mp4');
            const subtitlePath = path.join(taskStorageDir, 'subtitle.srt');
            const scriptJsonPath = path.join(taskStorageDir, 'script.json');

            if (!fs.existsSync(finalVideoPath)) {
              throw new Error(
                `Output video file final-1.mp4 not found at ${finalVideoPath}`,
              );
            }

            const thumbnailFilename = 'thumbnail.jpg';
            const thumbnailPath = path.join(taskStorageDir, thumbnailFilename);
            await new Promise<void>((res, rej) => {
              const timeout = setTimeout(() => {
                rej(
                  new Error('ffmpeg thumbnail generation timed out after 60s'),
                );
              }, 60000);
              ffmpeg(finalVideoPath)
                .screenshots({
                  count: 1,
                  timemarks: ['0'],
                  filename: thumbnailFilename,
                  folder: taskStorageDir,
                })
                .on('end', () => {
                  clearTimeout(timeout);
                  res();
                })
                .on('error', (err: Error) => {
                  clearTimeout(timeout);
                  rej(err);
                });
            });

            const s3VideoKey = `videos/${jobId}/final.mp4`;
            const s3ThumbnailKey = `videos/${jobId}/thumbnail.jpg`;
            const s3SubtitleKey = `videos/${jobId}/subtitle.srt`;
            const s3ScriptKey = `videos/${jobId}/script.json`;

            await this.storage.uploadFile(
              finalVideoPath,
              s3VideoKey,
              'video/mp4',
            );
            if (fs.existsSync(thumbnailPath)) {
              await this.storage.uploadFile(
                thumbnailPath,
                s3ThumbnailKey,
                'image/jpeg',
              );
            }
            if (fs.existsSync(subtitlePath)) {
              await this.storage.uploadFile(
                subtitlePath,
                s3SubtitleKey,
                'text/plain',
              );
            }
            if (fs.existsSync(scriptJsonPath)) {
              await this.storage.uploadFile(
                scriptJsonPath,
                s3ScriptKey,
                'application/json',
              );
            }

            let scriptContent = script;
            if (fs.existsSync(scriptJsonPath)) {
              try {
                const scriptData = JSON.parse(
                  fs.readFileSync(scriptJsonPath, 'utf8'),
                ) as ScriptFile;
                scriptContent = scriptData.script || script;
              } catch (error: unknown) {
                this.logger.error(
                  `Failed to parse script.json: ${getErrorMessage(error)}`,
                );
              }
            }

            const video = await this.prisma.video.create({
              data: {
                ideaId,
                jobId,
                title: subject,
                script: scriptContent,
                videoObjectKey: s3VideoKey,
                thumbnailObjectKey: fs.existsSync(thumbnailPath)
                  ? s3ThumbnailKey
                  : null,
                subtitleObjectKey: fs.existsSync(subtitlePath)
                  ? s3SubtitleKey
                  : null,
                metadataObjectKey: fs.existsSync(scriptJsonPath)
                  ? s3ScriptKey
                  : null,
                ratio: config.aspect_ratio || '9:16',
              },
            });

            await this.prisma.generationJob.update({
              where: { id: jobId },
              data: {
                status: 'completed',
                progress: 100,
                finishedAt: new Date(),
              },
            });

            if (fs.existsSync(taskStorageDir)) {
              fs.rmSync(taskStorageDir, { recursive: true, force: true });
            }

            resolve(video);
          } catch (error: unknown) {
            this.logger.error(
              `Post-processing failed: ${getErrorMessage(error)}`,
            );
            await this.prisma.generationJob.update({
              where: { id: jobId },
              data: {
                status: 'failed',
                errorMessage: getErrorMessage(error),
                finishedAt: new Date(),
              },
            });
            reject(error instanceof Error ? error : new Error(String(error)));
          }
        })();
      });
    });
  }
}

